@import url("https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&display=swap");

:root {
  --background: #02050a;
  --surface: #050a11;
  --surface-light: #08111c;
  --border: #123047;
  --border-bright: #075c86;
  --text: #f4f7fb;
  --muted: #8794a6;
  --cyan: #00c8ff;
  --cyan-dark: #007aa8;
  --orange: #ffab00;
  --orange-bright: #ffbd27;
}

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  background: var(--background);
  color: var(--text);
  font-family: "Inter", Arial, Helvetica, sans-serif;
}

a {
  color: inherit;
  text-decoration: none;
}

button,
a {
  -webkit-tap-highlight-color: transparent;
}

main {
  width: 100%;
  overflow: hidden;
}

/* =========================================================
   HEADER
========================================================= */

.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  width: 100%;
  background: rgba(2, 5, 10, 0.92);
  backdrop-filter: blur(16px);
  border-bottom: 1px solid #102031;
}

.nav-inner {
  width: min(1500px, calc(100% - 96px));
  min-height: 96px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 40px;
}

.brand {
  font-size: calc((25px) * var(--cl-font-scale, 1));
  font-weight: 900;
  letter-spacing: -1px;
  white-space: nowrap;
}

.main-nav {
  display: flex;
  align-items: center;
  gap: 34px;
}

.main-nav a {
  position: relative;
  color: #b7c0cd;
  font-size: calc((13px) * var(--cl-font-scale, 1));
  font-weight: 800;
  letter-spacing: 0.5px;
  transition: color 0.2s ease;
}

.main-nav a:hover,
.main-nav a.active {
  color: white;
}

.main-nav a.active::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: -15px;
  height: 3px;
  background: var(--orange);
  box-shadow: 0 0 16px rgba(255, 171, 0, 0.7);
}

.nav-button,
.primary-button,
.secondary-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 14px;
  min-height: 56px;
  padding: 0 28px;
  font-size: calc((13px) * var(--cl-font-scale, 1));
  font-weight: 900;
  letter-spacing: 0.4px;
  transition:
    transform 0.2s ease,
    box-shadow 0.2s ease,
    background 0.2s ease;
}

.nav-button {
  border: 1px solid var(--orange);
  color: var(--orange);
  border-radius: 13px;
}

.nav-button:hover {
  background: var(--orange);
  color: #050505;
}

.primary-button {
  background: var(--orange);
  color: #050505;
  border: 1px solid var(--orange);
  box-shadow: 0 12px 35px rgba(255, 171, 0, 0.12);
}

.primary-button:hover {
  transform: translateY(-3px);
  background: var(--orange-bright);
  box-shadow: 0 18px 45px rgba(255, 171, 0, 0.25);
}

.secondary-button {
  border: 1px solid var(--cyan);
  color: var(--cyan);
  background: transparent;
}

.secondary-button:hover {
  transform: translateY(-3px);
  background: rgba(0, 200, 255, 0.08);
  box-shadow: 0 15px 40px rgba(0, 200, 255, 0.12);
}

/* =========================================================
   HERO
========================================================= */

.hero-section {
  position: relative;
  padding: 78px 0 0;
  background:
    linear-gradient(rgba(0, 200, 255, 0.025) 1px, transparent 1px),
    linear-gradient(90deg, rgba(0, 200, 255, 0.025) 1px, transparent 1px),
    radial-gradient(circle at 75% 40%, rgba(0, 120, 255, 0.12), transparent 30%),
    #02050a;
  background-size: 48px 48px, 48px 48px, auto, auto;
}

.hero-grid {
  width: min(1500px, calc(100% - 96px));
  margin: 0 auto;
  min-height: 690px;
  display: grid;
  grid-template-columns: 0.9fr 1.1fr;
  align-items: center;
}

.hero-content {
  position: relative;
  z-index: 2;
  padding: 30px 0 70px;
}

.eyebrow,
.section-label {
  color: var(--cyan);
  font-size: calc((12px) * var(--cl-font-scale, 1));
  font-weight: 900;
  letter-spacing: 1.6px;
}

.eyebrow {
  display: inline-flex;
  padding: 15px 20px;
  border: 1px solid var(--cyan);
  margin-bottom: 38px;
}

.hero-content h1 {
  margin: 0;
  font-size: calc((clamp(65px, 7vw, 116px)) * var(--cl-font-scale, 1));
  line-height: 0.88;
  letter-spacing: -6px;
  font-weight: 900;
}

.hero-content h1 span,
h2 span {
  color: var(--orange);
}

.hero-description {
  max-width: 670px;
  margin: 40px 0 28px;
  color: #aab5c4;
  font-size: calc((18px) * var(--cl-font-scale, 1));
  line-height: 1.75;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 18px;
}

.hero-note {
  max-width: 610px;
  margin-top: 38px;
  color: #758294;
  font-size: calc((13px) * var(--cl-font-scale, 1));
  line-height: 1.7;
}

.hero-visual {
  position: relative;
  min-height: 680px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.visual-glow {
  position: absolute;
  width: 440px;
  height: 440px;
  border-radius: 50%;
  background: radial-gradient(
    circle,
    rgba(255, 151, 0, 0.42),
    rgba(0, 153, 255, 0.12) 45%,
    transparent 70%
  );
  filter: blur(12px);
}

.visual-orbit {
  position: absolute;
  border: 1px solid rgba(0, 200, 255, 0.65);
  border-radius: 50%;
  transform: rotateX(67deg);
}

.orbit-one {
  width: 570px;
  height: 220px;
}

.orbit-two {
  width: 440px;
  height: 170px;
}

.orbit-three {
  width: 320px;
  height: 125px;
}

.coin-wrapper {
  position: relative;
  z-index: 3;
  width: 430px;
  height: 430px;
}

.hero-coin {
  object-fit: contain;
  filter:
    drop-shadow(0 0 25px rgba(255, 145, 0, 0.35))
    drop-shadow(0 0 55px rgba(0, 170, 255, 0.12));
}

.floating-card {
  position: absolute;
  z-index: 4;
  min-width: 130px;
  padding: 18px 20px;
  border: 1px solid rgba(0, 200, 255, 0.6);
  background: rgba(3, 13, 22, 0.9);
  box-shadow: 0 0 30px rgba(0, 180, 255, 0.12);
  color: var(--cyan);
  font-size: calc((10px) * var(--cl-font-scale, 1));
  font-weight: 900;
  letter-spacing: 1px;
}

.floating-card span {
  display: block;
  margin-bottom: 7px;
  font-size: calc((18px) * var(--cl-font-scale, 1));
}

.card-learn {
  left: 4%;
  top: 22%;
}

.card-blockchain {
  right: 2%;
  top: 26%;
}

.card-security {
  left: 8%;
  bottom: 22%;
}

.card-community {
  right: 3%;
  bottom: 19%;
}

.hero-features {
  width: min(1320px, calc(100% - 96px));
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  border: 1px solid var(--border);
}

.feature-item {
  min-height: 150px;
  padding: 30px;
  display: flex;
  gap: 20px;
  border-right: 1px solid var(--border);
}

.feature-item:last-child {
  border-right: 0;
}

.feature-icon {
  flex: 0 0 auto;
  color: var(--cyan);
  font-size: calc((30px) * var(--cl-font-scale, 1));
  text-shadow: 0 0 20px rgba(0, 200, 255, 0.6);
}

.feature-item h3 {
  margin: 3px 0 12px;
  font-size: calc((13px) * var(--cl-font-scale, 1));
  font-weight: 900;
}

.feature-item p {
  margin: 0;
  color: var(--muted);
  font-size: calc((12px) * var(--cl-font-scale, 1));
  line-height: 1.7;
}

.stats-grid {
  width: min(1320px, calc(100% - 96px));
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  border: 1px solid var(--border);
  border-top: 0;
}

.stat {
  min-height: 115px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  border-right: 1px solid var(--border);
}

.stat:last-child {
  border-right: 0;
}

.stat strong {
  color: var(--orange);
  font-size: calc((26px) * var(--cl-font-scale, 1));
  font-weight: 900;
}

.stat span {
  margin-top: 8px;
  color: #8190a2;
  font-size: calc((10px) * var(--cl-font-scale, 1));
  font-weight: 800;
  letter-spacing: 1px;
}

/* =========================================================
   ABOUT BIRTHDAY MESSAGING
========================================================= */

.about-section,
.mission-section,
.paths-section,
.process-section,
.testimonials-section,
.faq-section {
  width: min(1320px, calc(100% - 96px));
  margin: 0 auto;
}

.about-section {
  padding: 150px 0;
}

.about-grid {
  margin-top: 50px;
  display: grid;
  grid-template-columns: 0.9fr 1.1fr;
  gap: 90px;
  align-items: center;
}

.about-content h2,
.mission-heading h2,
.paths-section h2,
.process-section h2,
.featured-content h2,
.security-content h2,
.testimonials-section h2,
.faq-heading h2,
.final-inner h2 {
  margin: 0;
  font-size: calc((clamp(45px, 5vw, 72px)) * var(--cl-font-scale, 1));
  line-height: 0.98;
  letter-spacing: -3px;
  font-weight: 900;
}

.about-content p {
  max-width: 650px;
  color: var(--muted);
  font-size: calc((16px) * var(--cl-font-scale, 1));
  line-height: 1.8;
}

.about-content .primary-button {
  margin-top: 20px;
}

/* =========================================================
   4K HEADQUARTERS IMAGE
========================================================= */

.about-visual {
  position: relative;
  width: 100%;
}

.about-image-frame {
  position: relative;
  width: 100%;
  aspect-ratio: 16 / 9;
  overflow: hidden;
  border: 1px solid var(--border);
  background: #02060b;
}

.about-image-frame img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center center;
}

.about-image {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center center;
  opacity: 0.92;
}

.image-overlay {
  position: absolute;
  inset: auto 30px 30px;
  z-index: 2;
  padding: 28px;
  background: rgba(2, 6, 11, 0.85);
  border: 1px solid rgba(0, 200, 255, 0.3);
}

.image-overlay span {
  display: block;
  color: var(--cyan);
  font-size: calc((10px) * var(--cl-font-scale, 1));
  font-weight: 900;
  letter-spacing: 1.5px;
}

.image-overlay strong {
  display: block;
  margin-top: 8px;
  font-size: calc((31px) * var(--cl-font-scale, 1));
  font-weight: 900;
}

.image-overlay small {
  display: block;
  margin-top: 8px;
  color: var(--orange);
  font-size: calc((10px) * var(--cl-font-scale, 1));
  font-weight: 900;
  letter-spacing: 1px;
}

.about-values {
  margin-top: 80px;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  border-top: 1px solid var(--border);
}

.about-values > div {
  padding: 35px 35px 0 0;
  border-right: 1px solid var(--border);
}

.about-values > div:not(:first-child) {
  padding-left: 35px;
}

.about-values > div:last-child {
  border-right: 0;
}

.about-values span,
.number,
.path-number {
  color: var(--cyan);
  font-size: calc((11px) * var(--cl-font-scale, 1));
  font-weight: 900;
  letter-spacing: 1px;
}

.about-values h3,
.mission-grid h3,
.process-step h3 {
  margin: 14px 0 10px;
  font-size: calc((14px) * var(--cl-font-scale, 1));
  font-weight: 900;
}

.about-values p,
.mission-grid p,
.process-step p {
  margin: 0;
  color: var(--muted);
  line-height: 1.7;
  font-size: calc((13px) * var(--cl-font-scale, 1));
}

/* =========================================================
   MISSION
========================================================= */

.mission-section {
  padding: 100px 0 150px;
}

.mission-heading {
  margin-top: 40px;
  display: grid;
  grid-template-columns: 1.2fr 0.8fr;
  gap: 80px;
  align-items: end;
}

.mission-heading p {
  color: var(--muted);
  font-size: calc((16px) * var(--cl-font-scale, 1));
  line-height: 1.8;
}

.mission-grid {
  margin-top: 75px;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  border: 1px solid var(--border);
}

.mission-grid article {
  min-height: 280px;
  padding: 35px;
  border-right: 1px solid var(--border);
}

.mission-grid article:last-child {
  border-right: 0;
}

.mission-grid h3 {
  margin-top: 60px;
  line-height: 1.4;
}

/* =========================================================
   LEARNING PATHS
   LANDING PAGE — 4K IMAGE CARDS
========================================================= */

.paths-section {
  width: min(1320px, calc(100% - 60px));
  margin: 0 auto;
  padding: 150px 0 170px;
}

.paths-section .section-heading-row {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 50px;
  margin-bottom: 70px;
}

.paths-section .section-label {
  margin-bottom: 28px;
}

.paths-section h2 {
  margin: 0;
  color: #ffffff;
  font-size: calc((clamp(58px, 7vw, 108px)) * var(--cl-font-scale, 1));
  font-weight: 900;
  line-height: 0.9;
  letter-spacing: -0.06em;
}

.paths-section h2 span {
  color: #ffb000;
}

.paths-section .text-link {
  flex-shrink: 0;
  color: #ffb000;
  text-decoration: none;
  font-size: calc((13px) * var(--cl-font-scale, 1));
  font-weight: 900;
  letter-spacing: 0.04em;
  white-space: nowrap;
  transition: color 180ms ease, transform 180ms ease;
}

.paths-section .text-link:hover {
  color: #ffffff;
  transform: translateX(4px);
}

.paths-section .paths-grid {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 14px;
}

.paths-section .path-card {
  position: relative;
  min-width: 0;
  min-height: 560px;
  padding: 16px;
  display: flex;
  flex-direction: column;
  color: #ffffff;
  text-decoration: none;
  background: linear-gradient(180deg, #06121c 0%, #020a11 100%);
  border: 1px solid rgba(0, 191, 255, 0.25);
  overflow: hidden;
  transition:
    transform 220ms ease,
    border-color 220ms ease,
    box-shadow 220ms ease;
}

.paths-section .path-card:hover {
  transform: translateY(-7px);
  border-color: rgba(0, 191, 255, 0.75);
  box-shadow: 0 25px 70px rgba(0, 170, 255, 0.14);
}

.paths-section .path-visual {
  position: relative;
  width: 100%;
  aspect-ratio: 1 / 1;
  margin-bottom: 28px;
  overflow: hidden;
  background: #02070c;
  border: 1px solid rgba(0, 191, 255, 0.24);
}

.paths-section .path-visual::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: linear-gradient(
    180deg,
    rgba(0, 0, 0, 0) 55%,
    rgba(0, 0, 0, 0.3) 100%
  );
}

.paths-section .path-visual img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;
  image-rendering: auto;
  transition: transform 500ms cubic-bezier(0.2, 0.7, 0.2, 1);
}

.paths-section .path-card:hover .path-visual img {
  transform: scale(1.055);
}

.paths-section .path-number {
  margin-bottom: 12px;
  color: #00bfff;
  font-size: calc((12px) * var(--cl-font-scale, 1));
  font-weight: 900;
  letter-spacing: 0.08em;
}

.paths-section .path-card h3 {
  margin: 0 0 14px;
  color: #ffffff;
  font-size: calc((20px) * var(--cl-font-scale, 1));
  font-weight: 900;
  line-height: 1;
  letter-spacing: -0.02em;
}

.paths-section .path-card p {
  margin: 0;
  color: rgba(255, 255, 255, 0.72);
  font-size: calc((13px) * var(--cl-font-scale, 1));
  line-height: 1.65;
}

.paths-section .path-card strong {
  margin-top: auto;
  padding-top: 30px;
  color: #ffb000;
  font-size: calc((11px) * var(--cl-font-scale, 1));
  font-weight: 900;
  letter-spacing: 0.05em;
}

@media (max-width: 1150px) {
  .paths-section {
    width: calc(100% - 48px);
  }

  .paths-section .paths-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .paths-section .path-card {
    min-height: 540px;
  }
}

@media (max-width: 850px) {
  .paths-section {
    width: calc(100% - 30px);
    padding-top: 100px;
    padding-bottom: 110px;
  }

  .paths-section .section-heading-row {
    display: block;
    margin-bottom: 50px;
  }

  .paths-section .text-link {
    display: inline-block;
    margin-top: 28px;
  }

  .paths-section h2 {
    font-size: calc((clamp(50px, 11vw, 82px)) * var(--cl-font-scale, 1));
  }

  .paths-section .paths-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 560px) {
  .paths-section {
    width: calc(100% - 30px);
    padding-top: 80px;
    padding-bottom: 90px;
  }

  .paths-section h2 {
    font-size: calc((48px) * var(--cl-font-scale, 1));
  }

  .paths-section .paths-grid {
    grid-template-columns: 1fr;
  }

  .paths-section .path-card {
    min-height: auto;
  }

  .paths-section .path-visual {
    aspect-ratio: 16 / 10;
  }
}

/* =========================================================
   PROCESS
========================================================= */

.process-section {
  padding: 80px 0 150px;
}

.process-section h2 {
  margin-top: 25px;
}

.process-grid {
  margin-top: 70px;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
}

.process-step {
  min-height: 250px;
  padding: 30px;
  border-top: 1px solid var(--border);
  border-right: 1px solid var(--border);
}

.process-step:last-child {
  border-right: 0;
}

.step-number {
  width: 52px;
  height: 52px;
  border: 1px solid var(--cyan);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--cyan);
  font-weight: 900;
  box-shadow: 0 0 20px rgba(0, 200, 255, 0.1);
}

.process-step h3 {
  margin-top: 35px;
}

/* =========================================================
   FEATURED
========================================================= */

.featured-section {
  min-height: 670px;
  display: grid;
  grid-template-columns: 1.2fr 0.8fr;
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
  background: #03070c;
}

.featured-image {
  position: relative;
  min-height: 670px;
  overflow: hidden;
  background:
    radial-gradient(
      circle at 50% 50%,
      rgba(0, 150, 255, 0.18),
      transparent 30%
    ),
    #02060b;
}

.featured-grid {
  position: absolute;
  inset: 0;
  opacity: 0.3;
  background:
    linear-gradient(rgba(0, 200, 255, 0.06) 1px, transparent 1px),
    linear-gradient(90deg, rgba(0, 200, 255, 0.06) 1px, transparent 1px);
  background-size: 55px 55px;
}

.featured-orb {
  position: absolute;
  border-radius: 50%;
  border: 1px solid var(--cyan);
  box-shadow: 0 0 40px rgba(0, 200, 255, 0.15);
}

.orb-one {
  width: 500px;
  height: 500px;
  left: 15%;
  top: 12%;
}

.orb-two {
  width: 350px;
  height: 350px;
  left: 27%;
  top: 25%;
}

.featured-center {
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  width: 230px;
  height: 230px;
  border-radius: 50%;
  border: 1px solid var(--cyan);
  background: rgba(2, 10, 17, 0.95);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  box-shadow:
    0 0 40px rgba(0, 200, 255, 0.25),
    inset 0 0 40px rgba(0, 200, 255, 0.08);
}

.featured-center span {
  color: var(--cyan);
  font-size: calc((10px) * var(--cl-font-scale, 1));
  font-weight: 900;
  letter-spacing: 2px;
}

.featured-center strong {
  margin-top: 8px;
  font-size: calc((40px) * var(--cl-font-scale, 1));
  font-weight: 900;
}

.featured-center small {
  color: var(--orange);
  margin-top: 5px;
  font-weight: 900;
  letter-spacing: 2px;
}

.featured-cube {
  position: absolute;
  padding: 22px 18px;
  border: 1px solid var(--cyan);
  background: rgba(2, 12, 20, 0.85);
  color: var(--cyan);
  font-size: calc((9px) * var(--cl-font-scale, 1));
  font-weight: 900;
  box-shadow: 0 0 30px rgba(0, 200, 255, 0.12);
}

.cube-one {
  left: 13%;
  top: 25%;
}

.cube-two {
  right: 13%;
  top: 21%;
}

.cube-three {
  left: 19%;
  bottom: 19%;
}

.featured-content {
  padding: 90px 70px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  border-left: 1px solid var(--border);
}

.featured-content h2 {
  margin-top: 25px;
}

.featured-content p {
  color: var(--muted);
  line-height: 1.8;
  font-size: calc((15px) * var(--cl-font-scale, 1));
}

.featured-content .primary-button {
  align-self: flex-start;
  margin-top: 18px;
}

/* =========================================================
   SECURITY
========================================================= */

.security-section {
  width: min(1320px, calc(100% - 96px));
  margin: 0 auto;
  padding: 150px 0;
  display: grid;
  grid-template-columns: 0.9fr 1.1fr;
  gap: 80px;
  align-items: center;
}

.security-content h2 {
  margin-top: 25px;
}

.security-content p {
  max-width: 650px;
  color: var(--muted);
  line-height: 1.8;
  font-size: calc((15px) * var(--cl-font-scale, 1));
}

.security-content .secondary-button {
  margin-top: 20px;
}

.security-visual {
  position: relative;
  height: 500px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.security-ring {
  position: absolute;
  border: 1px solid rgba(0, 200, 255, 0.45);
  border-radius: 50%;
}

.ring-one {
  width: 470px;
  height: 470px;
}

.ring-two {
  width: 350px;
  height: 350px;
}

.ring-three {
  width: 230px;
  height: 230px;
}

.security-lock {
  position: relative;
  z-index: 2;
  width: 210px;
  height: 210px;
  border: 1px solid var(--cyan);
  background: rgba(3, 12, 20, 0.94);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  box-shadow: 0 0 50px rgba(0, 200, 255, 0.16);
}

.security-lock span {
  color: var(--cyan);
  font-size: calc((52px) * var(--cl-font-scale, 1));
}

.security-lock strong {
  margin-top: 8px;
  font-size: calc((18px) * var(--cl-font-scale, 1));
  font-weight: 900;
}

.security-lock small {
  margin-top: 8px;
  color: var(--orange);
  font-size: calc((8px) * var(--cl-font-scale, 1));
  font-weight: 900;
  letter-spacing: 1px;
}

/* =========================================================
   TESTIMONIALS
========================================================= */

.testimonials-section {
  padding: 100px 0 150px;
}

.testimonial-grid {
  margin-top: 55px;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 15px;
}

.testimonial-card {
  min-height: 320px;
  padding: 35px;
  border: 1px solid var(--border);
  background: linear-gradient(
    160deg,
    rgba(6, 17, 28, 0.8),
    rgba(2, 7, 13, 0.95)
  );
}

.quote {
  color: var(--cyan);
  font-size: calc((50px) * var(--cl-font-scale, 1));
  line-height: 0.7;
}

.testimonial-card p {
  min-height: 130px;
  color: #a8b4c4;
  font-size: calc((14px) * var(--cl-font-scale, 1));
  line-height: 1.8;
}

.testimonial-author {
  display: flex;
  flex-direction: column;
  border-top: 1px solid var(--border);
  padding-top: 20px;
}

.testimonial-author strong {
  font-size: calc((11px) * var(--cl-font-scale, 1));
  letter-spacing: 1px;
}

.testimonial-author span {
  margin-top: 6px;
  color: var(--muted);
  font-size: calc((11px) * var(--cl-font-scale, 1));
}

/* =========================================================
   FAQ
========================================================= */

.faq-section {
  padding: 80px 0 150px;
  display: grid;
  grid-template-columns: 0.8fr 1.2fr;
  gap: 100px;
}

.faq-heading h2 {
  margin-top: 25px;
}

.faq-list {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.faq-list details {
  border: 1px solid var(--border);
  background: rgba(4, 11, 18, 0.8);
}

.faq-list summary {
  min-height: 75px;
  padding: 0 25px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  cursor: pointer;
  list-style: none;
  font-size: calc((13px) * var(--cl-font-scale, 1));
  font-weight: 800;
}

.faq-list summary::-webkit-details-marker {
  display: none;
}

.faq-list summary span {
  color: var(--cyan);
  font-size: calc((25px) * var(--cl-font-scale, 1));
  font-weight: 400;
}

.faq-list details[open] summary span {
  transform: rotate(45deg);
}

.faq-list p {
  margin: 0;
  padding: 0 25px 25px;
  color: var(--muted);
  line-height: 1.7;
  font-size: calc((13px) * var(--cl-font-scale, 1));
}

/* =========================================================
   FINAL
========================================================= */

.final-section {
  padding: 150px 30px;
  border-top: 1px solid var(--border);
  background:
    radial-gradient(
      circle at 50% 40%,
      rgba(0, 160, 255, 0.12),
      transparent 35%
    ),
    #02060b;
  text-align: center;
}

.final-inner {
  max-width: 900px;
  margin: 0 auto;
}

.final-inner h2 {
  margin-top: 25px;
}

.final-inner p {
  max-width: 600px;
  margin: 35px auto;
  color: var(--muted);
  line-height: 1.8;
}

.large-button {
  min-width: 220px;
}

/* =========================================================
   FOOTER
========================================================= */

.site-footer {
  padding: 80px max(48px, calc((100vw - 1320px) / 2)) 30px;
  border-top: 1px solid var(--border);
  background: #010408;
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 70px;
}

.footer-brand p {
  max-width: 390px;
  color: var(--muted);
  line-height: 1.7;
  font-size: calc((12px) * var(--cl-font-scale, 1));
}

.footer-tagline {
  display: inline-block;
  margin-top: 18px;
  color: var(--cyan);
  font-size: calc((9px) * var(--cl-font-scale, 1));
  font-weight: 900;
  letter-spacing: 2px;
}

.footer-column {
  display: flex;
  flex-direction: column;
  gap: 13px;
}

.footer-column h4 {
  margin: 0 0 10px;
  color: white;
  font-size: calc((11px) * var(--cl-font-scale, 1));
  letter-spacing: 1px;
}

.footer-column a,
.footer-column span {
  color: var(--muted);
  font-size: calc((11px) * var(--cl-font-scale, 1));
}

.footer-column a:hover {
  color: var(--cyan);
}

.footer-bottom {
  margin-top: 65px;
  padding-top: 25px;
  border-top: 1px solid var(--border);
  display: flex;
  justify-content: space-between;
  gap: 30px;
  color: #536171;
  font-size: calc((10px) * var(--cl-font-scale, 1));
  letter-spacing: 0.5px;
}

/* =========================================================
   TABLET
========================================================= */

@media (max-width: 1150px) {
  .main-nav {
    gap: 17px;
  }

  .main-nav a {
    font-size: calc((11px) * var(--cl-font-scale, 1));
  }

  .nav-inner,
  .hero-grid,
  .hero-features,
  .stats-grid,
  .about-section,
  .mission-section,
  .paths-section,
  .process-section,
  .security-section,
  .testimonials-section,
  .faq-section {
    width: min(100% - 48px, 1320px);
  }

  .paths-grid {
    grid-template-columns: repeat(3, 1fr);
  }

  .mission-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .mission-grid article:nth-child(2) {
    border-right: 0;
  }

  .mission-grid article:nth-child(1),
  .mission-grid article:nth-child(2) {
    border-bottom: 1px solid var(--border);
  }
}

/* =========================================================
   MOBILE
========================================================= */

@media (max-width: 850px) {
  .site-header {
    position: relative;
  }

  .nav-inner {
    width: calc(100% - 30px);
    min-height: 78px;
  }

  .brand {
    font-size: calc((19px) * var(--cl-font-scale, 1));
  }

  .main-nav {
    display: none;
  }

  .nav-button {
    min-height: 44px;
    padding: 0 15px;
    font-size: calc((10px) * var(--cl-font-scale, 1));
  }

  .hero-section {
    padding-top: 35px;
  }

  .hero-grid {
    width: calc(100% - 30px);
    display: block;
  }

  .hero-content {
    padding-bottom: 0;
  }

  .hero-content h1 {
    font-size: calc((clamp(58px, 17vw, 90px)) * var(--cl-font-scale, 1));
    letter-spacing: -4px;
  }

  .hero-description {
    font-size: calc((15px) * var(--cl-font-scale, 1));
  }

  .hero-visual {
    min-height: 480px;
    margin-top: -20px;
  }

  .coin-wrapper {
    width: 330px;
    height: 330px;
  }

  .visual-orbit {
    transform: rotateX(67deg);
  }

  .orbit-one {
    width: 400px;
    height: 150px;
  }

  .orbit-two {
    width: 310px;
    height: 120px;
  }

  .orbit-three {
    width: 230px;
    height: 90px;
  }

  .floating-card {
    min-width: auto;
    padding: 12px;
    font-size: calc((8px) * var(--cl-font-scale, 1));
  }

  .card-learn {
    left: 0;
    top: 18%;
  }

  .card-blockchain {
    right: 0;
    top: 22%;
  }

  .card-security {
    left: 3%;
    bottom: 17%;
  }

  .card-community {
    right: 0;
    bottom: 14%;
  }

  .hero-features,
  .stats-grid {
    width: calc(100% - 30px);
  }

  .hero-features {
    grid-template-columns: 1fr;
  }

  .feature-item {
    border-right: 0;
    border-bottom: 1px solid var(--border);
  }

  .feature-item:last-child {
    border-bottom: 0;
  }

  .stats-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .stat {
    border-bottom: 1px solid var(--border);
  }

  .stat:nth-child(2n) {
    border-right: 0;
  }

  .stat:last-child {
    grid-column: 1 / -1;
    border-right: 0;
  }

  .about-section,
  .mission-section,
  .paths-section,
  .process-section,
  .security-section,
  .testimonials-section,
  .faq-section {
    width: calc(100% - 30px);
    padding-top: 90px;
    padding-bottom: 90px;
  }

  .about-grid,
  .mission-heading,
  .security-section,
  .faq-section {
    grid-template-columns: 1fr;
    gap: 45px;
  }

  .about-content h2,
  .mission-heading h2,
  .paths-section h2,
  .process-section h2,
  .featured-content h2,
  .security-content h2,
  .testimonials-section h2,
  .faq-heading h2,
  .final-inner h2 {
    font-size: calc((45px) * var(--cl-font-scale, 1));
    letter-spacing: -2px;
  }

  /*
    Keep the headquarters image at its natural 16:9
    proportion on mobile as well.
  */
  .about-image-frame {
    width: 100%;
    aspect-ratio: 16 / 9;
    min-height: 0;
  }

  .about-image {
    width: 100%;
    height: 100%;
    object-fit: cover;
  }

  .about-values {
    grid-template-columns: 1fr;
  }

  .about-values > div,
  .about-values > div:not(:first-child) {
    padding: 30px 0;
    border-right: 0;
    border-bottom: 1px solid var(--border);
  }

  .mission-grid {
    grid-template-columns: 1fr;
  }

  .mission-grid article,
  .mission-grid article:nth-child(2) {
    border-right: 0;
    border-bottom: 1px solid var(--border);
  }

  .mission-grid article:last-child {
    border-bottom: 0;
  }

  .paths-grid {
    grid-template-columns: 1fr;
  }

  .path-card {
    min-height: 390px;
  }

  .section-heading-row {
    display: block;
  }

  .section-heading-row .text-link {
    display: inline-block;
    margin-top: 25px;
  }

  .process-grid {
    grid-template-columns: 1fr;
  }

  .process-step {
    border-right: 0;
    border-bottom: 1px solid var(--border);
  }

  .featured-section {
    display: block;
  }

  .featured-image {
    min-height: 470px;
  }

  .featured-content {
    padding: 70px 25px;
    border-left: 0;
    border-top: 1px solid var(--border);
  }

  .security-visual {
    height: 390px;
  }

  .ring-one {
    width: 350px;
    height: 350px;
  }

  .ring-two {
    width: 270px;
    height: 270px;
  }

  .ring-three {
    width: 190px;
    height: 190px;
  }

  .testimonial-grid {
    grid-template-columns: 1fr;
  }

  .footer-grid {
    grid-template-columns: 1fr 1fr;
    gap: 45px;
  }

  .footer-brand {
    grid-column: 1 / -1;
  }

  .footer-bottom {
    flex-direction: column;
  }
}

@media (max-width: 500px) {
  .nav-button {
    display: none;
  }

  .hero-actions {
    flex-direction: column;
  }

  .hero-actions a {
    width: 100%;
  }

  .hero-visual {
    min-height: 400px;
  }

  .coin-wrapper {
    width: 280px;
    height: 280px;
  }

  .floating-card {
    transform: scale(0.8);
  }

  .eyebrow {
    font-size: calc((9px) * var(--cl-font-scale, 1));
  }

  /*
    Headquarters image remains 16:9.
    Do NOT use a fixed height here.
  */
  .about-image-frame {
    width: 100%;
    aspect-ratio: 16 / 9;
    min-height: 0;
  }

  .about-image {
    width: 100%;
    height: 100%;
    object-fit: cover;
  }

  .featured-center {
    width: 180px;
    height: 180px;
  }

  .featured-center strong {
    font-size: calc((30px) * var(--cl-font-scale, 1));
  }

  .footer-grid {
    grid-template-columns: 1fr;
  }

  .footer-brand {
    grid-column: auto;
  }

  .site-footer {
    padding-left: 25px;
    padding-right: 25px;
  }
}

/* =========================================================
   CHAINLAB LEARNING HUB
========================================================= */

.learnPage {
  min-height: 100vh;
  background:
    linear-gradient(
      rgba(0, 200, 255, 0.025) 1px,
      transparent 1px
    ),
    linear-gradient(
      90deg,
      rgba(0, 200, 255, 0.025) 1px,
      transparent 1px
    ),
    #02060b;
  background-size: 72px 72px;
  color: #f5f7fa;
}

.learnNav {
  height: 78px;
  padding: 0 4%;
  display: flex;
  align-items: center;
  justify-content: space-between;
