.hero-section {
  position: relative;
  width: calc(100% - 80px);
  max-width: 1600px;
  margin: 70px auto 100px;
  padding: 0;
  overflow: hidden;

  border: 1px solid rgba(0, 174, 255, 0.22);
  border-radius: 32px;

  background:
    radial-gradient(
      circle at 76% 40%,
      rgba(0, 132, 255, 0.25),
      transparent 34%
    ),
    radial-gradient(
      circle at 55% 72%,
      rgba(0, 91, 220, 0.18),
      transparent 38%
    ),
    linear-gradient(
      135deg,
      #020914 0%,
      #03152d 42%,
      #041d3d 70%,
      #020914 100%
    );

  box-shadow:
    0 30px 100px rgba(0, 0, 0, 0.5),
    0 0 100px rgba(0, 110, 255, 0.08),
    inset 0 1px 0 rgba(255, 255, 255, 0.035);
}

/* Technical grid */

.hero-section::before {
  content: "";
  position: absolute;
  inset: 0;

  background-image:
    linear-gradient(
      rgba(0, 174, 255, 0.045) 1px,
      transparent 1px
    ),
    linear-gradient(
      90deg,
      rgba(0, 174, 255, 0.045) 1px,
      transparent 1px
    );

  background-size: 52px 52px;

  opacity: 0.7;
  pointer-events: none;
}

/* Atmospheric blue glow */

.hero-section::after {
  content: "";
  position: absolute;

  width: 650px;
  height: 650px;

  right: 2%;
  top: 5%;

  background: radial-gradient(
    circle,
    rgba(0, 153, 255, 0.16),
    transparent 68%
  );

  filter: blur(30px);

  pointer-events: none;
}

/* Keep hero content above background effects */

.hero-section > * {
  position: relative;
  z-index: 2;
}


