/* =========================================================
   MOBILE BREAKPOINT
   ========================================================= */

@media (max-width: 1000px) {
  .site-header .main-nav,
  .site-header .nav-button {
    display: none !important;
  }

  .site-header .nav-inner {
    position: relative;
  }

  .mobile-menu-button {
    display: block;
    margin-left: auto;

    position: relative;
    z-index: 10000;
  }
}


@media (min-width: 1001px) {
  .mobile-navigation {
    display: none !important;
  }

  .mobile-menu-button {
    display: none !important;
  }
}


/* =========================================================
   SMALL SCREENS
   ========================================================= */

@media (max-width: 600px) {
  .chainlab-tools {
    right: 14px;
    bottom: 14px;
    gap: 7px;
  }

  .chainlab-tool-button,
  .chainlab-chat-button {
    height: 44px;
    min-width: 44px;
    padding: 0 11px;
  }

  .chainlab-chat-button {
    min-width: 58px;
  }

  .chainlab-chat-overlay {
    padding: 0;
  }

  .chainlab-chatbox {
    width: 100%;
    height: 100%;
    max-height: none;

    border-radius: 0;
  }

  .mobile-navigation {
    padding: 20px;
  }

  .mobile-navigation-links a {
    font-size: calc((28px) * var(--cl-font-scale, 1));
    padding: 18px 0;
  }
}


/* =========================================================
   REDUCED MOTION
   ========================================================= */

@media (prefers-reduced-motion: reduce) {
  .chainlab-tool-button,
  .chainlab-chat-button,
  .mobile-navigation,
  .mobile-navigation-links a,
  .mobile-menu-button span {
    transition: none !important;
  }
}

