  color: #ffffff;

  font-size: calc((clamp(28px, 8vw, 52px)) * var(--cl-font-scale, 1));

  font-weight: 800;

  letter-spacing: -0.04em;

  text-decoration: none;

  transition:
    color 0.2s ease,
    padding-left 0.2s ease;
}

.mobile-navigation-links a span {
  width: 30px;

  color: #00d9ff;

