  min-width: 118px;
  padding: 0 14px;

  display: flex;
  align-items: center;
  justify-content: center;
  gap: 9px;

  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 12px;

  background: rgba(10, 17, 28, 0.96);
  color: #ffffff;

  font-family: inherit;
  font-size: calc((11px) * var(--cl-font-scale, 1));
  font-weight: 800;
  letter-spacing: 0.08em;

  cursor: pointer;

  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);

  transition:
    background 0.2s ease,
    border-color 0.2s ease,
    transform 0.2s ease;
}

.device-preview-button:hover,
.device-preview-button-open {
  background: #111b2a;
  border-color: rgba(0, 217, 255, 0.45);
}

.device-preview-button:hover {
  transform: translateY(-1px);
}

.device-preview-icon {
  font-size: calc((15px) * var(--cl-font-scale, 1));
  color: #00d9ff;
}

.device-preview-chevron {
  margin-left: 2px;
  font-size: calc((8px) * var(--cl-font-scale, 1));
  color: rgba(255, 255, 255, 0.6);
}

.device-preview-menu {
  position: absolute;
  top: calc(100% + 8px);
  right: 0;

  width: 245px;

  padding: 8px;

  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 12px;

  background: rgba(8, 13, 21, 0.98);

  box-shadow:
    0 20px 50px rgba(0, 0, 0, 0.45),
    0 0 30px rgba(0, 217, 255, 0.04);

  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
}

.device-preview-option {
  width: 100%;
  min-height: 46px;

  padding: 0 12px;

  display: flex;
  align-items: center;
  gap: 12px;

  border: 0;
  border-radius: 8px;

  background: transparent;
  color: #b8c4d3;

  font-family: inherit;
  font-size: calc((13px) * var(--cl-font-scale, 1));
  font-weight: 600;

  text-align: left;

  cursor: pointer;

  transition:
    background 0.2s ease,
    color 0.2s ease;
}

.device-preview-option:hover {
  background: rgba(0, 217, 255, 0.07);
  color: #ffffff;
}

.device-preview-option-active {
  background: rgba(0, 217, 255, 0.1);
  color: #ffffff;
}

.device-option-icon {
  width: 22px;

  display: inline-flex;
  justify-content: center;

  color: #00d9ff;
  font-size: calc((17px) * var(--cl-font-scale, 1));
}

/* =========================================================
   DEVICE PREVIEW SIZES
   ========================================================= */

/*
   Current screen size
   Normal website behavior.
*/

html[data-device-preview="current"] body {
  width: 100%;
  max-width: none;
  margin: 0;
}

/*
   Mobile
   390px phone-style viewport.
*/

html[data-device-preview="mobile"] body {
  width: 390px;
  max-width: 390px;
  min-height: 100vh;
  margin: 0 auto;

  overflow-x: hidden;

  border-left: 1px solid rgba(0, 217, 255, 0.18);
  border-right: 1px solid rgba(0, 217, 255, 0.18);

  box-shadow:
    0 0 60px rgba(0, 217, 255, 0.08);
}

/*
   Tablet
   768px tablet-style viewport.
*/

html[data-device-preview="tablet"] body {
  width: 768px;
  max-width: 768px;
  min-height: 100vh;
  margin: 0 auto;

  overflow-x: hidden;

  border-left: 1px solid rgba(0, 217, 255, 0.18);
  border-right: 1px solid rgba(0, 217, 255, 0.18);

  box-shadow:
    0 0 60px rgba(0, 217, 255, 0.08);
}

/*
   Preview background outside the device.
*/

html[data-device-preview="mobile"],
html[data-device-preview="tablet"] {
  background: #010308;
}

html[data-device-preview="mobile"] body,
html[data-device-preview="tablet"] body {
  background: #02050a;
}

/*
   Keep the preview usable on small computer screens.
*/

@media (max-width: 820px) {
  html[data-device-preview="tablet"] body {
    width: 100%;
    max-width: 768px;
  }
}

@media (max-width: 430px) {
  html[data-device-preview="mobile"] body {
    width: 100%;
    max-width: 390px;
  }
}

/*
   Device control remains outside the simulated viewport.
*/

html[data-device-preview="mobile"] .device-preview-control,
html[data-device-preview="tablet"] .device-preview-control {
  position: fixed;
  top: 20px;
  right: 20px;
}

/* =========================================================
   CHAINLAB GLOBAL LIGHT / DARK THEME
   ========================================================= */

/* Default dark theme */
:root {
  --cl-bg: #02050a;
  --cl-surface: #07101b;
  --cl-text: #ffffff;
  --cl-muted: #9aa8bd;
  --cl-border: rgba(255, 255, 255, 0.12);
  --cl-accent: #00d9ff;
}

/* Light theme */
html[data-theme="light"] {
  --cl-bg: #f5f7fa;
  --cl-surface: #ffffff;
  --cl-text: #111827;
  --cl-muted: #526174;
  --cl-border: rgba(17, 24, 39, 0.15);
  --cl-accent: #007f9e;
}

/* Main page background and default text */
html[data-theme="light"] body {
  background: var(--cl-bg) !important;
  color: var(--cl-text) !important;
}

/* Apply the theme to common page sections */
html[data-theme="light"] main,
html[data-theme="light"] section {
  background-color: transparent;
  color: var(--cl-text);
}

/* Header and navigation */
html[data-theme="light"] .site-header {
  background: rgba(255, 255, 255, 0.96) !important;
  border-color: var(--cl-border) !important;
}

html[data-theme="light"] .site-header a {
  color: var(--cl-text);
}

/* Common cards and panels */
html[data-theme="light"] article,
html[data-theme="light"] .audience-card,
html[data-theme="light"] .progressPanel,
html[data-theme="light"] .searchPanel,
html[data-theme="light"] .learning-card,
html[data-theme="light"] .lesson-card,
html[data-theme="light"] .quiz-card {
  background: var(--cl-surface) !important;
  color: var(--cl-text) !important;
  border-color: var(--cl-border) !important;
}

/* Headings and regular text */
html[data-theme="light"] h1,
html[data-theme="light"] h2,
html[data-theme="light"] h3,
html[data-theme="light"] h4,
html[data-theme="light"] p,
html[data-theme="light"] li,
html[data-theme="light"] label {
  color: var(--cl-text);
}

/* Muted text */
html[data-theme="light"] .hero-description,
html[data-theme="light"] .section-description,
html[data-theme="light"] .audience-card p,
html[data-theme="light"] .section-label {
  color: var(--cl-muted);
}

/* Inputs and search boxes */
html[data-theme="light"] input,
html[data-theme="light"] textarea,
html[data-theme="light"] select {
  background: #ffffff !important;
  color: #111827 !important;
  border-color: var(--cl-border) !important;
}

html[data-theme="light"] input::placeholder,
html[data-theme="light"] textarea::placeholder {
  color: #6b7280 !important;
}

/* Buttons */
html[data-theme="light"] button {
  border-color: var(--cl-border);
}

/* Keep ChainLab accent elements visible */
html[data-theme="light"] .hero-content h1 span,
html[data-theme="light"] .audience-heading h2 span,
html[data-theme="light"] .security-content h2,
html[data-theme="light"] .security-content h2 span {
  color: var(--cl-accent) !important;
}

/* Footer */
html[data-theme="light"] footer {
  background: #eef2f6 !important;
  color: var(--cl-text) !important;
  border-color: var(--cl-border) !important;
}

/* Smooth theme change */
body,
.site-header,
article,
input,
textarea,
select {
  transition:
    background-color 0.2s ease,
    color 0.2s ease,
    border-color 0.2s ease;
}

/* =========================================================
   CHAINLAB GLOBAL FONT SIZE CONTROL
   ========================================================= */

html {
  font-size: calc(16px * var(--cl-font-scale, 1));
}
/* =========================================
