  color: #f1f5f9;
}

html[data-theme="dark"] .language-selector select,
html.dark .language-selector select {
  color: #f1f5f9;
}

html[data-theme="dark"] .language-selector::after,
html.dark .language-selector::after {
  color: #f1f5f9;
}

html[data-theme="dark"] .nav-search-button,
html.dark .nav-search-button {
  color: #f1f5f9;
}

html[data-theme="dark"] .nav-login-button,
html.dark .nav-login-button {
  background: #111827;

  border-color: #64748b;

  color: #ffffff;
}

html[data-theme="dark"] .nav-login-button:hover,
html.dark .nav-login-button:hover {
  border-color: #70a7ff;
  color: #70a7ff;
}


