    #02070d;
  color: #f7fbff;
  overflow: hidden;
}

.auth-topbar {
  position: relative;
  z-index: 20;
  height: 76px;
  display: flex;
  align-items: center;
  gap: 48px;
  padding: 0 5.8vw;
  border-bottom: 1px solid rgba(48, 160, 255, 0.18);
  background: rgba(2, 7, 13, 0.84);
  backdrop-filter: blur(18px);
}

.auth-brand {
  flex: 0 0 auto;
  color: #fff;
  font-size: 30px;
  font-weight: 800;
  letter-spacing: -1.4px;
  text-decoration: none;
}

.auth-brand span {
  color: #19d8ff;
}

.auth-nav {
  display: flex;
  align-items: center;
  gap: 42px;
  margin-left: auto;
}

.auth-nav a {
  color: #c4d1df;
  font-size: 14px;
  font-weight: 500;
  letter-spacing: 0.02em;
