}

.auth-nav a:hover {
  color: #19d8ff;
}

.auth-top-actions {
  display: flex;
  align-items: center;
  gap: 20px;
}

.auth-icon-button {
  width: 32px;
  height: 32px;
  display: grid;
  place-items: center;
