}

.auth-get-started {
  min-width: 148px;
  height: 45px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid #10cfff;
  border-radius: 11px;
  color: #fff;
  font-size: 13px;
  font-weight: 700;
