.auth-get-started:hover {
  background: rgba(16, 207, 255, 0.1);
  box-shadow: 0 0 30px rgba(16, 207, 255, 0.2);
}

.auth-shell {
  position: relative;
  min-height: calc(100vh - 76px);
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(480px, 610px);
  gap: clamp(45px, 7vw, 115px);
  align-items: center;
  max-width: 1450px;
  margin: 0 auto;
  padding: 52px 5.8vw 65px;
}

.auth-background-grid {
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 0.24;
  background-image:
    linear-gradient(rgba(35, 152, 255, 0.075) 1px, transparent 1px),
    linear-gradient(90deg, rgba(35, 152, 255, 0.075) 1px, transparent 1px);
  background-size: 64px 64px;
  mask-image: linear-gradient(to bottom, transparent, black 15%, black 82%, transparent);
}

.auth-glow {
  position: absolute;
  pointer-events: none;
  border-radius: 999px;
  filter: blur(80px);
}

.auth-glow-one {
  width: 420px;
  height: 420px;
  left: 7%;
  top: 20%;
  background: rgba(0, 109, 255, 0.08);
}

.auth-glow-two {
  width: 320px;
  height: 320px;
  right: 19%;
  bottom: 10%;
  background: rgba(0, 229, 255, 0.06);
}

.auth-hero {
  position: relative;
  z-index: 2;
  min-width: 0;
  padding-left: clamp(0px, 2vw, 26px);
}

.auth-eyebrow {
  margin-bottom: 25px;
  color: #2edaff;
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.32em;
}

.auth-hero h1 {
  margin: 0;
  color: #f7fbff;
  font-size: clamp(58px, 5.8vw, 88px);
  line-height: 0.96;
  font-weight: 800;
  letter-spacing: -0.055em;
}

.auth-hero h1 span {
  color: #12d8ff;
  text-shadow: 0 0 30px rgba(18, 216, 255, 0.15);
}

.auth-hero-copy {
  max-width: 600px;
  margin: 27px 0 0;
  color: #b9c8d7;
  font-size: 19px;
  line-height: 1.6;
}

.auth-network {
  position: relative;
  height: 285px;
  max-width: 690px;
  margin: 8px 0 -2px;
}

.auth-network-core {
  position: absolute;
  left: 53%;
  top: 52%;
  width: 170px;
  height: 145px;
  transform: translate(-50%, -50%) perspective(500px) rotateX(12deg) rotateZ(-1deg);
  display: grid;
  place-items: center;
  border: 1px solid rgba(29, 205, 255, 0.8);
  border-radius: 10px;
  background:
    linear-gradient(145deg, rgba(15, 103, 169, 0.34), rgba(2, 17, 30, 0.8)),
    rgba(4, 18, 31, 0.8);
  box-shadow:
    0 0 28px rgba(12, 203, 255, 0.24),
    inset 0 0 35px rgba(9, 137, 255, 0.12);
}

.auth-network-core::before {
  content: "";
  position: absolute;
  inset: -18px;
  border-radius: 16px;
  border: 1px solid rgba(31, 191, 255, 0.18);
  box-shadow: 0 0 40px rgba(0, 174, 255, 0.12);
}

.auth-chain-symbol {
  position: relative;
  width: 62px;
  height: 46px;
  filter: drop-shadow(0 0 12px rgba(23, 207, 255, 0.65));
}

.auth-chain-symbol span {
  position: absolute;
  width: 38px;
  height: 22px;
  border: 6px solid #16c9ff;
  border-radius: 20px;
  transform: rotate(-37deg);
}

.auth-chain-symbol span:first-child {
  left: 0;
  top: 17px;
}

.auth-chain-symbol span:last-child {
  right: 0;
  top: 4px;
}

.auth-network-node {
  position: absolute;
  width: 48px;
  height: 48px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(26, 203, 255, 0.65);
  border-radius: 7px;
  background: rgba(4, 28, 48, 0.88);
  box-shadow: 0 0 22px rgba(0, 185, 255, 0.18);
}

.auth-network-node span {
  width: 12px;
  height: 12px;
  border-radius: 3px;
  background: #0bd7ff;
  box-shadow: 0 0 17px rgba(11, 215, 255, 0.8);
}

.node-one {
  left: 17%;
  top: 48%;
}

.node-two {
  left: 37%;
  top: 14%;
}

.node-three {
  right: 11%;
  top: 42%;
}

.node-four {
  right: 28%;
  top: 5%;
}

.auth-network-line {
  position: absolute;
  height: 1px;
  transform-origin: left center;
  background: linear-gradient(90deg, rgba(20, 196, 255, 0.06), rgba(20, 196, 255, 0.6), rgba(20, 196, 255, 0.06));
  box-shadow: 0 0 8px rgba(20, 196, 255, 0.3);
}

.line-one {
  width: 270px;
  left: 23%;
  top: 57%;
  transform: rotate(-16deg);
}

.line-two {
  width: 220px;
  left: 43%;
  top: 32%;
  transform: rotate(29deg);
}

.line-three {
  width: 230px;
  left: 54%;
  top: 58%;
  transform: rotate(-9deg);
}

.auth-benefits {
  display: grid;
  gap: 15px;
  max-width: 570px;
  margin-top: -3px;
}

.auth-benefit {
  display: flex;
  align-items: center;
  gap: 18px;
}

.auth-benefit-icon {
  flex: 0 0 54px;
  width: 54px;
  height: 54px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(21, 170, 255, 0.22);
  border-radius: 11px;
  background: linear-gradient(145deg, rgba(5, 51, 82, 0.76), rgba(2, 19, 33, 0.72));
  box-shadow: inset 0 0 18px rgba(8, 157, 255, 0.08);
}

.auth-benefit-icon svg {
  width: 26px;
  height: 26px;
  fill: none;
  stroke: #36d9ff;
  stroke-width: 1.45;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.auth-benefit strong {
  display: block;
  margin-bottom: 4px;
  color: #fff;
  font-size: 13px;
  letter-spacing: 0.02em;
}

.auth-benefit span {
  display: block;
  color: #9fb1c3;
  font-size: 14px;
  line-height: 1.4;
}

.auth-card {
  position: relative;
  z-index: 5;
  width: 100%;
  padding: 55px 78px 45px;
  border: 1px solid rgba(41, 156, 224, 0.58);
  border-radius: 17px;
  background:
    linear-gradient(145deg, rgba(9, 27, 43, 0.82), rgba(4, 14, 24, 0.94)),
    rgba(4, 13, 23, 0.88);
  box-shadow:
    0 30px 90px rgba(0, 0, 0, 0.38),
    0 0 35px rgba(0, 157, 255, 0.06),
    inset 0 1px 0 rgba(255, 255, 255, 0.035);
  backdrop-filter: blur(24px);
}

.auth-card::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  border-radius: inherit;
  background: linear-gradient(135deg, rgba(31, 204, 255, 0.055), transparent 28%, transparent 75%, rgba(31, 204, 255, 0.025));
}

.auth-card-header {
  position: relative;
  z-index: 1;
  margin-bottom: 38px;
}

.auth-card-header h2 {
  margin: 0 0 9px;
  color: #f7fbff;
  font-size: 38px;
  line-height: 1.1;
  letter-spacing: -0.025em;
}

.auth-card-header p {
  margin: 0;
  color: #b6c5d4;
  font-size: 16px;
  line-height: 1.5;
}

.auth-form {
  position: relative;
  z-index: 1;
}

.auth-field {
  display: block;
  margin-bottom: 25px;
}

.auth-field > span {
  display: block;
  margin-bottom: 10px;
  color: #f3f8fc;
  font-size: 15px;
  font-weight: 600;
}

.auth-input-wrapper {
  position: relative;
}

.auth-input-icon {
  position: absolute;
  left: 17px;
  top: 50%;
  z-index: 2;
  display: grid;
  place-items: center;
  width: 22px;
  height: 22px;
  transform: translateY(-50%);
  color: #c0cfdd;
}

.auth-input-icon svg {
  width: 21px;
  height: 21px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.45;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.auth-input-wrapper input {
  width: 100%;
  height: 52px;
  padding: 0 48px;
  border: 1px solid rgba(93, 127, 153, 0.56);
  border-radius: 10px;
  outline: none;
  color: #f3f8ff;
  background: rgba(5, 16, 28, 0.68);
  font: inherit;
  font-size: 15px;
  transition: border-color 180ms ease, box-shadow 180ms ease, background 180ms ease;
  box-sizing: border-box;
}

.auth-input-wrapper input::placeholder {
  color: #718396;
}

.auth-input-wrapper input:focus {
  border-color: rgba(18, 211, 255, 0.8);
  background: rgba(7, 22, 37, 0.84);
  box-shadow: 0 0 0 3px rgba(18, 211, 255, 0.08), 0 0 25px rgba(18, 211, 255, 0.05);
}

.auth-input-wrapper input:disabled {
  opacity: 0.62;
}

.auth-password-toggle {
  position: absolute;
  right: 14px;
  top: 50%;
  width: 30px;
  height: 30px;
  display: grid;
  place-items: center;
  transform: translateY(-50%);
  border: 0;
  background: transparent;
  color: #8ea2b5;
  cursor: pointer;
}

.auth-password-toggle svg {
  width: 21px;
  height: 21px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.45;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.auth-password-toggle:hover {
  color: #16d5ff;
}

.auth-options {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin: 1px 0 27px;
}

.remember-me {
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: 11px;
  color: #dce6ee;
  font-size: 14px;
  cursor: pointer;
  user-select: none;
}

.remember-me input {
  position: absolute;
  opacity: 0;
  pointer-events: none;
}

.custom-checkbox {
  width: 18px;
  height: 18px;
  display: inline-block;
  border: 1px solid #8ea2b5;
  border-radius: 4px;
  background: rgba(2, 10, 17, 0.72);
  transition: all 160ms ease;
}

.remember-me input:checked + .custom-checkbox {
  border-color: #11d4ff;
  background: #11d4ff;
  box-shadow: 0 0 14px rgba(17, 212, 255, 0.22);
}

.remember-me input:checked + .custom-checkbox::after {
  content: "✓";
  display: block;
  color: #02121d;
  font-size: 13px;
  font-weight: 900;
