  background: linear-gradient(145deg, rgba(5, 52, 84, .78), rgba(2, 19, 33, .76));
  box-shadow:
    inset 0 0 18px rgba(8, 157, 255, .08),
    0 5px 20px rgba(0, 0, 0, .14);
}

.auth-benefit-icon svg {
  width: 26px;
  height: 26px;
  fill: none;
  stroke: #36d9ff;
  stroke-width: 1.45;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.auth-benefit strong {
  display: block;
  margin: 0 0 4px;
  color: #fff;
  font-size: 13px;
  line-height: 1.1;
  letter-spacing: .02em;
}

.auth-benefit span {
  display: block;
  color: #9fb1c3;
  font-size: 14px;
  line-height: 1.4;
}

/* ---------- LOGIN CARD ---------- */

.auth-card {
  position: relative;
  z-index: 10;
  width: 100%;
  padding: 55px 78px 45px;
  border: 1px solid rgba(46, 161, 224, .66);
  border-radius: 17px;
  background:
    linear-gradient(145deg, rgba(9, 28, 45, .84), rgba(4, 14, 24, .96)),
    rgba(4, 13, 23, .90);
  box-shadow:
    0 30px 90px rgba(0, 0, 0, .42),
    0 0 38px rgba(0, 157, 255, .075),
