  color: #f7fbff;
  font-size: 38px;
  line-height: 1.1;
  font-weight: 750;
  letter-spacing: -.025em;
}

.auth-card-header p {
  margin: 0;
  color: #b6c5d4;
  font-size: 16px;
  line-height: 1.5;
}

.auth-form {
  position: relative;
  z-index: 1;
}

.auth-field {
