/* =========================================================
   CHAINLAB LEARNING HUB
========================================================= */

.learnPage {
  min-height: 100vh;
  background:
    linear-gradient(
      rgba(0, 200, 255, 0.025) 1px,
      transparent 1px
    ),
    linear-gradient(
      90deg,
      rgba(0, 200, 255, 0.025) 1px,
      transparent 1px
    ),
    #02060b;
  background-size: 72px 72px;
  color: #f5f7fa;
}

.learnNav {
  height: 78px;
  padding: 0 4%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 1px solid rgba(0, 200, 255, 0.16);
  background: rgba(2, 6, 11, 0.96);
  position: sticky;
  top: 0;
  z-index: 100;
  backdrop-filter: blur(16px);
}

.learnBrand {
  font-size: calc((20px) * var(--cl-font-scale, 1));
  font-weight: 900;
