  left: 4%;
}

.nodeTwo {
  top: 115px;
  right: 0;
}

.nodeThree {
  bottom: 80px;
  left: 0;
}

.nodeFour {
  bottom: 20px;
  right: 8%;
}

.learningPath {
  padding: 120px 6%;
}

.learnSectionHeader {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 80px;
  align-items: end;
  margin-bottom: 65px;
}

.learnSectionHeader h2 {
  margin: 0;
  font-size: calc((clamp(48px, 6vw, 90px)) * var(--cl-font-scale, 1));
  line-height: 0.9;
  letter-spacing: -4px;
  font-weight: 900;
}

.learnSectionHeader h2 span {
  color: #ffad00;
}

.learnSectionHeader > p {
  max-width: 550px;
  color: #8194a9;
  line-height: 1.8;
  font-size: calc((15px) * var(--cl-font-scale, 1));
}

.learningModule {
  display: grid;
  grid-template-columns: 100px 1fr 190px;
  gap: 35px;
  align-items: center;
  min-height: 230px;
  padding: 35px 40px;
