}

.moduleTopics {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.moduleTopics span {
  padding: 7px 10px;
  border: 1px solid rgba(0, 200, 255, 0.15);
  color: #718599;
  font-size: calc((8px) * var(--cl-font-scale, 1));
  font-weight: 900;
  letter-spacing: 0.7px;
}

.moduleAction {
  display: flex;
  justify-content: flex-end;
  align-items: center;
  gap: 18px;
  color: #00c8ff;
  font-size: calc((9px) * var(--cl-font-scale, 1));
  font-weight: 900;
  letter-spacing: 1px;
}

.moduleAction strong {
  font-size: calc((22px) * var(--cl-font-scale, 1));
}

.securityModule {
  border-color: rgba(0, 200, 255, 0.3);
}

.comingModule {
  opacity: 0.65;
  cursor: default;
}

.comingModule .moduleAction {
  color: #ffad00;
}

.learnProcess {
