/* =========================================
   CHAINLAB CHAT BUTTON
   Glossy pill design inspired by START LEARNING
   ========================================= */

.chainlab-chat-launcher {
  position: fixed !important;
  right: 26px !important;
  bottom: 26px !important;
  top: auto !important;
  left: auto !important;

  z-index: 10010 !important;

  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  gap: 12px !important;

  min-width: 230px;
  min-height: 62px;

  padding: 16px 28px !important;

  border: 1px solid rgba(255, 255, 255, 0.75) !important;
  border-radius: 999px !important;

  background: linear-gradient(
    180deg,
    #222328 0%,
    #101115 48%,
    #08090c 100%
  ) !important;

  color: #f5f6f8 !important;

  font-family: inherit !important;
  font-size: 16px !important;
  font-weight: 700 !important;
  letter-spacing: 0.04em !important;

  cursor: pointer !important;

  box-shadow:
    0 0 0 4px rgba(255, 255, 255, 0.08),
    0 0 0 7px rgba(0, 0, 0, 0.55),
    inset 0 1px 2px rgba(255, 255, 255, 0.3),
    inset 0 -5px 10px rgba(0, 0, 0, 0.7),
    0 8px 20px rgba(0, 0, 0, 0.45);

  transition:
    transform 0.25s ease,
    box-shadow 0.25s ease,
    border-color 0.25s ease;
}

/* Hide the old square icon */
.chainlab-chat-launcher-icon {
  display: none !important;
}

/* Add the arrow */
.chainlab-chat-launcher::after {
  content: "→";
  display: inline-block;

  font-size: 22px;
  font-weight: 400;
  line-height: 1;

  transition: transform 0.25s ease;
}

/* Hover effect */
.chainlab-chat-launcher:hover {
  transform: translateY(-2px);

  border-color: rgba(255, 255, 255, 0.95) !important;

  box-shadow:
    0 0 0 4px rgba(255, 255, 255, 0.12),
    0 0 0 7px rgba(0, 0, 0, 0.6),
    inset 0 1px 3px rgba(255, 255, 255, 0.4),
    inset 0 -5px 10px rgba(0, 0, 0, 0.7),
    0 10px 25px rgba(0, 0, 0, 0.5);
}

.chainlab-chat-launcher:hover::after {
  transform: translateX(4px);
}

/* Pressed effect */
.chainlab-chat-launcher:active {
  transform: scale(0.97);

  box-shadow:
    inset 0 3px 8px rgba(0, 0, 0, 0.8),
    0 2px 6px rgba(0, 0, 0, 0.3);
}

/* Keyboard accessibility */
.chainlab-chat-launcher:focus-visible {
  outline: 2px solid #ffffff;
  outline-offset: 6px;
}

/* Mobile positioning */
@media (max-width: 768px) {
  .chainlab-chat-launcher {
    right: 18px !important;
    bottom: 18px !important;

    min-width: 190px;
    min-height: 56px;

    padding: 14px 22px !important;
    font-size: 14px !important;
  }
}
/* =========================================
   CHAINLAB CHATBOX — ANIMATED CARD DESIGN
   Inspired by Uiverse.io by ElSombrero2
   ========================================= */

.chainlab-chatbox {
  position: fixed !important;

  right: 28px !important;
  bottom: 105px !important;

  width: 360px !important;
  max-width: calc(100vw - 32px) !important;

  height: 480px !important;
  max-height: calc(100dvh - 140px) !important;

  z-index: 10009 !important;

  display: flex !important;
  flex-direction: column !important;

  overflow: hidden !important;

  background: #151515 !important;
  color: #ffffff !important;

  border: 1px solid rgba(255, 153, 102, 0.35) !important;
  border-radius: 8px !important;

  box-shadow:
    0 0 10px 1px #000000ee,
    0 0 25px rgba(255, 153, 102, 0.08);

  isolation: isolate;

  animation: chainlab-chat-appear 300ms ease-out;
}

/* Animated orange border */

.chainlab-chatbox::before {
  content: "";

  position: absolute;
  inset: -50%;

  width: 200%;
  height: 200%;

  background: linear-gradient(
    90deg,
    transparent,
    #ff9966,
    #ff9966,
    #ff9966,
    transparent
  );

  animation: chainlab-chat-border 5s linear infinite;

  z-index: -2;

  pointer-events: none;
}

/* Dark inner surface */

.chainlab-chatbox::after {
  content: "";

  position: absolute;
  inset: 2px;

  background: #151515;

  border-radius: 6px;

  z-index: -1;

  pointer-events: none;
}

/* =========================================
   CHAT HEADER
   ========================================= */

.chainlab-chat-header {
  position: relative;

  display: flex;
  align-items: center;
  justify-content: space-between;

  padding: 20px;

  background: #151515;

  border-bottom: 1px solid rgba(255, 153, 102, 0.2);

  flex-shrink: 0;
}

.chainlab-chat-label {
  display: block;

  margin-bottom: 6px;

  color: #ff9966;

  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.12em;
}

.chainlab-chat-header h2 {
  margin: 0;

  color: #ffffff;

  font-size: 20px;
  font-weight: 700;
}

/* Close button */

.chainlab-chat-close {
  display: flex;
  align-items: center;
  justify-content: center;

  width: 34px;
  height: 34px;

  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: 50%;

  background: #202020;

  color: #ffffff;

  font-size: 23px;

  cursor: pointer;

  transition:
    background 200ms ease,
    border-color 200ms ease;
}

.chainlab-chat-close:hover {
  background: #303030;
  border-color: #ff9966;
}

/* =========================================
   CHAT MESSAGES
   ========================================= */

.chainlab-chat-messages {
  position: relative;

  display: flex;
  flex-direction: column;
  gap: 14px;

  flex: 1;

  min-height: 0;

  padding: 20px;

  overflow-y: auto;

  background: #151515;

  scrollbar-width: thin;
  scrollbar-color: #454545 #151515;
}

/* Individual message bubbles */

.chainlab-message {
  max-width: 90%;

  padding: 12px 14px;

  border-radius: 6px;

  font-size: 14px;
  line-height: 1.6;

  overflow-wrap: anywhere;
}

/* ChainLab assistant messages */

.assistant-message {
  align-self: flex-start;

  background: #222222;

  border: 1px solid rgba(255, 255, 255, 0.08);

  color: #eeeeee;
}

/* User messages */

.user-message {
  align-self: flex-end;

  background: rgba(255, 153, 102, 0.12);

  border: 1px solid rgba(255, 153, 102, 0.4);

  color: #ffffff;
}

/* =========================================
   QUICK QUESTIONS
   ========================================= */

.chainlab-chat-quick {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;

  padding: 12px 16px;

  background: #151515;

  border-top: 1px solid rgba(255, 255, 255, 0.07);
}

.chainlab-chat-quick button {
  padding: 8px 11px;

  border: 1px solid rgba(255, 153, 102, 0.35);
  border-radius: 5px;

  background: #202020;

  color: #eeeeee;

  font-size: 11px;

  cursor: pointer;

  transition:
    background 200ms ease,
    border-color 200ms ease;
}

.chainlab-chat-quick button:hover {
  background: #292929;
  border-color: #ff9966;
}

/* =========================================
   CHAT INPUT
   ========================================= */

.chainlab-chat-input {
  display: flex;
  align-items: center;
  gap: 10px;

  padding: 14px 16px;

  background: #151515;

  border-top: 1px solid rgba(255, 255, 255, 0.1);

  flex-shrink: 0;
}

.chainlab-chat-input input {
  flex: 1;

  min-width: 0;

  padding: 12px 14px;

  border: 1px solid #353535;
  border-radius: 5px;

  outline: none;

  background: #202020;

  color: #ffffff;

  font-family: inherit;
  font-size: 13px;

  transition: border-color 200ms ease;
}

.chainlab-chat-input input::placeholder {
  color: #888888;
}

.chainlab-chat-input input:focus {
  border-color: #ff9966;
}

/* Send button */

.chainlab-chat-input button {
  display: flex;
  align-items: center;
  justify-content: center;

  width: 44px;
  height: 44px;

  border: 1px solid rgba(255, 153, 102, 0.7);
  border-radius: 5px;

  background: #ff9966;

  color: #151515;

  font-size: 24px;
  font-weight: 700;

  cursor: pointer;

  transition:
    background 200ms ease,
    transform 200ms ease;
}

.chainlab-chat-input button:hover {
  background: #ffb38c;
  transform: translateY(-2px);
}

/* =========================================
   ANIMATIONS
   ========================================= */

@keyframes chainlab-chat-border {
  0% {
    transform: rotate(0deg);
  }

  100% {
    transform: rotate(360deg);
  }
}

@keyframes chainlab-chat-appear {
  from {
    opacity: 0;
    transform: translateY(12px) scale(0.98);
  }

  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

/* =========================================
   MOBILE RESPONSIVENESS
   ========================================= */

@media (max-width: 480px) {
  .chainlab-chatbox {
    right: 12px !important;
    bottom: 88px !important;

    width: calc(100vw - 24px) !important;

    height: min(480px, calc(100dvh - 115px)) !important;

    max-height: calc(100dvh - 115px) !important;
  }

  .chainlab-chat-header {
    padding: 16px;
  }

  .chainlab-chat-messages {
    padding: 14px;
  }
}

/* =========================================
   CHAINLAB — SPARKLE TOOLBAR BUTTONS
   White and silver theme
   ========================================= */

.chainlab-control-sparkle {
  --active: 0;

  position: relative;
  isolation: isolate;

  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;

  min-width: 48px;
  min-height: 48px;

  padding: 12px;

  border: 1px solid rgba(255, 255, 255, 0.16);
  border-radius: 100px;

  background:
    radial-gradient(
      40% 50% at center 100%,
      rgba(255, 255, 255, calc(var(--active) * 0.25)),
      transparent
    ),
    radial-gradient(
      80% 100% at center 120%,
      rgba(220, 225, 235, calc(var(--active) * 0.2)),
      transparent
    ),
    #151515;

  color: #f5f5f5;

  font-family: inherit;
  font-size: 16px;
  font-weight: 600;

  cursor: pointer;
  white-space: nowrap;

  box-shadow:
    0 0 calc(var(--active) * 18px)
      calc(var(--active) * 4px)
      rgba(255, 255, 255, 0.12),
    inset 0 1px 1px rgba(255, 255, 255, 0.2),
    inset 0 -2px 4px rgba(0, 0, 0, 0.5);

  transition:
    background 300ms ease,
    box-shadow 300ms ease,
    transform 300ms ease,
    border-color 300ms ease;
}

/* White outer glow */

.chainlab-control-sparkle::before {
  content: "";

  position: absolute;
  inset: -4px;

  z-index: -1;

  border: 1px solid rgba(255, 255, 255, 0.35);
  border-radius: inherit;

  opacity: var(--active);

  transition: opacity 300ms ease;
}

/* White highlight */

.chainlab-control-sparkle::after {
  content: "";

  position: absolute;
  inset: 0;

  border-radius: inherit;

  background: linear-gradient(
    180deg,
    rgba(255, 255, 255, 0.18),
    transparent 55%
  );

  opacity: 0;

  pointer-events: none;

  transition: opacity 300ms ease;
}

/* Hover and keyboard focus */

.chainlab-control-sparkle:hover,
.chainlab-control-sparkle:focus-visible {
  --active: 1;

  border-color: rgba(255, 255, 255, 0.75);

  transform: translateY(-2px);

  box-shadow:
    0 0 18px rgba(255, 255, 255, 0.12),
    inset 0 1px 2px rgba(255, 255, 255, 0.3),
    inset 0 -2px 4px rgba(0, 0, 0, 0.5);
}

.chainlab-control-sparkle:hover::after,
.chainlab-control-sparkle:focus-visible::after {
  opacity: 1;
}

/* Pressed state */

.chainlab-control-sparkle:active {
  transform: scale(0.96);

  background: #292929;

  box-shadow:
    inset 0 2px 6px rgba(0, 0, 0, 0.6),
    0 0 8px rgba(255, 255, 255, 0.12);
}

/* Keyboard accessibility */

.chainlab-control-sparkle:focus-visible {
  outline: 2px solid #ffffff;
  outline-offset: 5px;
}

/* =========================================
   SPARKLE DECORATION
   ========================================= */

.chainlab-control-sparkle .sparkle-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;

  color: #ffffff;

  transition:
    transform 300ms ease,
    filter 300ms ease;
}

.chainlab-control-sparkle:hover .sparkle-icon {
  transform: scale(1.12);

  filter: drop-shadow(0 0 5px rgba(255, 255, 255, 0.7));
}

/* =========================================
   LIGHT MODE
   ========================================= */

html[data-theme="light"] .chainlab-control-sparkle {
  background: #f0f0f0;

  color: #171717;

  border-color: rgba(0, 0, 0, 0.18);

  box-shadow:
    inset 0 1px 2px rgba(255, 255, 255, 0.9),
    0 2px 6px rgba(0, 0, 0, 0.08);
}

html[data-theme="light"] .chainlab-control-sparkle::before {
  border-color: rgba(0, 0, 0, 0.2);
}

html[data-theme="light"] .chainlab-control-sparkle::after {
  background: linear-gradient(
    180deg,
    rgba(255, 255, 255, 0.8),
    transparent 60%
  );
}

html[data-theme="light"] .chainlab-control-sparkle:hover {
