  -webkit-text-fill-color: #b7c4d8 !important;
  background-image: none !important;
  text-shadow: none !important;
}


/* COMPANY SECTION LIGHT MODE OVERRIDE
   ChainLabControls sets data-theme="light" on both html and body.
   Target the section directly so this works even if its inner wrapper class changes. */
html[data-theme="light"] body[data-theme="light"] main .about-section {
  color: #f5f7fa !important;
}

html[data-theme="light"] body[data-theme="light"] main .about-section :is(.section-label, .eyebrow, .section-kicker) {
  color: #00d4ff !important;
  -webkit-text-fill-color: #00d4ff !important;
}

html[data-theme="light"] body[data-theme="light"] main .about-section :is(h1, h2, h3) {
  color: #f5f7fa !important;
  -webkit-text-fill-color: #f5f7fa !important;
  background: none !important;
  background-image: none !important;
}

html[data-theme="light"] body[data-theme="light"] main .about-section :is(h1, h2, h3) span {
  color: #ffad00 !important;
  -webkit-text-fill-color: #ffad00 !important;
}

html[data-theme="light"] body[data-theme="light"] main .about-section :is(p, li, blockquote) {
  color: #b7c4d8 !important;
  -webkit-text-fill-color: #b7c4d8 !important;
  text-shadow: none !important;
  background-image: none !important;
}

html[data-theme="light"] body[data-theme="light"] main .about-section :is(p, li, blockquote) * {
  color: inherit !important;
  -webkit-text-fill-color: inherit !important;
}

/* COMPANY BEHIND CHAINLAB — FORCE ALL SECTION COPY TO WHITE IN LIGHT MODE */
html[data-theme="light"] body[data-theme="light"] main .about-section .company-content :is(.section-label, .eyebrow, .section-kicker, h1, h2, h3, p, li, blockquote),
html[data-theme="light"] body[data-theme="light"] main .about-section .company-content :is(.section-label, .eyebrow, .section-kicker, h1, h2, h3, p, li, blockquote) * {
  color: #ffffff !important;
  -webkit-text-fill-color: #ffffff !important;
  background-image: none !important;
  text-shadow: none !important;
}

/* Light-mode hero typography: strong black headline with slate supporting text. */
html[data-theme="light"] body:has(.hero-section) main .hero-section .hero-kicker,
html[data-theme="light"] body:has(.hero-section) main .hero-section .eyebrow,
html[data-theme="light"] body:has(.hero-section) main .hero-section .section-label {
