  color: #f7fbff;
  background:
    radial-gradient(circle at 18% 60%, rgba(0, 108, 255, .16), transparent 28%),
    radial-gradient(circle at 72% 46%, rgba(0, 190, 255, .075), transparent 26%),
    radial-gradient(circle at 100% 70%, rgba(0, 90, 255, .08), transparent 25%),
    #02070d;
}

/* ---------- TOP NAV ---------- */

.auth-topbar {
  position: relative;
  z-index: 50;
  width: 100%;
  height: 76px;
  display: flex;
  align-items: center;
  padding: 0 clamp(28px, 5.8vw, 90px);
  gap: 42px;
  border-bottom: 1px solid rgba(34, 153, 219, .18);
  background: rgba(2, 7, 13, .84);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
}

.auth-brand {
  flex: 0 0 auto;
  color: #f8fbff;
  text-decoration: none;
  font-size: 30px;
  line-height: 1;
  font-weight: 800;
  letter-spacing: -1.5px;
}

.auth-brand span {
  color: #13d7ff;
}

.auth-nav {
  display: flex;
  align-items: center;
  gap: clamp(24px, 2.7vw, 43px);
  margin-left: 36px;
}

.auth-nav a {
  position: relative;
  color: #b9c9d8;
  text-decoration: none;
  font-size: 14px;
  line-height: 1;
  font-weight: 500;
  letter-spacing: .015em;
  transition: color .18s ease;
}

.auth-nav a::after {
  content: "";
  position: absolute;
  left: 0;
  right: 100%;
  bottom: -9px;
  height: 1px;
  background: #18d9ff;
  transition: right .18s ease;
}

.auth-nav a:hover {
  color: #fff;
}

.auth-nav a:hover::after {
  right: 0;
}

.auth-top-actions {
  display: flex;
  align-items: center;
  gap: 20px;
  margin-left: auto;
}

.auth-icon-button {
  width: 31px;
  height: 31px;
  display: grid;
  place-items: center;
  padding: 0;
  border: 0;
  background: transparent;
  color: #9eb1c3;
  cursor: pointer;
  transition: color .18s ease, transform .18s ease;
}

.auth-icon-button:hover {
  color: #19d8ff;
  transform: translateY(-1px);
}

.auth-icon-button svg {
  width: 22px;
  height: 22px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.55;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.auth-get-started {
  min-width: 148px;
  height: 45px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0 19px;
  border: 1px solid #0fd3ff;
  border-radius: 11px;
  color: #f8fcff;
  background: rgba(0, 178, 255, .025);
  text-decoration: none;
  font-size: 13px;
  font-weight: 700;
  letter-spacing: .035em;
  box-shadow: 0 0 24px rgba(0, 205, 255, .09);
  transition: background .18s ease, box-shadow .18s ease, transform .18s ease;
}

.auth-get-started:hover {
  background: rgba(0, 205, 255, .10);
  box-shadow: 0 0 30px rgba(0, 205, 255, .20);
  transform: translateY(-1px);
}

/* ---------- MAIN SHELL ---------- */

.auth-shell {
  position: relative;
  z-index: 2;
  width: min(1450px, 100%);
  min-height: calc(100vh - 76px);
  margin: 0 auto;
  padding: 48px clamp(28px, 5.8vw, 90px) 52px;
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(500px, 610px);
  align-items: center;
  column-gap: clamp(48px, 6.8vw, 105px);
}

.auth-background-grid {
  position: absolute;
  z-index: 0;
  inset: 0;
  pointer-events: none;
  opacity: .26;
  background-image:
    linear-gradient(rgba(30, 147, 226, .07) 1px, transparent 1px),
    linear-gradient(90deg, rgba(30, 147, 226, .07) 1px, transparent 1px);
  background-size: 64px 64px;
  mask-image: linear-gradient(to bottom, transparent 0%, black 13%, black 86%, transparent 100%);
  -webkit-mask-image: linear-gradient(to bottom, transparent 0%, black 13%, black 86%, transparent 100%);
}

.auth-glow {
  position: absolute;
  z-index: 0;
  pointer-events: none;
  border-radius: 50%;
  filter: blur(85px);
}

.auth-glow-one {
  width: 520px;
  height: 520px;
  left: -110px;
  top: 18%;
  background: rgba(0, 106, 255, .095);
}

.auth-glow-two {
  width: 390px;
  height: 390px;
  right: 17%;
  bottom: -80px;
  background: rgba(0, 213, 255, .055);
}

/* ---------- LEFT HERO ---------- */

.auth-hero {
  position: relative;
  z-index: 4;
  min-width: 0;
  padding-left: clamp(0px, 1.2vw, 18px);
}

.auth-eyebrow {
  margin: 0 0 24px;
  color: #27d9ff;
  font-size: 13px;
  line-height: 1;
  font-weight: 700;
  letter-spacing: .31em;
}

.auth-hero h1 {
  margin: 0;
  color: #f8fbff;
  font-size: clamp(60px, 5.7vw, 88px);
  line-height: .965;
  font-weight: 800;
  letter-spacing: -.057em;
}

.auth-hero h1 span {
  color: #12d8ff;
  text-shadow: 0 0 34px rgba(18, 216, 255, .14);
}

.auth-hero-copy {
  max-width: 595px;
  margin: 27px 0 0;
  color: #b8c8d8;
  font-size: 19px;
  line-height: 1.58;
}

/* ---------- BLOCKCHAIN ART ---------- */

.auth-network {
  position: relative;
  width: min(100%, 690px);
  height: 305px;
  margin: 3px 0 -2px;
  overflow: visible;
}

/* Glowing perspective floor under the network. */
.auth-network::after {
  content: "";
  position: absolute;
  left: 3%;
  right: 0;
  bottom: 14px;
  height: 135px;
  opacity: .42;
  transform: perspective(450px) rotateX(60deg);
  transform-origin: bottom center;
  background-image:
    linear-gradient(rgba(0, 181, 255, .15) 1px, transparent 1px),
    linear-gradient(90deg, rgba(0, 181, 255, .15) 1px, transparent 1px);
  background-size: 42px 42px;
  mask-image: radial-gradient(ellipse at center, black 0%, transparent 72%);
  -webkit-mask-image: radial-gradient(ellipse at center, black 0%, transparent 72%);
  pointer-events: none;
}

.auth-network-core {
  position: absolute;
  z-index: 5;
  left: 54%;
  top: 55%;
  width: 174px;
  height: 145px;
  transform: translate(-50%, -50%) perspective(650px) rotateX(10deg) rotateZ(-1deg);
  display: grid;
  place-items: center;
  border: 1px solid rgba(44, 211, 255, .88);
  border-radius: 9px;
  background:
    linear-gradient(145deg, rgba(20, 120, 192, .38), rgba(2, 16, 29, .91)),
    rgba(3, 20, 34, .9);
  box-shadow:
    0 0 12px rgba(19, 207, 255, .48),
    0 0 42px rgba(0, 183, 255, .24),
    inset 0 0 40px rgba(7, 148, 255, .16);
}

/* Cube side / depth. */
.auth-network-core::before {
  content: "";
  position: absolute;
  z-index: -1;
  left: 17px;
  right: -18px;
  bottom: -25px;
  height: 25px;
  transform: skewX(-38deg);
  transform-origin: top left;
  border: 1px solid rgba(17, 151, 215, .42);
  background: linear-gradient(90deg, rgba(3, 26, 43, .92), rgba(2, 12, 23, .92));
  box-shadow: 0 15px 28px rgba(0, 0, 0, .55);
}

/* Inner glow / top face. */
.auth-network-core::after {
  content: "";
  position: absolute;
  inset: -18px;
  border: 1px solid rgba(28, 199, 255, .18);
  border-radius: 13px;
  box-shadow: 0 0 42px rgba(0, 180, 255, .13);
  pointer-events: none;
}

.auth-chain-symbol {
  position: relative;
  z-index: 2;
  width: 66px;
  height: 48px;
  filter: drop-shadow(0 0 12px rgba(23, 207, 255, .72));
}

.auth-chain-symbol span {
  position: absolute;
  width: 39px;
  height: 23px;
  border: 6px solid #16caff;
  border-radius: 20px;
  transform: rotate(-37deg);
}

.auth-chain-symbol span:first-child {
  left: 0;
  top: 18px;
}

.auth-chain-symbol span:last-child {
  right: 0;
  top: 4px;
}

/* Small blockchain cubes. */
.auth-network-node {
  position: absolute;
  z-index: 4;
  width: 54px;
  height: 54px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(35, 210, 255, .78);
  border-radius: 5px;
  background:
    linear-gradient(145deg, rgba(16, 107, 169, .48), rgba(2, 24, 41, .92));
  box-shadow:
    0 0 18px rgba(0, 190, 255, .25),
    inset 0 0 17px rgba(0, 173, 255, .10);
  transform: perspective(400px) rotateX(7deg) rotateZ(-1deg);
}

.auth-network-node::before {
  content: "";
  position: absolute;
  left: 9px;
  right: -10px;
  bottom: -10px;
  height: 10px;
  transform: skewX(-42deg);
  background: rgba(2, 28, 45, .84);
  border-right: 1px solid rgba(29, 189, 239, .4);
  border-bottom: 1px solid rgba(29, 189, 239, .3);
}

.auth-network-node span {
  width: 13px;
  height: 13px;
  border-radius: 2px;
  background: #12d7ff;
  box-shadow:
    0 0 9px #12d7ff,
    0 0 24px rgba(18, 215, 255, .72);
}

.node-one { left: 15%; top: 52%; }
.node-two { left: 36%; top: 12%; }
.node-three { right: 8%; top: 44%; }
.node-four { right: 26%; top: 2%; }

.auth-network-line {
  position: absolute;
  z-index: 2;
  height: 1px;
  transform-origin: left center;
  background: linear-gradient(
    90deg,
    rgba(18, 202, 255, .04),
    rgba(18, 202, 255, .58),
    rgba(18, 202, 255, .08)
  );
  box-shadow: 0 0 8px rgba(20, 196, 255, .30);
}

.line-one {
  width: 270px;
  left: 20%;
  top: 60%;
  transform: rotate(-16deg);
}

.line-two {
  width: 225px;
  left: 41%;
  top: 31%;
  transform: rotate(29deg);
}

.line-three {
  width: 245px;
  left: 53%;
  top: 61%;
  transform: rotate(-10deg);
}

/* ---------- BENEFITS ---------- */

.auth-benefits {
  position: relative;
  z-index: 5;
  display: grid;
  gap: 15px;
  max-width: 575px;
  margin-top: -1px;
}

.auth-benefit {
  display: flex;
  align-items: center;
  gap: 18px;
}

.auth-benefit-icon {
  flex: 0 0 54px;
  width: 54px;
  height: 54px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(21, 170, 255, .23);
  border-radius: 11px;
  background: linear-gradient(145deg, rgba(5, 52, 84, .78), rgba(2, 19, 33, .76));
  box-shadow:
    inset 0 0 18px rgba(8, 157, 255, .08),
    0 5px 20px rgba(0, 0, 0, .14);
}

.auth-benefit-icon svg {
  width: 26px;
  height: 26px;
  fill: none;
  stroke: #36d9ff;
  stroke-width: 1.45;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.auth-benefit strong {
  display: block;
  margin: 0 0 4px;
  color: #fff;
  font-size: 13px;
  line-height: 1.1;
  letter-spacing: .02em;
}

.auth-benefit span {
  display: block;
  color: #9fb1c3;
  font-size: 14px;
  line-height: 1.4;
}

/* ---------- LOGIN CARD ---------- */

.auth-card {
  position: relative;
  z-index: 10;
  width: 100%;
  padding: 55px 78px 45px;
  border: 1px solid rgba(46, 161, 224, .66);
  border-radius: 17px;
  background:
    linear-gradient(145deg, rgba(9, 28, 45, .84), rgba(4, 14, 24, .96)),
    rgba(4, 13, 23, .90);
  box-shadow:
    0 30px 90px rgba(0, 0, 0, .42),
    0 0 38px rgba(0, 157, 255, .075),
    inset 0 1px 0 rgba(255, 255, 255, .045);
  backdrop-filter: blur(24px);
  -webkit-backdrop-filter: blur(24px);
}

.auth-card::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  border-radius: inherit;
  background:
    linear-gradient(
      135deg,
      rgba(31, 204, 255, .06),
      transparent 27%,
      transparent 73%,
      rgba(31, 204, 255, .025)
    );
}

.auth-card-header {
  position: relative;
  z-index: 1;
  margin-bottom: 38px;
}

.auth-card-header h2 {
  margin: 0 0 9px;
  color: #f7fbff;
  font-size: 38px;
  line-height: 1.1;
  font-weight: 750;
  letter-spacing: -.025em;
}

.auth-card-header p {
  margin: 0;
  color: #b6c5d4;
  font-size: 16px;
  line-height: 1.5;
}

.auth-form {
  position: relative;
  z-index: 1;
}

.auth-field {
  display: block;
  margin-bottom: 25px;
}

.auth-field > span {
  display: block;
  margin-bottom: 10px;
  color: #f3f8fc;
  font-size: 15px;
  font-weight: 600;
}

.auth-input-wrapper {
  position: relative;
}

.auth-input-icon {
  position: absolute;
  left: 17px;
  top: 50%;
  z-index: 2;
  width: 22px;
  height: 22px;
  display: grid;
  place-items: center;
  transform: translateY(-50%);
  color: #c0cfdd;
}

.auth-input-icon svg {
  width: 21px;
  height: 21px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.45;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.auth-input-wrapper input {
  width: 100%;
  height: 52px;
  padding: 0 48px;
  border: 1px solid rgba(93, 127, 153, .56);
  border-radius: 10px;
  outline: none;
  color: #f3f8ff;
  background: rgba(5, 16, 28, .68);
  font: inherit;
  font-size: 15px;
  box-sizing: border-box;
  transition: border-color .18s ease, box-shadow .18s ease, background .18s ease;
}

.auth-input-wrapper input::placeholder {
  color: #718396;
}

.auth-input-wrapper input:focus {
  border-color: rgba(18, 211, 255, .82);
  background: rgba(7, 22, 37, .86);
  box-shadow:
    0 0 0 3px rgba(18, 211, 255, .08),
    0 0 25px rgba(18, 211, 255, .05);
}

.auth-input-wrapper input:disabled {
  opacity: .62;
}

.auth-password-toggle {
  position: absolute;
  right: 13px;
  top: 50%;
  width: 31px;
  height: 31px;
  display: grid;
  place-items: center;
  padding: 0;
  transform: translateY(-50%);
  border: 0;
  background: transparent;
  color: #8ea2b5;
  cursor: pointer;
}

.auth-password-toggle:hover {
  color: #16d5ff;
}

.auth-password-toggle svg {
  width: 21px;
  height: 21px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.45;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.auth-options {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin: 1px 0 27px;
}

.remember-me {
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: 11px;
  color: #dce6ee;
  font-size: 14px;
  cursor: pointer;
  user-select: none;
}

.remember-me input {
  position: absolute;
  opacity: 0;
  pointer-events: none;
}

.custom-checkbox {
  width: 18px;
  height: 18px;
  display: inline-block;
  border: 1px solid #8ea2b5;
  border-radius: 4px;
  background: rgba(2, 10, 17, .72);
  transition: all .16s ease;
}

.remember-me input:checked + .custom-checkbox {
  border-color: #11d4ff;
  background: #11d4ff;
  box-shadow: 0 0 14px rgba(17, 212, 255, .22);
}

.remember-me input:checked + .custom-checkbox::after {
  content: "✓";
  display: block;
  color: #02121d;
  font-size: 13px;
  font-weight: 900;
  line-height: 17px;
  text-align: center;
}

.forgot-password {
  padding: 0;
  border: 0;
  background: transparent;
  color: #13d8ff;
  font: inherit;
  font-size: 14px;
  cursor: pointer;
}

.forgot-password:hover {
  color: #7beaff;
}

.auth-primary-button {
  width: 100%;
  height: 55px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  border: 0;
  border-radius: 10px;
  color: #02131c;
  background: linear-gradient(90deg, #14d9f7, #18b9ef);
  font: inherit;
  font-size: 16px;
  font-weight: 800;
  cursor: pointer;
  box-shadow: 0 10px 25px rgba(7, 195, 239, .13);
  transition: transform .16s ease, box-shadow .16s ease, filter .16s ease;
}

.auth-primary-button span {
  font-size: 23px;
  line-height: 0;
}

.auth-primary-button:hover:not(:disabled) {
  transform: translateY(-1px);
  box-shadow: 0 14px 32px rgba(7, 195, 239, .20);
  filter: brightness(1.04);
}

.auth-primary-button:disabled {
  cursor: wait;
  opacity: .7;
}

.auth-message {
  position: relative;
  z-index: 1;
  margin: 14px 0 0;
  padding: 10px 12px;
  border: 1px solid rgba(19, 216, 255, .20);
  border-radius: 8px;
  color: #9defff;
  background: rgba(10, 168, 211, .06);
  font-size: 13px;
  line-height: 1.45;
}

.auth-divider {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
  gap: 16px;
  margin: 29px 0 23px;
  color: #91a3b5;
  font-size: 13px;
}

.auth-divider::before,
.auth-divider::after {
  content: "";
  flex: 1;
  height: 1px;
  background: rgba(129, 151, 170, .32);
}

.auth-divider span {
  flex: 0 0 auto;
}

.auth-social-buttons {
  position: relative;
  z-index: 1;
  display: grid;
  gap: 11px;
}

.auth-social-button {
  width: 100%;
  min-height: 51px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  border: 1px solid rgba(87, 119, 145, .48);
  border-radius: 9px;
  color: #edf5fb;
  background: rgba(10, 24, 38, .62);
  font: inherit;
  font-size: 15px;
  font-weight: 500;
  cursor: pointer;
  transition: border-color .16s ease, background .16s ease, transform .16s ease;
}

.auth-social-button:hover {
  border-color: rgba(19, 211, 255, .52);
  background: rgba(13, 37, 54, .82);
  transform: translateY(-1px);
}

.google-icon,
.apple-icon,
.phantom-icon {
  width: 23px;
  height: 23px;
  display: grid;
  place-items: center;
}

.google-icon svg,
.apple-icon svg,
.phantom-icon svg {
  width: 22px;
  height: 22px;
}

.apple-icon {
  color: #fff;
}

.apple-icon svg {
  fill: currentColor;
}

.phantom-icon {
  color: #a477ff;
}

.phantom-icon svg {
  fill: currentColor;
  filter: drop-shadow(0 0 5px rgba(164, 119, 255, .35));
}

.auth-switch {
  position: relative;
  z-index: 1;
  margin: 34px 0 0;
  color: #aabaca;
  text-align: center;
  font-size: 15px;
}

.auth-switch a {
  color: #13d8ff;
  font-weight: 600;
  text-decoration: none;
}

.auth-switch a:hover {
  text-decoration: underline;
}

.auth-back {
  position: relative;
  z-index: 1;
  display: block;
  margin-top: 25px;
  color: #7f93a6;
  font-size: 13px;
  text-align: center;
  text-decoration: none;
}

.auth-back:hover {
  color: #13d8ff;
}

/* Login is intentionally dark even if the global site is in light mode. */
html.light body:has(.auth-page),
body.light:has(.auth-page) {
  background: #02070d !important;
}

/* ---------- RESPONSIVE ---------- */

@media (max-width: 1220px) {
  .auth-topbar {
    gap: 25px;
    padding-inline: 4vw;
  }

  .auth-nav {
    gap: 23px;
    margin-left: 20px;
  }

  .auth-shell {
    grid-template-columns: minmax(0, 1fr) minmax(440px, 540px);
    column-gap: 42px;
    padding-inline: 4vw;
  }

  .auth-card {
    padding: 46px 48px 40px;
  }

  .auth-network {
    transform: scale(.91);
    transform-origin: left center;
    width: 110%;
    margin-top: -2px;
    margin-bottom: -18px;
  }
}

@media (max-width: 940px) {
  .auth-nav {
    display: none;
  }

  .auth-top-actions {
    margin-left: auto;
  }

  .auth-shell {
    grid-template-columns: 1fr;
    max-width: 700px;
    min-height: auto;
    padding-top: 46px;
  }

  .auth-hero {
    padding-left: 0;
    text-align: center;
  }

  .auth-hero-copy {
    margin-inline: auto;
  }

  .auth-network {
    width: 100%;
    max-width: 690px;
    margin-inline: auto;
    transform: scale(.82);
    transform-origin: center;
    margin-top: -2px;
    margin-bottom: -30px;
  }

  .auth-benefits {
    margin-inline: auto;
    text-align: left;
  }

  .auth-card {
    padding: 43px 42px 38px;
  }
}

@media (max-width: 620px) {
  .auth-topbar {
    height: 68px;
    padding-inline: 20px;
  }

  .auth-brand {
    font-size: 25px;
  }

  .auth-icon-button {
    display: none;
  }

  .auth-get-started {
    min-width: 118px;
    height: 40px;
    font-size: 11px;
  }

  .auth-shell {
    min-height: auto;
    padding: 35px 18px 45px;
  }

  .auth-eyebrow {
    margin-bottom: 20px;
    font-size: 10px;
