  box-sizing: border-box;

  padding: 0 20px;

  border: 1px solid #00d4e8;
  border-radius: 16px;

  background: #00c8df;
  color: #02050a;

  font-size: 15px;
  font-weight: 800;
  letter-spacing: 0.04em;

  cursor: pointer;

  box-shadow: 0 8px 28px rgba(0, 0, 0, 0.25);

  z-index: 9998;

  transition:
    background 0.2s ease,
    transform 0.2s ease;
}

.chainlab-chat-launcher:hover {
  background: #36d8e8;
  transform: translateY(-2px);
}

.chainlab-chat-launcher-icon {
  font-size: 20px;
  line-height: 1;
}

/* =====================================================
   FLOATING CHAT WINDOW
===================================================== */

.chainlab-chatbox {
  position: fixed !important;

  right: 24px !important;
  bottom: 96px !important;

  top: auto !important;
  left: auto !important;

  width: 380px;
  max-width: calc(100vw - 32px);

  height: 520px;
  max-height: calc(100dvh - 125px);

  display: flex;
  flex-direction: column;

  box-sizing: border-box;

  overflow: hidden;

  background: #080d18;
  color: #f5f7fa;

  border: 1px solid #263142;
  border-radius: 22px;

  box-shadow: 0 18px 60px rgba(0, 0, 0, 0.45);

  z-index: 9999;
}

/* =====================================================
   CHAT HEADER
===================================================== */

.chainlab-chat-header {
  display: flex;
  align-items: center;
  justify-content: space-between;

  padding: 20px;

  border-bottom: 1px solid #263142;

  flex-shrink: 0;
}

.chainlab-chat-label {
  color: #00c8df;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.08em;
}

.chainlab-chat-header h2 {
  margin: 8px 0 0;
  font-size: 20px;
  font-weight: 800;
}

.chainlab-chat-close {
  width: 38px;
  height: 38px;

  display: flex;
  align-items: center;
  justify-content: center;

  border: 1px solid #263142;
  border-radius: 10px;

  background: #101827;
  color: #f5f7fa;

  font-size: 25px;

  cursor: pointer;
}

.chainlab-chat-close:hover {
  background: #1b2739;
}

/* =====================================================
   CHAT MESSAGES
===================================================== */

.chainlab-chat-messages {
  flex: 1;
  min-height: 0;

  display: flex;
  flex-direction: column;
  gap: 12px;

  overflow-y: auto;

  padding: 20px;
}

.chainlab-message {
  max-width: 90%;

  padding: 12px 15px;

  border-radius: 14px;

  font-size: 14px;
  line-height: 1.6;

  overflow-wrap: anywhere;
}

.assistant-message {
  align-self: flex-start;

  background: #111c2e;
  color: #e7edf5;

  border: 1px solid #263142;
}

.user-message {
  align-self: flex-end;

  background: #00c8df;
  color: #02050a;

  font-weight: 600;
}

/* =====================================================
   QUICK QUESTIONS
===================================================== */

.chainlab-chat-quick {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;

  padding: 12px 16px;

  border-top: 1px solid #263142;
}

.chainlab-chat-quick button {
  padding: 9px 12px;

  border: 1px solid #263142;
  border-radius: 20px;

  background: #101827;
  color: #dce5ef;

  font-size: 12px;
  cursor: pointer;

  transition:
    background 0.2s ease,
    border-color 0.2s ease;
}

.chainlab-chat-quick button:hover {
  background: #17243a;
  border-color: #00c8df;
}

/* =====================================================
   CHAT INPUT
===================================================== */

.chainlab-chat-input {
  display: flex;
  align-items: center;
  gap: 10px;

  padding: 14px 16px;

  border-top: 1px solid #263142;

  flex-shrink: 0;
}

.chainlab-chat-input input {
  flex: 1;
  min-width: 0;
  height: 48px;

  box-sizing: border-box;

  padding: 0 14px;

  border: 1px solid #263142;
  border-radius: 12px;

  outline: none;

  background: #f3f5f8;
  color: #101827;

  font-size: 14px;
}

.chainlab-chat-input input:focus {
  border-color: #00c8df;
  box-shadow: 0 0 0 2px rgba(0, 200, 223, 0.15);
}

.chainlab-chat-input input::placeholder {
  color: #7b8797;
}

.chainlab-chat-input button {
  width: 48px;
  min-width: 48px;
  height: 48px;

  display: flex;
  align-items: center;
  justify-content: center;

  border: none;
  border-radius: 12px;

  background: #00c8df;
  color: #02050a;

  font-size: 24px;
  font-weight: 700;

  cursor: pointer;
}

.chainlab-chat-input button:hover {
  background: #36d8e8;
}

/* =====================================================
   MOBILE RESPONSIVENESS
===================================================== */

@media (max-width: 600px) {
  .chainlab-utility-inner {
    min-height: 68px;
    padding: 8px 12px;
  }

  .chainlab-toolbar-center {
    gap: 8px;
  }

  .chainlab-tools {
    gap: 8px;
  }

  .chainlab-tool-button {
    width: 52px;
    min-width: 52px;
    height: 52px;
    min-height: 52px;

    border-radius: 14px;

    font-size: 17px;
  }

  .chainlab-toolbar-center .chainlab-device-button {
    width: 52px;
    min-width: 52px;
    height: 52px;
    min-height: 52px;

    border-radius: 14px;
  }

  .chainlab-chat-launcher {
    right: 16px !important;
    bottom: 16px !important;

    width: 128px;
    min-width: 128px;
    height: 52px;

    border-radius: 14px;
  }

  .chainlab-chatbox {
    right: 12px !important;
    bottom: 78px !important;

    width: calc(100vw - 24px);

    height: 500px;
    max-height: calc(100dvh - 100px);

    border-radius: 18px;
  }
