/* =========================================
   DEVICE PREVIEW CONTROL
   ========================================= */

.device-preview-control {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  z-index: 1000;
}

/* =========================================
   UIVERSE-STYLE DEVICE BUTTON
   ========================================= */

.device-preview-button {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;

  padding: 12px 24px;

  background-color: #212121;
  color: #fefefe;

  border: 2px solid #fefefe;
  border-radius: 4px;

  font-family: inherit;
  font-size: 14px;
  font-weight: 600;
  letter-spacing: 0.5px;
  text-transform: uppercase;

  cursor: pointer;
  white-space: nowrap;
  isolation: isolate;
  overflow: hidden;

  transition:
    color 0.3s ease,
    border-color 0.3s ease,
    background-color 0.3s ease;
}

/* Horizontal animation layer */

.device-preview-button::before {
  content: "";

  position: absolute;

  top: 6px;
  left: -2px;

  width: calc(100% + 4px);
  height: calc(100% - 12px);

  background-color: #212121;

  transform: scaleY(1);
  transform-origin: center;

  transition: transform 0.3s ease-in-out;

  z-index: -1;
}

/* Vertical animation layer */

.device-preview-button::after {
  content: "";

  position: absolute;

  left: 6px;
  top: -2px;

  height: calc(100% + 4px);
  width: calc(100% - 12px);

  background-color: #212121;

  transform: scaleX(1);
  transform-origin: center;

  transition:
    transform 0.3s ease-in-out;

  transition-delay: 0.5s;

  z-index: -1;
}

/* Animate when hovering */

.device-preview-button:hover::before {
  transform: scaleY(0);
}

.device-preview-button:hover::after {
  transform: scaleX(0);
}

/* Keep the text above the animation */

.device-preview-button-text,
.device-preview-chevron {
  position: relative;
  z-index: 3;
}

/* Chevron */

.device-preview-chevron {
  font-size: 16px;
  line-height: 1;
}

/* Hover appearance */

.device-preview-button:hover {
  color: #ffffff;
  border-color: #ffffff;
}

/* Keyboard accessibility */

.device-preview-button:focus-visible {
  outline: 2px solid #ffffff;
  outline-offset: 4px;
}

/* Pressed appearance */

.device-preview-button:active {
  transform: scale(0.98);
}

/* =========================================
   DEVICE PREVIEW DROPDOWN
   ========================================= */

.device-preview-menu {
  position: absolute;

  top: calc(100% + 10px);
  right: 0;

  min-width: 200px;

  padding: 6px;

  background-color: #212121;
  color: #fefefe;

  border: 1px solid rgba(255, 255, 255, 0.2);
  border-radius: 8px;

  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);

  display: flex;
  flex-direction: column;
  gap: 4px;

  z-index: 1001;

  animation: device-menu-appear 0.2s ease-out;
}

/* Dropdown animation */

@keyframes device-menu-appear {
  from {
    opacity: 0;
    transform: translateY(-5px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* Dropdown options */

.device-preview-option {
  display: flex;
  align-items: center;
  justify-content: space-between;

  width: 100%;

  padding: 12px 14px;

  background-color: transparent;
  color: #e5e5e5;

  border: 1px solid transparent;
  border-radius: 5px;

  font-family: inherit;
  font-size: 13px;
  text-align: left;

  cursor: pointer;

  transition:
    background-color 0.2s ease,
    color 0.2s ease,
    border-color 0.2s ease;
}

/* Hover */

.device-preview-option:hover {
  background-color: #333333;
  color: #ffffff;
}

/* Selected option */

.device-preview-option.active {
  background-color: #303030;
  color: #ffffff;
  border-color: rgba(255, 255, 255, 0.3);
}

/* Selected checkmark */

.device-preview-check {
  color: #ffffff;
  font-size: 14px;
  font-weight: 700;
}

/* Keyboard accessibility */

.device-preview-option:focus-visible {
  outline: 2px solid #ffffff;
  outline-offset: -2px;
}

/* =========================================
   LIGHT MODE
   ========================================= */

html[data-theme="light"] .device-preview-button {
  background-color: #e8e8e8;
  color: #212121;
  border-color: #212121;
}

html[data-theme="light"] .device-preview-button::before,
html[data-theme="light"] .device-preview-button::after {
  background-color: #e8e8e8;
}

html[data-theme="light"] .device-preview-button:hover {
  color: #111111;
  border-color: #111111;
}

html[data-theme="light"] .device-preview-menu {
  background-color: #e8e8e8;
  color: #212121;
  border-color: rgba(0, 0, 0, 0.2);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.15);
}

html[data-theme="light"] .device-preview-option {
  color: #212121;
}

html[data-theme="light"] .device-preview-option:hover {
  background-color: #d5d5d5;
  color: #111111;
}

html[data-theme="light"] .device-preview-option.active {
  background-color: #d0d0d0;
  color: #111111;
  border-color: rgba(0, 0, 0, 0.2);
}

