.language-selector select {
  position: relative;
  z-index: 100000;

  display: inline-block;

  min-height: 30px;
  max-width: 160px;
  padding: 4px 8px;

  border: 1px solid transparent;
  border-radius: 5px;

  background: var(--control-bg, transparent);
  color: var(--text-color, inherit);

  font-family: inherit;
  font-size: inherit;
  font-weight: 500;

  cursor: pointer;
  pointer-events: auto;
}

.language-selector select:focus {
