}

/* =========================================================
   CHAINLAB — FINAL TOOLBAR INTERACTION FIX
   This overrides conflicting older toolbar rules.
========================================================= */

/* The toolbar itself must accept mouse/touch interaction. */
.chainlab-utility-bar {
  pointer-events: auto !important;
  position: fixed !important;
  z-index: 2147483000 !important;
}

/* The toolbar row must also accept interaction. */
.chainlab-utility-inner {
  pointer-events: auto !important;
  position: relative !important;
  z-index: 2147483001 !important;
}

/* Center controls must sit above the navigation layer. */
.chainlab-toolbar-center {
  position: relative !important;
  z-index: 2147483003 !important;
  pointer-events: auto !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
}

/* Language selector gets its own interaction layer. */
.language-selector {
  position: relative !important;
  z-index: 2147483004 !important;
  pointer-events: auto !important;
  isolation: isolate;
}

/* The actual native dropdown must receive the click. */
.language-selector select {
  position: relative !important;
  z-index: 2147483005 !important;
  pointer-events: auto !important;
  cursor: pointer !important;
  user-select: auto !important;
}

/* The language selector's decorative elements must not
   intercept the click intended for the select. */
.language-selector-icon,
.language-selector-label {
  pointer-events: none !important;
}

/* Keep the navigation from intercepting toolbar clicks. */
.chainlab-utility-inner > .site-header {
  pointer-events: none !important;
}

/* But the navigation's actual links remain clickable. */
.chainlab-utility-inner > .site-header a {
  pointer-events: auto !important;
}

/* Device controls remain interactive. */
.chainlab-toolbar-right,
.chainlab-toolbar-right *,
.device-preview-control,
.device-preview-control * {
  pointer-events: auto !important;
}

/* Existing ChainLab controls remain interactive. */
.chainlab-toolbar-center .chainlab-tools,
.chainlab-toolbar-center .chainlab-tools *,
.chainlab-toolbar-center button {
  pointer-events: auto !important;
}

/* Make sure no overflow rule clips the language menu. */
.chainlab-utility-bar,
.chainlab-utility-inner,
.chainlab-toolbar-center,
.language-selector {
  overflow: visible !important;
}

/* Native select appearance */
.language-selector select {
  appearance: auto !important;
  -webkit-appearance: auto !important;
  -moz-appearance: auto !important;
}

/* Desktop */
@media (min-width: 769px) {
  .chainlab-utility-bar {
    top: 16px !important;
    left: 24px !important;
    right: 160px !important;
    width: auto !important;
  }

  .chainlab-toolbar-center {
    flex: 0 0 auto !important;
  }
}

/* Mobile */
@media (max-width: 768px) {
  .chainlab-utility-bar {
    left: 12px !important;
    right: 12px !important;
    top: 12px !important;
  }

  .chainlab-toolbar-center {
    flex: 0 0 auto !important;
  }

  .language-selector select {
    min-width: 90px !important;
    max-width: 125px !important;
  }
}

/* =========================================================
   CHAINLAB — LANGUAGE SELECTOR LAYER FIX
   Fixes the header sitting above the language dropdown.
========================================================= */

/* Keep the toolbar interaction layer above the navigation. */
.chainlab-utility-bar {
  pointer-events: none !important;
  z-index: 2147483600 !important;
}

/* The toolbar container itself remains interactive. */
.chainlab-utility-inner {
  pointer-events: none !important;
  position: relative !important;
  z-index: 2147483601 !important;
}

/* Appearance + language controls must sit above the header. */
.chainlab-toolbar-center {
  position: relative !important;
  z-index: 2147483640 !important;
  pointer-events: auto !important;
}

/* Language selector gets the highest interaction layer. */
.language-selector {
  position: relative !important;
  z-index: 2147483645 !important;
  pointer-events: auto !important;
}

/* Native select must receive the mouse click. */
.language-selector select {
  position: relative !important;
  z-index: 2147483646 !important;
  pointer-events: auto !important;
  cursor: pointer !important;
}

/* The header must remain below the toolbar controls. */
.chainlab-utility-inner > .site-header,
header.site-header {
  z-index: 2147483000 !important;
}

/* Keep navigation links clickable. */
header.site-header a {
  pointer-events: auto !important;
}

/* Language selector's decorative elements must not block clicks. */
.language-selector-icon,
.language-selector-label {
  pointer-events: none !important;
}

/* Prevent clipping. */
.chainlab-utility-bar,
.chainlab-utility-inner,
.chainlab-toolbar-center,
.language-selector {
  overflow: visible !important;
}

/* =========================
   LANDING PAGE NAV ACTIONS
========================= */

.nav-actions {
  display: flex;
  align-items: center;
  gap: 10px;
}

.sign-in-nav-button {
  text-decoration: none;
  white-space: nowrap;
}

/* =========================================================
   CHAINLAB LOGIN PAGE
   Screenshot-inspired authentication UI
========================================================= */

.auth-page {
  min-height: 100vh;
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 48px 20px;
  background: #f3f3f3;
  color: #111111;
  box-sizing: border-box;
}

.auth-card {
  width: 100%;
  max-width: 380px;
  background: #ffffff;
  border-radius: 28px;
  padding: 42px 38px 38px;
  box-sizing: border-box;
  box-shadow: 0 18px 50px rgba(0, 0, 0, 0.12);
}

.auth-header {
  margin-bottom: 28px;
}

.auth-eyebrow {
  display: none;
}

.auth-header h1 {
  display: none;
}

.auth-subtitle {
  display: none;
}

/* =========================================================
   FORM
========================================================= */

.auth-form {
  width: 100%;
}

.auth-field {
  display: block;
  width: 100%;
  margin-bottom: 18px;
}

.auth-field > span {
  display: block;
  margin-bottom: 10px;
  font-size: 18px;
  line-height: 1.25;
  font-weight: 500;
  color: #111111;
}

.auth-input-wrapper {
  position: relative;
  width: 100%;
}

.auth-input-icon {
  position: absolute;
  left: 14px;
  top: 50%;
  transform: translateY(-50%);
  width: 24px;
  height: 24px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 22px;
  font-weight: 400;
  color: #111111;
  pointer-events: none;
}

.auth-input-icon.password-icon {
  left: 14px;
}

.auth-input-wrapper input {
  width: 100%;
  height: 62px;
  box-sizing: border-box;
  border: 1px solid #dedede;
  border-radius: 14px;
  background: #ffffff;
  color: #111111;
  padding: 0 16px 0 48px;
  font-size: 16px;
  outline: none;
  transition:
    border-color 0.2s ease,
    box-shadow 0.2s ease,
    background 0.2s ease;
}

.auth-input-wrapper input::placeholder {
  color: #777777;
  opacity: 1;
}

.auth-input-wrapper input:focus {
  border-color: #111111;
  box-shadow: 0 0 0 3px rgba(17, 17, 17, 0.08);
}

.auth-input-wrapper input:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

/* =========================================================
   REMEMBER / FORGOT PASSWORD
========================================================= */

.auth-options {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin: 2px 0 38px;
}

.remember-me {
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  cursor: pointer;
  font-size: 16px;
  color: #111111;
  white-space: nowrap;
}

.remember-me input {
  position: absolute;
  opacity: 0;
  pointer-events: none;
}

.custom-checkbox {
  width: 15px;
  height: 15px;
  border: 1.5px solid #777777;
  border-radius: 50%;
  display: inline-block;
  box-sizing: border-box;
  transition: all 0.2s ease;
}

.remember-me input:checked + .custom-checkbox {
  border-color: #111111;
  background: #111111;
  box-shadow: inset 0 0 0 3px #ffffff;
}

.forgot-password {
  border: 0;
  background: transparent;
  padding: 0;
  color: #2769ff;
  font-size: 16px;
  font-family: inherit;
  cursor: pointer;
  white-space: nowrap;
}

.forgot-password:hover {
  text-decoration: underline;
}

/* =========================================================
   SIGN IN BUTTON
========================================================= */

.auth-primary-button {
  width: 100%;
  height: 62px;
  border: 0;
  border-radius: 14px;
  background: #151616;
  color: #ffffff;
  font-family: inherit;
  font-size: 18px;
  font-weight: 700;
  cursor: pointer;
  transition:
    transform 0.2s ease,
    background 0.2s ease,
    opacity 0.2s ease;
}

.auth-primary-button:hover {
  background: #252626;
  transform: translateY(-1px);
}

.auth-primary-button:active {
  transform: translateY(0);
}

.auth-primary-button:disabled {
  opacity: 0.65;
  cursor: not-allowed;
  transform: none;
}

/* =========================================================
   STATUS MESSAGE
========================================================= */

.auth-message {
  margin: 18px 0 0;
  text-align: center;
  font-size: 14px;
  line-height: 1.5;
  color: #555555;
}

/* =========================================================
   SIGN UP
========================================================= */

.auth-switch {
  margin: 36px 0 30px;
  text-align: center;
  color: #111111;
  font-size: 16px;
  line-height: 1.5;
}

.auth-switch a {
  color: #2769ff;
  text-decoration: none;
  font-weight: 500;
}

.auth-switch a:hover {
  text-decoration: underline;
}

/* =========================================================
   OR WITH
========================================================= */

.auth-divider {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 0 30px;
}

.auth-divider::before,
.auth-divider::after {
  content: "";
  display: none;
}

.auth-divider span {
  font-size: 16px;
  color: #111111;
}

/* =========================================================
   GOOGLE / APPLE
========================================================= */

.auth-social-buttons {
  width: 100%;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}

.auth-social-button {
  height: 62px;
  border: 1px solid #dedede;
  border-radius: 14px;
  background: #ffffff;
  color: #111111;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  font-family: inherit;
  font-size: 16px;
  font-weight: 500;
  cursor: pointer;
  transition:
    background 0.2s ease,
    border-color 0.2s ease,
    transform 0.2s ease;
}

.auth-social-button:hover {
  background: #f7f7f7;
  border-color: #c8c8c8;
  transform: translateY(-1px);
}

.auth-social-button:active {
  transform: translateY(0);
}

.google-icon,
.apple-icon {
  width: 22px;
  height: 22px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.google-icon svg,
.apple-icon svg {
  display: block;
}

/* =========================================================
   BACK LINK
========================================================= */

.auth-back {
  display: block;
  margin-top: 30px;
  text-align: center;
  color: #666666;
  text-decoration: none;
  font-size: 14px;
}

.auth-back:hover {
  color: #111111;
}

/* =========================================================
   DARK MODE
   Supports ChainLab themes using data-theme="dark"
   or the .dark class.
========================================================= */

html[data-theme="dark"] .auth-page,
html.dark .auth-page {
  background: #202020;
  color: #ffffff;
}

html[data-theme="dark"] .auth-card,
html.dark .auth-card {
  background: #ffffff;
  color: #111111;
}

/*
   Screenshot-style dark mode variant:
   The page becomes charcoal while the login card remains
   white, preserving the strong contrast from the reference.
*/

html[data-theme="dark"] .auth-input-wrapper input,
html.dark .auth-input-wrapper input {
  background: #ffffff;
  color: #111111;
  border-color: #dedede;
}

html[data-theme="dark"] .auth-input-wrapper input::placeholder,
html.dark .auth-input-wrapper input::placeholder {
  color: #777777;
}

html[data-theme="dark"] .auth-field > span,
html.dark .auth-field > span {
  color: #111111;
}

html[data-theme="dark"] .auth-input-icon,
html.dark .auth-input-icon {
  color: #111111;
}

html[data-theme="dark"] .remember-me,
html.dark .remember-me {
  color: #111111;
}

html[data-theme="dark"] .auth-divider span,
html.dark .auth-divider span {
  color: #111111;
}

html[data-theme="dark"] .auth-switch,
html.dark .auth-switch {
  color: #111111;
}

html[data-theme="dark"] .auth-social-button,
html.dark .auth-social-button {
  background: #ffffff;
  color: #111111;
  border-color: #dedede;
}

html[data-theme="dark"] .auth-social-button:hover,
html.dark .auth-social-button:hover {
  background: #f7f7f7;
}

html[data-theme="dark"] .auth-back,
html.dark .auth-back {
  color: #777777;
}

html[data-theme="dark"] .auth-back:hover,
html.dark .auth-back:hover {
  color: #111111;
}

/* =========================================================
   MOBILE
========================================================= */

@media (max-width: 520px) {
  .auth-page {
    min-height: 100vh;
    padding: 20px 12px;
    align-items: center;
  }

  .auth-card {
    max-width: 100%;
    padding: 34px 26px 32px;
    border-radius: 26px;
  }

  .auth-field > span {
    font-size: 17px;
  }

  .auth-input-wrapper input {
    height: 62px;
  }

  .auth-options {
    margin-bottom: 34px;
  }

  .remember-me,
  .forgot-password {
    font-size: 15px;
  }

  .auth-social-buttons {
    gap: 10px;
  }

  .auth-social-button {
    height: 60px;
    font-size: 15px;
  }
}

@media (max-width: 380px) {
  .auth-card {
    padding-left: 20px;
    padding-right: 20px;
  }

  .auth-options {
    align-items: flex-start;
  }

  .remember-me,
  .forgot-password {
    font-size: 14px;
  }
}

/* =========================================================
   CHAINLAB DASHBOARD — LIGHT / DARK MODE
   Add this entire block to the bottom of app/globals.css.
========================================================= */

.dashboard-page {
  min-height: 100vh;
  width: 100%;
  box-sizing: border-box;
  padding: 42px 30px 70px;
  background: #f7f9fc;
  color: #10131a;
}

.dashboard-shell {
  width: min(1480px, 100%);
  margin: 0 auto;
}

/* ---------------------------------------------------------
   GLOBAL DASHBOARD TYPOGRAPHY
--------------------------------------------------------- */

.dashboard-page *,
.dashboard-page *::before,
.dashboard-page *::after {
  box-sizing: border-box;
}

.dashboard-label {
  display: block;
  margin: 0;
  color: #286cf6;
  font-size: 12px;
  line-height: 1.2;
  font-weight: 800;
  letter-spacing: 0.08em;
}

.dashboard-page h1,
.dashboard-page h2,
.dashboard-page h3,
.dashboard-page p {
  margin-top: 0;
}

.dashboard-page h1,
.dashboard-page h2,
.dashboard-page h3 {
  letter-spacing: -0.03em;
}

.dashboard-page a {
  text-decoration: none;
}

/* ---------------------------------------------------------
   HEADER
--------------------------------------------------------- */

.dashboard-header {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 320px 390px;
  align-items: center;
  gap: 24px;
  margin-bottom: 24px;
}

.dashboard-welcome h1 {
  margin: 8px 0 7px;
  font-size: clamp(34px, 4vw, 50px);
  line-height: 1;
  font-weight: 800;
  color: #10131a;
}

.dashboard-welcome p {
  max-width: 650px;
  margin-bottom: 0;
  color: #536174;
  font-size: 16px;
  line-height: 1.55;
}

.dashboard-user-card {
  min-height: 116px;
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 17px;
  border: 1px solid #e1e6ef;
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.88);
  box-shadow: 0 10px 30px rgba(25, 38, 60, 0.06);
}

.dashboard-avatar {
  width: 64px;
  height: 64px;
  flex: 0 0 64px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: linear-gradient(135deg, #216cff, #7956ff);
  color: #ffffff;
  font-size: 22px;
  font-weight: 800;
}

.dashboard-user-info {
  min-width: 0;
}

.dashboard-user-info strong,
.dashboard-user-info span,
.dashboard-user-info small {
  display: block;
}

.dashboard-user-info strong {
  overflow: hidden;
  color: #151922;
  font-size: 16px;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.dashboard-user-info span {
  overflow: hidden;
  margin-top: 3px;
  color: #667287;
  font-size: 13px;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.dashboard-user-info small {
  margin-top: 8px;
  color: #536174;
  font-size: 12px;
}

.dashboard-user-info small i {
  display: inline-block;
  width: 8px;
  height: 8px;
  margin-right: 6px;
  border-radius: 50%;
  background: #12c987;
}

.dashboard-actions {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.dashboard-primary-button {
  min-height: 48px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  padding: 0 22px;
  border: 0;
  border-radius: 14px;
  background: linear-gradient(90deg, #285dff, #11aeea);
  color: #ffffff;
  font-size: 13px;
  font-weight: 800;
  letter-spacing: 0.02em;
  box-shadow: 0 10px 24px rgba(39, 103, 246, 0.18);
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.dashboard-primary-button:hover {
  transform: translateY(-1px);
  box-shadow: 0 14px 28px rgba(39, 103, 246, 0.24);
}

.dashboard-action-row {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
}

.dashboard-secondary-button {
  min-height: 44px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  padding: 0 11px;
  border: 1px solid #dfe5ee;
  border-radius: 12px;
  background: #ffffff;
  color: #202632;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.02em;
  transition: border-color 0.2s ease, background 0.2s ease;
}

.dashboard-secondary-button:hover {
  border-color: #c6d0df;
  background: #f5f8fc;
}

/* ---------------------------------------------------------
   SECTIONS
--------------------------------------------------------- */

.dashboard-section,
.dashboard-card {
  border: 1px solid #e1e6ef;
  background: rgba(255, 255, 255, 0.92);
  box-shadow: 0 10px 34px rgba(26, 40, 65, 0.055);
}

.dashboard-section {
  border-radius: 20px;
  padding: 20px;
}

.dashboard-section-heading {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 18px;
}

.dashboard-section-heading h2 {
  margin: 5px 0 0;
  color: #10131a;
  font-size: 25px;
  line-height: 1.1;
  font-weight: 800;
}

.dashboard-section-heading p {
  margin: 5px 0 0;
  color: #738096;
  font-size: 13px;
  line-height: 1.45;
}

.dashboard-section-heading > p {
  align-self: center;
}

/* ---------------------------------------------------------
   QUICK ACCESS
--------------------------------------------------------- */

.dashboard-quick-section {
  margin-bottom: 18px;
}

.dashboard-quick-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 14px;
}

.dashboard-quick-card {
  position: relative;
  min-height: 192px;
  overflow: hidden;
  padding: 18px 20px;
  border: 1px solid #e2e7ef;
  border-radius: 17px;
  color: #10131a;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.dashboard-quick-card:hover {
  transform: translateY(-2px);
  box-shadow: 0 14px 28px rgba(20, 35, 60, 0.09);
}

.dashboard-quick-icon {
  width: 39px;
  height: 39px;
  display: grid;
  place-items: center;
  margin-bottom: 13px;
  border-radius: 11px;
  background: #ffffff;
  font-size: 21px;
  font-weight: 800;
  box-shadow: 0 5px 16px rgba(20, 35, 60, 0.08);
}

.dashboard-quick-number {
  position: absolute;
  top: 17px;
  right: 19px;
  font-size: 25px;
  font-weight: 800;
  opacity: 0.9;
}

.dashboard-quick-card h3 {
  margin-bottom: 7px;
  font-size: 15px;
  font-weight: 800;
}

.dashboard-quick-card p {
  max-width: 260px;
  margin-bottom: 18px;
  color: #56647a;
  font-size: 13px;
  line-height: 1.5;
}

.dashboard-quick-card strong {
  font-size: 11px;
  font-weight: 800;
}

.dashboard-quick-card strong span,
.dashboard-text-link span,
.dashboard-module-button span {
  margin-left: 7px;
}

.dashboard-accent-blue {
  background: linear-gradient(145deg, #eef6ff, #f8fbff);
  color: #1669e8;
}

.dashboard-accent-gold {
  background: linear-gradient(145deg, #fff9e9, #fffdf7);
  color: #d18d12;
}

.dashboard-accent-purple {
  background: linear-gradient(145deg, #f5f0ff, #fcfaff);
  color: #7045e9;
}

.dashboard-accent-green {
  background: linear-gradient(145deg, #edfcf7, #f9fffc);
  color: #10ae7b;
}

.dashboard-accent-blue h3,
.dashboard-accent-gold h3,
.dashboard-accent-purple h3,
.dashboard-accent-green h3 {
  color: #151922;
}

/* ---------------------------------------------------------
   OVERVIEW
--------------------------------------------------------- */

.dashboard-overview {
  display: grid;
  grid-template-columns: 1.15fr 1fr 1fr;
  gap: 14px;
  margin-bottom: 18px;
}

.dashboard-card {
  min-height: 138px;
  display: flex;
  gap: 14px;
  padding: 19px;
  border-radius: 17px;
}

.dashboard-stat-icon {
  width: 39px;
  height: 39px;
  flex: 0 0 39px;
  display: grid;
  place-items: center;
  border-radius: 11px;
  font-size: 19px;
  font-weight: 800;
}

.dashboard-stat-blue {
  background: #e8f1ff;
  color: #236eff;
}

.dashboard-stat-gold {
  background: #fff3d8;
  color: #d18d12;
}

.dashboard-stat-purple {
  background: #eee8ff;
  color: #7045e9;
}

.dashboard-stat-content {
  width: 100%;
}

.dashboard-stat-line {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
}

.dashboard-stat-line strong,
.dashboard-stat-card > div:last-child > strong {
  display: block;
  margin: 4px 0 1px;
  color: #10131a;
  font-size: 29px;
  line-height: 1;
  font-weight: 800;
}

.dashboard-stat-line p,
.dashboard-stat-card p {
  margin: 0;
  color: #6d7a8d;
  font-size: 12px;
  line-height: 1.4;
}

.dashboard-progress-track {
  width: 100%;
  height: 9px;
  overflow: hidden;
  margin-top: 14px;
  border-radius: 999px;
  background: #e8edf4;
}

.dashboard-progress-track > div {
  height: 100%;
  min-width: 0;
  border-radius: inherit;
  background: linear-gradient(90deg, #2372ff, #18a9eb);
  transition: width 0.4s ease;
}

.dashboard-text-link {
  display: inline-flex;
  align-items: center;
  margin-top: 12px;
  color: #2568ed;
  font-size: 10px;
  font-weight: 800;
}

.dashboard-locked {
  display: block;
  margin: 4px 0 2px;
  color: #10131a;
  font-size: 22px;
  line-height: 1;
  font-weight: 800;
}

/* ---------------------------------------------------------
   MAIN COURSE / PROFILE
--------------------------------------------------------- */

.dashboard-main-grid {
  display: grid;
  grid-template-columns: minmax(0, 2fr) minmax(310px, 0.95fr);
  gap: 18px;
  margin-bottom: 18px;
}

.dashboard-course-section,
.dashboard-profile-section {
  min-width: 0;
}

.dashboard-course-section .dashboard-section-heading > strong {
  color: #4e5d72;
  font-size: 13px;
  white-space: nowrap;
}

.dashboard-module-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
}

.dashboard-module {
  min-width: 0;
  padding: 13px;
  border: 1px solid #e0e6ef;
  border-radius: 14px;
  background: #fbfcfe;
}

.dashboard-module-top {
  display: flex;
  align-items: center;
  gap: 9px;
  margin-bottom: 19px;
}

.dashboard-module-icon {
  width: 34px;
  height: 34px;
  flex: 0 0 34px;
  display: grid;
  place-items: center;
  border-radius: 10px;
  font-size: 18px;
  font-weight: 800;
}

.dashboard-module-top > div {
  min-width: 0;
  flex: 1;
  display: flex;
  justify-content: space-between;
  gap: 5px;
}

.dashboard-module-top strong {
  overflow: hidden;
  color: #202631;
  font-size: 13px;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.dashboard-module-top > div > span {
  color: #354256;
  font-size: 12px;
  font-weight: 700;
}

.dashboard-module .dashboard-progress-track {
  height: 7px;
  margin-top: 0;
}

.dashboard-module p {
  margin: 7px 0 12px;
  color: #6c788b;
  font-size: 11px;
}

.dashboard-module-button {
  min-height: 34px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  border: 1px solid currentColor;
  border-radius: 9px;
  font-size: 10px;
  font-weight: 800;
}

/* Module accents */

.dashboard-module-blue {
  color: #216eff;
}

.dashboard-module-blue .dashboard-module-icon {
  background: #e5efff;
}

.dashboard-module-green {
  color: #0bb685;
}

.dashboard-module-green .dashboard-module-icon {
  background: #e2faf2;
}

.dashboard-module-gold {
  color: #db9716;
}

.dashboard-module-gold .dashboard-module-icon {
  background: #fff1d1;
}

.dashboard-module-red {
  color: #ee5963;
}

.dashboard-module-red .dashboard-module-icon {
  background: #ffe8eb;
}

/* Profile */

.dashboard-profile-section {
  padding: 19px;
}

.dashboard-profile-heading {
  display: flex;
  align-items: flex-start;
  gap: 11px;
  margin-bottom: 18px;
}

.dashboard-profile-icon {
  width: 38px;
  height: 38px;
  flex: 0 0 38px;
  display: grid;
  place-items: center;
  border-radius: 11px;
  background: #eaf2ff;
  color: #216eff;
  font-size: 19px;
}

.dashboard-profile-heading h2 {
  margin: 4px 0 3px;
  color: #151922;
  font-size: 18px;
  line-height: 1.1;
}

.dashboard-profile-heading p {
  margin: 0;
  color: #738096;
  font-size: 11px;
}

.dashboard-profile-details {
  overflow: hidden;
  border: 1px solid #e0e6ef;
  border-radius: 13px;
}

.dashboard-profile-row {
  min-height: 38px;
  display: grid;
  grid-template-columns: 25px 1fr auto;
  align-items: center;
  gap: 6px;
  padding: 7px 10px;
  border-bottom: 1px solid #e8edf3;
}

.dashboard-profile-row:last-child {
  border-bottom: 0;
}

.dashboard-profile-row > span {
  color: #5e6b7f;
  text-align: center;
}

.dashboard-profile-row label {
  color: #4c596c;
  font-size: 11px;
}

.dashboard-profile-row strong {
  max-width: 170px;
  overflow: hidden;
  color: #344055;
  font-size: 11px;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.dashboard-profile-row strong.dashboard-active {
  color: #08a976;
}

.dashboard-signout-button {
  width: 100%;
  min-height: 43px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  margin-top: 14px;
  border: 1px solid #d5dce6;
  border-radius: 11px;
  background: #ffffff;
  color: #151922;
  font-family: inherit;
  font-size: 11px;
  font-weight: 800;
  cursor: pointer;
  transition: background 0.2s ease, border-color 0.2s ease;
}

.dashboard-signout-button:hover {
  background: #f4f7fb;
  border-color: #c4cdd9;
}

/* ---------------------------------------------------------
   BADGES
--------------------------------------------------------- */

.dashboard-badges-section {
  margin-bottom: 18px;
}

.dashboard-badge-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
}

.dashboard-badge-card {
  display: flex;
  align-items: center;
  gap: 11px;
  min-width: 0;
  padding: 13px;
  border: 1px solid #e1e6ef;
  border-radius: 14px;
  background: #fbfcfe;
}

.dashboard-badge-icon {
  width: 42px;
  height: 42px;
  flex: 0 0 42px;
  display: grid;
  place-items: center;
  border-radius: 12px;
  background: #eef1f5;
  color: #7a8596;
  font-size: 13px;
  font-weight: 800;
}

.dashboard-badge-card h3 {
