/* ============================================================
   CHAINLAB — MODERN HEADER SYSTEM
   ============================================================ */

.chainlab-top-system {
  position: relative;
  z-index: 5000;
  width: 100%;
  padding: 18px 14px 0;
}


/* ============================================================
   TOP UTILITY BAR
   ============================================================ */

.chainlab-utility-bar {
  width: 100%;
  height: 64px;
  display: flex;
  align-items: center;
}

.chainlab-utility-inner {
  width: 100%;
  min-height: 64px;

  display: flex;
  align-items: center;
  justify-content: space-between;

  padding: 0 34px;

  border-radius: 22px;

  background: rgba(255, 255, 255, 0.68);

  border: 1px solid rgba(255, 255, 255, 0.85);

  box-shadow:
    0 8px 30px rgba(28, 69, 126, 0.05),
    inset 0 1px 0 rgba(255, 255, 255, 0.85);

  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
}


/* ============================================================
   LEFT UTILITY CONTROLS
   ============================================================ */

.chainlab-toolbar-left {
  display: flex;
  align-items: center;
  gap: 20px;

  min-width: 0;
}

.chainlab-toolbar-divider {
  width: 1px;
  height: 28px;

  background: rgba(86, 105, 130, 0.22);

  flex-shrink: 0;
}


/* ============================================================
   CHAINLAB CONTROLS
   ============================================================ */

.chainlab-toolbar-left .chainlab-controls {
  display: flex;
  align-items: center;
  gap: 8px;
}


/* ============================================================
   LANGUAGE
   ============================================================ */

.language-selector {
  position: relative;

  display: flex;
  align-items: center;

  gap: 9px;

  height: 40px;

  padding: 0 4px;

  color: #172033;

  font-size: 15px;
  font-weight: 600;

  white-space: nowrap;
}

.language-selector-icon {
  display: flex;
  align-items: center;
  justify-content: center;

  width: 22px;
  height: 22px;

  font-size: 19px;
}

.language-selector-label {
  display: none;
}

.language-selector select {
  appearance: none;
  -webkit-appearance: none;

  border: 0;
  outline: 0;

  background: transparent;

  color: #172033;

  font-family: inherit;

  font-size: 15px;
  font-weight: 600;

  cursor: pointer;

  padding: 5px 24px 5px 0;
}

.language-selector::after {
  content: "⌄";

  position: absolute;

  right: 2px;
  top: 50%;

  transform: translateY(-54%);

  pointer-events: none;

  color: #1b2739;

  font-size: 15px;
  font-weight: 700;
}

.language-selector select option {
  background: #ffffff;
  color: #111827;
}


/* ============================================================
   DEVICE
   ============================================================ */

.chainlab-toolbar-right {
  display: flex;
  align-items: center;
  justify-content: flex-end;

  margin-left: auto;
}

.device-preview-control {
  position: relative;

  display: flex;
  align-items: center;
}

.device-preview-button {
  height: 42px;

  display: inline-flex;
  align-items: center;
  justify-content: center;

  gap: 10px;

  padding: 0 4px;

  border: 0;
  border-radius: 10px;

  background: transparent;

  color: #172033;

  font-family: inherit;

  font-size: 15px;
  font-weight: 650;

  cursor: pointer;

  transition:
    background 0.2s ease,
    color 0.2s ease;
}

.device-preview-button:hover {
  background: rgba(23, 108, 255, 0.06);
}

.device-preview-icon {
  flex-shrink: 0;
}

.device-preview-button-text {
  text-transform: none;
}

.device-preview-chevron {
  font-size: 16px;
  line-height: 1;

  transform: translateY(-1px);
}


/* DEVICE MENU */

.device-preview-menu {
  position: absolute;

  top: calc(100% + 10px);
  right: 0;

  min-width: 210px;

  padding: 7px;

  border-radius: 15px;

  background: rgba(255, 255, 255, 0.98);

  border: 1px solid rgba(20, 35, 60, 0.09);

  box-shadow:
    0 20px 50px rgba(15, 30, 55, 0.14);

  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);

  z-index: 10000;
}

.device-preview-option {
  width: 100%;

  min-height: 42px;

  display: flex;
  align-items: center;
  justify-content: space-between;

  padding: 0 12px;

  border: 0;
  border-radius: 9px;

  background: transparent;

  color: #172033;

  font-family: inherit;

  font-size: 14px;

  cursor: pointer;

  text-align: left;
}

.device-preview-option:hover,
.device-preview-option.active {
  background: rgba(23, 108, 255, 0.08);
}

.device-preview-check {
  color: #176cff;
  font-weight: 800;
}


/* ============================================================
   MAIN NAVIGATION
   ============================================================ */

.site-header {
  width: 100%;

  margin-top: 0;

  border-radius: 0 0 28px 28px;

  background: rgba(255, 255, 255, 0.88);

  border: 1px solid rgba(255, 255, 255, 0.92);

  box-shadow:
    0 18px 40px rgba(36, 74, 125, 0.09),
    inset 0 1px 0 rgba(255, 255, 255, 0.95);

  backdrop-filter: blur(22px);
  -webkit-backdrop-filter: blur(22px);

  position: relative;
  z-index: 5001;
}

.nav-inner {
  width: 100%;

  min-height: 102px;

  display: flex;
  align-items: center;

  padding: 0 28px 0 34px;

  gap: 30px;
}


/* ============================================================
   BRAND
   ============================================================ */

.brand {
  flex: 0 0 auto;

  display: inline-flex;
  align-items: center;

  color: #090d14;

  text-decoration: none;

  font-size: clamp(27px, 2.15vw, 39px);

  line-height: 1;

  font-weight: 900;

  letter-spacing: -2.8px;

  white-space: nowrap;

  transition:
    transform 0.2s ease,
    opacity 0.2s ease;
}

.brand:hover {
  transform: translateY(-1px);
  opacity: 0.78;
}


/* ============================================================
   MAIN NAV
   ============================================================ */

.main-nav {
  display: flex;
  align-items: center;

  gap: clamp(26px, 2.6vw, 52px);

  margin-left: clamp(25px, 3vw, 55px);

  flex: 1;
}

.main-nav a {
  position: relative;

  display: inline-flex;
  align-items: center;

  height: 102px;

  color: #111827;

  text-decoration: none;

  font-size: 16px;

  font-weight: 750;

  letter-spacing: -0.35px;

  white-space: nowrap;

  transition:
    color 0.2s ease,
    transform 0.2s ease;
}

.main-nav a::after {
  content: "";

  position: absolute;

  left: 0;
  right: 0;

  bottom: 27px;

  height: 2px;

  border-radius: 99px;

  background: #176cff;

  transform: scaleX(0);
  transform-origin: center;

  transition:
    transform 0.22s ease;
}

.main-nav a:hover {
  color: #176cff;
  transform: translateY(-1px);
}

.main-nav a:hover::after {
  transform: scaleX(1);
}


/* ============================================================
   RIGHT NAVIGATION
   ============================================================ */

.nav-actions {
  display: flex;
  align-items: center;

  gap: 16px;

  flex-shrink: 0;
}


/* SEARCH */

.nav-search-button {
  width: 50px;
  height: 50px;

  display: inline-flex;
  align-items: center;
  justify-content: center;

  border: 0;

  background: transparent;

  color: #111827;

  border-radius: 12px;

  cursor: pointer;

  transition:
    background 0.2s ease,
    color 0.2s ease,
    transform 0.2s ease;
}

.nav-search-button:hover {
  background: rgba(23, 108, 255, 0.07);
  color: #176cff;
  transform: translateY(-1px);
}


/* DIVIDER */

.nav-action-divider {
  width: 1px;
  height: 48px;

  background: rgba(87, 103, 126, 0.25);

  margin: 0 8px 0 0;
}


/* LOGIN */

.nav-login-button {
  min-width: 136px;
  height: 58px;

  display: inline-flex;
  align-items: center;
  justify-content: center;

  padding: 0 24px;

  border-radius: 12px;

  border: 1.5px solid #6c7788;

  background: #ffffff;

  color: #111827;

  text-decoration: none;

  font-size: 16px;

  font-weight: 750;

  transition:
    background 0.2s ease,
    border-color 0.2s ease,
    color 0.2s ease,
    transform 0.2s ease,
    box-shadow 0.2s ease;
}

.nav-login-button:hover {
  border-color: #176cff;
  color: #176cff;

  transform: translateY(-1px);

  box-shadow:
    0 7px 18px rgba(23, 108, 255, 0.12);
}


/* ============================================================
   START LEARNING
   ============================================================ */

.nav-button {
  min-width: 254px;
  height: 62px;

  display: inline-flex;
  align-items: center;
  justify-content: center;

  gap: 16px;

  padding: 0 27px;

