/* ============================================================
   CHAINLAB — SINGLE LINE HEADER
   Compact / Minimal / No Large Shapes
   ============================================================ */

.chainlab-header {
  position: sticky;
  top: 0;
  z-index: 9999;

  width: 100%;

  background: rgba(255, 255, 255, 0.94);

  border-bottom: 1px solid rgba(20, 30, 45, 0.08);

  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
}


/* ============================================================
   HEADER INNER
   ============================================================ */

.chainlab-header-inner {
  width: 100%;

  min-height: 62px;

  display: flex;
  align-items: center;

  gap: 16px;

  padding: 0 24px;

  white-space: nowrap;
}


/* ============================================================
   FONT SIZE CONTROLS
   ============================================================ */

.header-controls {
  display: flex;
  align-items: center;

  flex-shrink: 0;
}

.header-controls .chainlab-controls {
  display: flex;
  align-items: center;

  gap: 5px;

  font-size: 13px;
}


/* ============================================================
   ALL DIVIDERS
   ============================================================ */

.header-divider {
  width: 1px;
  height: 20px;

  flex-shrink: 0;

  background: rgba(40, 50, 65, 0.18);
}


/* ============================================================
   LANGUAGE
   ============================================================ */

.language-selector {
  position: relative;

  display: flex;
  align-items: center;

  flex-shrink: 0;

  height: 34px;

  gap: 5px;

  padding: 0;

  background: transparent;

  border: none;

  box-shadow: none;

  color: #172033;

  font-size: 13px;

  font-weight: 600;
}

.language-selector-icon {
  display: inline-flex;

  align-items: center;
  justify-content: center;

  font-size: 15px;

  width: 18px;
  height: 18px;
}

.language-selector-label {
  display: none;
}

.language-selector select {
  appearance: none;
  -webkit-appearance: none;

  border: none;
  outline: none;

  background: transparent;

  color: #172033;

  font-family: inherit;

  font-size: 13px;

  font-weight: 600;

  cursor: pointer;

  padding: 0 15px 0 0;
}

.language-selector::after {
  content: "⌄";

  position: absolute;

  right: 0;
  top: 50%;

  transform: translateY(-55%);

  pointer-events: none;

  font-size: 12px;

  color: #172033;
}

.language-selector select option {
  background: #ffffff;
  color: #111827;
}


/* ============================================================
   BRAND
   ============================================================ */

.chainlab-header .brand {
  display: inline-flex;
  align-items: center;

  flex-shrink: 0;

  color: #090d14;

  text-decoration: none;

  font-size: 21px;

  line-height: 1;

  font-weight: 900;

  letter-spacing: -1.5px;

  white-space: nowrap;

  margin-left: 2px;
}

.chainlab-header .brand:hover {
  opacity: 0.72;
}


/* ============================================================
   MAIN NAVIGATION
   ============================================================ */

.chainlab-header .main-nav {
  display: flex;
  align-items: center;

  flex: 1;

  gap: 22px;

  margin: 0;

  min-width: 0;
}

.chainlab-header .main-nav a {
  position: relative;

  display: inline-flex;
  align-items: center;

  height: 62px;

  color: #172033;

  text-decoration: none;

  font-size: 13px;

  line-height: 1;

  font-weight: 700;

  letter-spacing: -0.15px;

  white-space: nowrap;
}

.chainlab-header .main-nav a::after {
  content: "";

  position: absolute;

  left: 0;
  right: 0;

  bottom: 13px;

  height: 1.5px;

  background: #176cff;

  transform: scaleX(0);

  transition: transform 0.2s ease;
}

.chainlab-header .main-nav a:hover {
  color: #176cff;
}

.chainlab-header .main-nav a:hover::after {
  transform: scaleX(1);
}


/* ============================================================
   RIGHT ACTIONS
   ============================================================ */

.chainlab-header .nav-actions {
  display: flex;
  align-items: center;

  gap: 12px;

  flex-shrink: 0;

  margin-left: auto;
}


/* ============================================================
   SEARCH
   ============================================================ */

.chainlab-header .nav-search-button {
  width: 30px;
  height: 34px;

  display: inline-flex;

  align-items: center;
  justify-content: center;

  padding: 0;

  border: none;

  background: transparent;

  color: #172033;

  cursor: pointer;
}

.chainlab-header .nav-search-button:hover {
  color: #176cff;
}


/* ============================================================
   LOGIN
   ============================================================ */

.chainlab-header .nav-login-button {
  display: inline-flex;

  align-items: center;
  justify-content: center;

  height: 34px;

  padding: 0 14px;

  border: 1px solid #8993a1;

  border-radius: 6px;

  background: transparent;

  color: #172033;

  text-decoration: none;

  font-size: 13px;

  font-weight: 700;

  white-space: nowrap;

  transition:
    border-color 0.2s ease,
    color 0.2s ease;
}

.chainlab-header .nav-login-button:hover {
  border-color: #176cff;
  color: #176cff;
}


/* ============================================================
   START LEARNING
   ============================================================ */

.chainlab-header .nav-button {
  display: inline-flex;

  align-items: center;
  justify-content: center;

  gap: 9px;

  height: 36px;

  padding: 0 17px;

  border-radius: 6px;

  background: #176cff;

  color: #ffffff;

  text-decoration: none;

  font-size: 12px;

  font-weight: 800;

  white-space: nowrap;

  box-shadow: none;

  transition:
    background 0.2s ease,
    transform 0.2s ease;
}

.chainlab-header .nav-button span {
  font-size: 17px;

  line-height: 1;
}

.chainlab-header .nav-button:hover {
  background: #0759df;

  transform: translateY(-1px);

  box-shadow: none;
}


/* ============================================================
   DEVICE
   ============================================================ */

.chainlab-header .device-preview-control {
  position: relative;

  display: flex;
  align-items: center;

  flex-shrink: 0;
}

.chainlab-header .device-preview-button {
  height: 34px;

  display: inline-flex;

  align-items: center;
  justify-content: center;

  gap: 6px;

  padding: 0;

  border: none;

  border-radius: 0;

  background: transparent;

  color: #172033;

  font-family: inherit;

  font-size: 13px;

  font-weight: 650;

  cursor: pointer;
}

.chainlab-header .device-preview-button:hover {
  background: transparent;

  color: #176cff;
}

.chainlab-header .device-preview-icon {
  width: 17px;
  height: 17px;
}

.chainlab-header .device-preview-button-text {
  font-size: 13px;
}

.chainlab-header .device-preview-chevron {
  font-size: 12px;
}


/* ============================================================
   DEVICE DROPDOWN
   ============================================================ */

.chainlab-header .device-preview-menu {
  position: absolute;

  top: calc(100% + 8px);
  right: 0;

  min-width: 190px;

  padding: 5px;

  background: #ffffff;

  border: 1px solid rgba(20, 30, 45, 0.1);

  border-radius: 7px;

  box-shadow: 0 12px 30px rgba(20, 30, 45, 0.12);

  z-index: 10000;
}

.chainlab-header .device-preview-option {
  width: 100%;

  min-height: 36px;

  display: flex;

  align-items: center;
  justify-content: space-between;

  padding: 0 9px;

  border: none;

  border-radius: 4px;

  background: transparent;

  color: #172033;

  font-size: 12px;

  cursor: pointer;

  text-align: left;
}

.chainlab-header .device-preview-option:hover,
.chainlab-header .device-preview-option.active {
  background: #f1f5fb;
}

.chainlab-header .device-preview-check {
  color: #176cff;

  font-weight: 800;
}


/* ============================================================
   DARK MODE
   ============================================================ */

html[data-theme="dark"] .chainlab-header,
html.dark .chainlab-header {
  background: rgba(10, 15, 25, 0.94);

  border-bottom-color: rgba(255, 255, 255, 0.08);
}

html[data-theme="dark"] .chainlab-header .brand,
html.dark .chainlab-header .brand {
  color: #ffffff;
}

html[data-theme="dark"] .chainlab-header .main-nav a,
html.dark .chainlab-header .main-nav a {
  color: #e5e7eb;
}

html[data-theme="dark"] .chainlab-header .main-nav a:hover,
html.dark .chainlab-header .main-nav a:hover {
  color: #70a7ff;
}

html[data-theme="dark"] .language-selector,
html.dark .language-selector,
html[data-theme="dark"] .language-selector select,
html.dark .language-selector select {
  color: #e5e7eb;
}

html[data-theme="dark"] .language-selector::after,
html.dark .language-selector::after {
  color: #e5e7eb;
}

html[data-theme="dark"] .chainlab-header .device-preview-button,
html.dark .chainlab-header .device-preview-button {
  color: #e5e7eb;
}

html[data-theme="dark"] .chainlab-header .nav-search-button,
html.dark .chainlab-header .nav-search-button {
  color: #e5e7eb;
}

html[data-theme="dark"] .chainlab-header .nav-login-button,
html.dark .chainlab-header .nav-login-button {
  color: #ffffff;

  border-color: #667085;
}

html[data-theme="dark"] .chainlab-header .device-preview-menu,
html.dark .chainlab-header .device-preview-menu {
  background: #111827;

  border-color: rgba(255, 255, 255, 0.08);
}

html[data-theme="dark"] .chainlab-header .device-preview-option,
html.dark .chainlab-header .device-preview-option {
  color: #e5e7eb;
}

html[data-theme="dark"] .chainlab-header .device-preview-option:hover,
html.dark .chainlab-header .device-preview-option.active {
  background: #1f2937;
}


/* ============================================================
   RESPONSIVE — REDUCE SPACING
   ============================================================ */

@media (max-width: 1400px) {

  .chainlab-header-inner {
    gap: 11px;

    padding: 0 16px;
  }

  .chainlab-header .main-nav {
    gap: 16px;
  }

  .chainlab-header .main-nav a {
    font-size: 12px;
  }

  .chainlab-header .brand {
    font-size: 19px;
  }

  .chainlab-header .nav-actions {
    gap: 8px;
  }

  .chainlab-header .nav-button {
    padding: 0 12px;

    font-size: 11px;
  }

  .chainlab-header .nav-login-button {
    padding: 0 11px;

    font-size: 12px;
  }
}


/* ============================================================
   TABLET
   ============================================================ */

@media (max-width: 1100px) {

  .chainlab-header-inner {
    gap: 9px;

    padding: 0 12px;
  }

  .chainlab-header .main-nav {
    gap: 11px;
  }

  .chainlab-header .main-nav a {
    font-size: 11px;
  }

  .chainlab-header .brand {
    font-size: 17px;
  }

  .chainlab-header .nav-actions {
    gap: 6px;
  }

  .chainlab-header .nav-button {
    padding: 0 9px;

    font-size: 10px;
  }

  .chainlab-header .nav-login-button {
    padding: 0 8px;

    font-size: 11px;
  }

  .chainlab-header .device-preview-button-text {
    font-size: 11px;
  }

  .language-selector select {
    font-size: 11px;
  }
}


/* ============================================================
   MOBILE
   ============================================================ */

@media (max-width: 850px) {

  .chainlab-header {
    min-height: 58px;
  }

  .chainlab-header-inner {
    min-height: 58px;

    padding: 0 14px;
  }

  .chainlab-header .main-nav {
    display: none;
  }

  .chainlab-header .brand {
    font-size: 19px;

    margin-right: auto;
  }

  .chainlab-header .nav-actions {
    margin-left: 0;
  }

  .chainlab-header .nav-search-button,
  .chainlab-header .nav-action-divider,
  .chainlab-header .nav-login-button,
  .chainlab-header .nav-button {
    display: none;
  }
}


/* ============================================================
   SMALL MOBILE
   ============================================================ */

@media (max-width: 520px) {

  .chainlab-header-inner {
    gap: 8px;

    padding: 0 10px;
  }

  .chainlab-header .brand {
    font-size: 16px;
  }

  .header-divider {
    height: 18px;
  }

  .chainlab-header .device-preview-button-text {
    display: none;
  }

  .chainlab-header .device-preview-button {
    gap: 3px;
  }

  .language-selector select {
    max-width: 65px;

    overflow: hidden;

    font-size: 10px;
  }

  .chainlab-header .device-preview-icon {
    width: 16px;
    height: 16px;
  }
}

/* ============================================================
   CHAINLAB HEADER — FIXED WHILE SCROLLING
   ============================================================ */

.chainlab-header {
  position: fixed !important;
  top: 0 !important;
  left: 0 !important;
  right: 0 !important;

  width: 100% !important;

  z-index: 999999 !important;

  margin: 0 !important;

  background: rgba(255, 255, 255, 0.96) !important;

  border-bottom: 1px solid rgba(20, 30, 45, 0.08);

  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
}


/* Keep the website content below the fixed header */

body {
  padding-top: 62px;
}


/* Dark mode */

html[data-theme="dark"] .chainlab-header,
html.dark .chainlab-header {
  background: rgba(10, 15, 25, 0.96) !important;

  border-bottom-color: rgba(255, 255, 255, 0.08);
}


/* =========================================================
   CHAINLAB LOGIN — EXACT VISUAL DIRECTION OF THE REFERENCE
   Add this at the bottom of app/globals.css.
   ========================================================= */

body:has(.auth-page) {
  background: #02070d !important;
}

body:has(.auth-page) .site-header,
body:has(.auth-page) .chainlab-utility-bar,
body:has(.auth-page) .chainlab-utility-inner {
  display: none !important;
}

.auth-page {
  min-height: 100vh;
  background:
    radial-gradient(circle at 18% 58%, rgba(0, 128, 255, 0.13), transparent 28%),
    radial-gradient(circle at 83% 38%, rgba(0, 220, 255, 0.09), transparent 25%),
    #02070d;
  color: #f7fbff;
  overflow: hidden;
}

.auth-topbar {
  position: relative;
  z-index: 20;
  height: 76px;
  display: flex;
  align-items: center;
  gap: 48px;
  padding: 0 5.8vw;
  border-bottom: 1px solid rgba(48, 160, 255, 0.18);
  background: rgba(2, 7, 13, 0.84);
  backdrop-filter: blur(18px);
}

.auth-brand {
  flex: 0 0 auto;
  color: #fff;
  font-size: 30px;
  font-weight: 800;
  letter-spacing: -1.4px;
  text-decoration: none;
}

.auth-brand span {
  color: #19d8ff;
}

.auth-nav {
  display: flex;
  align-items: center;
  gap: 42px;
  margin-left: auto;
}

.auth-nav a {
  color: #c4d1df;
  font-size: 14px;
  font-weight: 500;
  letter-spacing: 0.02em;
  text-decoration: none;
  transition: color 180ms ease;
}

.auth-nav a:hover {
  color: #19d8ff;
}

.auth-top-actions {
  display: flex;
  align-items: center;
  gap: 20px;
}

.auth-icon-button {
  width: 32px;
  height: 32px;
  display: grid;
  place-items: center;
  padding: 0;
  border: 0;
  background: transparent;
  color: #9bb0c4;
  cursor: pointer;
}

.auth-icon-button svg {
  width: 22px;
  height: 22px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.6;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.auth-icon-button:hover {
  color: #19d8ff;
}

.auth-get-started {
  min-width: 148px;
  height: 45px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid #10cfff;
  border-radius: 11px;
  color: #fff;
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-decoration: none;
  box-shadow: 0 0 22px rgba(16, 207, 255, 0.1);
  transition: all 180ms ease;
}

.auth-get-started:hover {
  background: rgba(16, 207, 255, 0.1);
  box-shadow: 0 0 30px rgba(16, 207, 255, 0.2);
}

.auth-shell {
  position: relative;
  min-height: calc(100vh - 76px);
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(480px, 610px);
  gap: clamp(45px, 7vw, 115px);
  align-items: center;
  max-width: 1450px;
  margin: 0 auto;
  padding: 52px 5.8vw 65px;
}

.auth-background-grid {
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 0.24;
  background-image:
    linear-gradient(rgba(35, 152, 255, 0.075) 1px, transparent 1px),
    linear-gradient(90deg, rgba(35, 152, 255, 0.075) 1px, transparent 1px);
  background-size: 64px 64px;
  mask-image: linear-gradient(to bottom, transparent, black 15%, black 82%, transparent);
}

.auth-glow {
  position: absolute;
  pointer-events: none;
  border-radius: 999px;
  filter: blur(80px);
}

.auth-glow-one {
  width: 420px;
  height: 420px;
  left: 7%;
  top: 20%;
  background: rgba(0, 109, 255, 0.08);
}

.auth-glow-two {
  width: 320px;
  height: 320px;
  right: 19%;
  bottom: 10%;
  background: rgba(0, 229, 255, 0.06);
}

.auth-hero {
  position: relative;
  z-index: 2;
  min-width: 0;
  padding-left: clamp(0px, 2vw, 26px);
}

.auth-eyebrow {
  margin-bottom: 25px;
  color: #2edaff;
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.32em;
}

.auth-hero h1 {
  margin: 0;
  color: #f7fbff;
  font-size: clamp(58px, 5.8vw, 88px);
  line-height: 0.96;
  font-weight: 800;
  letter-spacing: -0.055em;
}

.auth-hero h1 span {
  color: #12d8ff;
  text-shadow: 0 0 30px rgba(18, 216, 255, 0.15);
}

.auth-hero-copy {
  max-width: 600px;
  margin: 27px 0 0;
  color: #b9c8d7;
  font-size: 19px;
  line-height: 1.6;
}

.auth-network {
  position: relative;
  height: 285px;
  max-width: 690px;
  margin: 8px 0 -2px;
}

.auth-network-core {
  position: absolute;
  left: 53%;
  top: 52%;
  width: 170px;
  height: 145px;
  transform: translate(-50%, -50%) perspective(500px) rotateX(12deg) rotateZ(-1deg);
  display: grid;
  place-items: center;
  border: 1px solid rgba(29, 205, 255, 0.8);
  border-radius: 10px;
  background:
    linear-gradient(145deg, rgba(15, 103, 169, 0.34), rgba(2, 17, 30, 0.8)),
    rgba(4, 18, 31, 0.8);
  box-shadow:
    0 0 28px rgba(12, 203, 255, 0.24),
    inset 0 0 35px rgba(9, 137, 255, 0.12);
}

.auth-network-core::before {
  content: "";
  position: absolute;
  inset: -18px;
  border-radius: 16px;
  border: 1px solid rgba(31, 191, 255, 0.18);
  box-shadow: 0 0 40px rgba(0, 174, 255, 0.12);
}

.auth-chain-symbol {
  position: relative;
  width: 62px;
  height: 46px;
  filter: drop-shadow(0 0 12px rgba(23, 207, 255, 0.65));
}

.auth-chain-symbol span {
  position: absolute;
  width: 38px;
  height: 22px;
  border: 6px solid #16c9ff;
  border-radius: 20px;
  transform: rotate(-37deg);
}

.auth-chain-symbol span:first-child {
  left: 0;
  top: 17px;
}

.auth-chain-symbol span:last-child {
  right: 0;
  top: 4px;
}

.auth-network-node {
  position: absolute;
  width: 48px;
  height: 48px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(26, 203, 255, 0.65);
  border-radius: 7px;
  background: rgba(4, 28, 48, 0.88);
  box-shadow: 0 0 22px rgba(0, 185, 255, 0.18);
}

.auth-network-node span {
  width: 12px;
  height: 12px;
  border-radius: 3px;
  background: #0bd7ff;
  box-shadow: 0 0 17px rgba(11, 215, 255, 0.8);
}

.node-one {
  left: 17%;
  top: 48%;
}

.node-two {
  left: 37%;
  top: 14%;
}

.node-three {
  right: 11%;
  top: 42%;
}

.node-four {
