  width: 100%;
  height: 100%;
  overflow: hidden;
  background: #05070b;
  border: 0;
}

.featured-card .featured-photo {
  position: absolute;
  inset: 0;

  width: 100%;
  height: 100%;

  display: block;

  object-fit: cover;
  object-position: center center;

  image-rendering: auto;

  transform: translateZ(0);
  backface-visibility: hidden;

  filter:
    contrast(1.05)
    saturate(1.04)
    brightness(1.02);

  transition:
    transform 1s cubic-bezier(0.2, 0.7, 0.2, 1);
}

