/* =========================================================
   CHAINLAB — PREMIUM HERO CARD
   ========================================================= */

.hero-section {
  position: relative;
  width: calc(100% - 80px);
  max-width: 1600px;
  margin: 70px auto 100px;
  padding: 0;
  overflow: hidden;

  border: 1px solid rgba(255, 255, 255, 0.10);
  border-radius: 32px;

  background:
    radial-gradient(
      circle at 78% 35%,
      rgba(0, 126, 255, 0.12),
      transparent 32%
    ),
    radial-gradient(
      circle at 20% 70%,
      rgba(0, 80, 160, 0.08),
      transparent 35%
    ),
    #03070d;

  box-shadow:
    0 30px 100px rgba(0, 0, 0, 0.45),
    inset 0 1px 0 rgba(255, 255, 255, 0.025);
}

/* Subtle technical grid inside the card */

.hero-section::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 0.45;

  background-image:
    linear-gradient(
      rgba(0, 174, 255, 0.035) 1px,
      transparent 1px
    ),
    linear-gradient(
      90deg,
      rgba(0, 174, 255, 0.035) 1px,
      transparent 1px
    );

  background-size: 44px 44px;
}

/* Keep all hero content above the grid */

.hero-section > * {
  position: relative;
  z-index: 1;
}


/* =========================================================
   MAIN HERO
   ========================================================= */

.hero-grid {
  min-height: 720px;
  padding: 70px 70px 40px;

  display: grid;
  grid-template-columns: minmax(0, 0.95fr) minmax(0, 1.25fr);
  gap: 45px;
  align-items: center;
}


/* =========================================================
   LEFT CONTENT
   ========================================================= */

.hero-content {
  position: relative;
  z-index: 3;
}

.hero-content .eyebrow {
  display: inline-flex;
  align-items: center;

  min-height: 58px;
  padding: 0 24px;

  margin-bottom: 42px;

  border: 1px solid rgba(0, 204, 255, 0.65);

  color: #00cfff;

  font-size: calc((13px) * var(--cl-font-scale, 1));
  font-weight: 800;
  letter-spacing: 0.10em;
  text-transform: uppercase;

  background: rgba(0, 12, 24, 0.45);
}

.hero-content h1 {
  margin: 0;

  font-size: calc((clamp(64px, 6.2vw, 105px)) * var(--cl-font-scale, 1));
  line-height: 0.91;
  letter-spacing: -0.065em;
  font-weight: 900;

  color: #f7f8fb;
}

.hero-content h1 span {
  color: #ffad00;
}

.hero-description {
  max-width: 700px;

  margin-top: 46px;

  color: #aab8ca;

  font-size: calc((18px) * var(--cl-font-scale, 1));
  line-height: 1.7;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;

  margin-top: 34px;
}

.hero-note {
  max-width: 650px;

  margin-top: 32px;

  color: #71839a;

  font-size: calc((14px) * var(--cl-font-scale, 1));
  line-height: 1.7;
}


/* =========================================================
   BLOCKCHAIN VISUAL
   ========================================================= */

.hero-visual {
  position: relative;

  min-height: 620px;

  display: flex;
  align-items: center;
  justify-content: center;

  overflow: hidden;

  border-radius: 22px;

  background:
    radial-gradient(
      circle at center,
      rgba(0, 100, 190, 0.10),
      transparent 65%
    );
}

.hero-visual::after {
  content: "";

  position: absolute;
  inset: 0;

  pointer-events: none;

  background:
    linear-gradient(
      90deg,
      rgba(3, 7, 13, 0.15),
      transparent 30%,
      transparent 70%,
      rgba(3, 7, 13, 0.08)
    );
}


/* =========================================================
   FEATURE STRIP
   ========================================================= */

.hero-features {
  margin: 0 70px;

  display: grid;
  grid-template-columns: repeat(4, 1fr);

  border-top: 1px solid rgba(255, 255, 255, 0.09);
  border-left: 1px solid rgba(255, 255, 255, 0.07);
}

.feature-item {
  min-height: 165px;

  padding: 30px 28px;

  display: flex;
  gap: 20px;
  align-items: flex-start;

  border-right: 1px solid rgba(255, 255, 255, 0.07);
  border-bottom: 1px solid rgba(255, 255, 255, 0.07);

  background: rgba(0, 8, 16, 0.28);
}

.feature-icon {
  flex: 0 0 auto;

  color: #00cfff;

  filter:
    drop-shadow(0 0 8px rgba(0, 200, 255, 0.35));
}

.feature-item h3 {
  margin: 0 0 10px;

  color: #f5f7fa;

  font-size: calc((14px) * var(--cl-font-scale, 1));
  font-weight: 800;
  letter-spacing: -0.01em;
}

.feature-item p {
  margin: 0;

  color: #71839a;

  font-size: calc((14px) * var(--cl-font-scale, 1));
  line-height: 1.65;
}


/* =========================================================
   STATISTICS
   ========================================================= */

.stats-grid {
  margin: 0 70px 70px;

  display: grid;
  grid-template-columns: repeat(5, 1fr);

  border-left: 1px solid rgba(255, 255, 255, 0.07);
  border-bottom: 1px solid rgba(255, 255, 255, 0.07);
}

.stat {
  min-height: 135px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;

  text-align: center;

  border-right: 1px solid rgba(255, 255, 255, 0.07);

  background: rgba(0, 8, 16, 0.20);
}

.stat strong {
  color: #ffad00;

  font-size: calc((clamp(30px, 3vw, 42px)) * var(--cl-font-scale, 1));
  line-height: 1;
  font-weight: 900;
  letter-spacing: -0.04em;
}

.stat span {
  margin-top: 12px;

  color: #71839a;

  font-size: calc((10px) * var(--cl-font-scale, 1));
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}


