/* =========================================================
   CHAINLAB — CHAT / FONT / THEME / MOBILE NAVIGATION
   ========================================================= */

/* =========================================================
   FONT SCALE
   ========================================================= */

html {
  --cl-font-scale: 1;
}

body {
  font-size: calc(16px * var(--cl-font-scale));
}


/* =========================================================
   FLOATING CHAINLAB TOOLS
   ========================================================= */

.chainlab-tools {
  position: fixed;
  right: 24px;
  bottom: 24px;
  z-index: 9998;

  display: flex;
  align-items: center;
  gap: 10px;
}

.chainlab-tool-button,
.chainlab-chat-button {
  height: 48px;
  min-width: 48px;
  padding: 0 14px;

  display: inline-flex;
  align-items: center;
  justify-content: center;

  border: 1px solid rgba(255, 255, 255, 0.18);
  border-radius: 12px;

  background: rgba(2, 5, 10, 0.94);
  color: #ffffff;

  font-family: inherit;
  font-size: calc((12px) * var(--cl-font-scale, 1));
  font-weight: 700;
  letter-spacing: 0.08em;

  cursor: pointer;

  backdrop-filter: blur(18px);

  transition:
    background 0.25s ease,
    color 0.25s ease,
    border-color 0.25s ease,
    transform 0.25s ease;
}

.chainlab-tool-button:hover,
.chainlab-chat-button:hover {
  background: #ffffff;
  color: #02050a;
  border-color: #ffffff;
  transform: translateY(-2px);
}

.chainlab-chat-button {
  min-width: 68px;
}


/* =========================================================
   FONT CONTROL
   ========================================================= */

.font-control-wrapper {
  position: relative;
}

.font-control-panel {
  position: absolute;
  right: 0;
  bottom: 58px;

  display: flex;
  gap: 6px;

  padding: 8px;

  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 12px;

  background: rgba(2, 5, 10, 0.96);

  backdrop-filter: blur(18px);

  box-shadow:
    0 20px 60px rgba(0, 0, 0, 0.35);
}

.font-control-panel button {
  width: 40px;
  height: 38px;

  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 8px;

  background: transparent;
  color: #ffffff;

  font-family: inherit;
  font-size: calc((13px) * var(--cl-font-scale, 1));
  font-weight: 700;

  cursor: pointer;
}

.font-control-panel button:hover,
.font-control-panel button.active {
  background: #00d9ff;
  border-color: #00d9ff;
  color: #02050a;
}


/* =========================================================
   CHAT OVERLAY
   ========================================================= */

.chainlab-chat-overlay {
  position: fixed;
  inset: 0;

  z-index: 9999;

  display: flex;
  align-items: flex-end;
  justify-content: flex-end;

  padding: 24px;

  background: rgba(0, 0, 0, 0.22);

  backdrop-filter: blur(3px);
}

.chainlab-chatbox {
  width: min(420px, calc(100vw - 32px));
  height: min(680px, calc(100vh - 48px));

  display: flex;
  flex-direction: column;

  overflow: hidden;

  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 22px;

  background: #02050a;
  color: #ffffff;

  box-shadow:
    0 30px 100px rgba(0, 0, 0, 0.55);
}


/* =========================================================
   CHAT HEADER
   ========================================================= */

.chainlab-chat-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;

  padding: 24px;

  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
}

.chainlab-chat-label {
  display: block;

  margin-bottom: 8px;

  color: #00d9ff;

  font-size: calc((10px) * var(--cl-font-scale, 1));
  font-weight: 700;
  letter-spacing: 0.14em;
}

.chainlab-chat-header h2 {
  margin: 0;

  color: #ffffff;

  font-size: calc((28px) * var(--cl-font-scale, 1));
  line-height: 1;
  letter-spacing: -0.04em;
}

.chainlab-chat-close {
  width: 36px;
  height: 36px;

  display: flex;
  align-items: center;
  justify-content: center;

  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 50%;

  background: transparent;
  color: #ffffff;

  font-size: calc((24px) * var(--cl-font-scale, 1));
  line-height: 1;

  cursor: pointer;
}

.chainlab-chat-close:hover {
  background: #ffffff;
  color: #02050a;
}


/* =========================================================
   CHAT MESSAGES
   ========================================================= */

.chainlab-chat-messages {
  flex: 1;

  overflow-y: auto;

  display: flex;
  flex-direction: column;
  gap: 14px;

  padding: 24px;
}

.chainlab-message {
  max-width: 88%;

  padding: 14px 16px;

  border-radius: 14px;

  font-size: calc((14px) * var(--cl-font-scale, 1));
  line-height: 1.6;
}

.chainlab-message.chainlab-message {
  align-self: flex-start;

  background: rgba(255, 255, 255, 0.06);
  color: rgba(255, 255, 255, 0.78);
}

.chainlab-message.user-message {
  align-self: flex-end;

  background: #00d9ff;
  color: #02050a;
}


/* =========================================================
   QUICK CHAT QUESTIONS
   ========================================================= */

.chainlab-chat-quick {
  display: flex;
  gap: 8px;

  padding: 0 20px 16px;

  overflow-x: auto;
}

.chainlab-chat-quick button {
  flex: 0 0 auto;

  padding: 9px 12px;

  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 20px;

  background: transparent;
  color: rgba(255, 255, 255, 0.7);

  font-family: inherit;
  font-size: calc((11px) * var(--cl-font-scale, 1));

  cursor: pointer;
}

.chainlab-chat-quick button:hover {
  border-color: #00d9ff;
  color: #00d9ff;
}


/* =========================================================
   CHAT INPUT
   ========================================================= */

.chainlab-chat-input {
  display: flex;
  gap: 8px;

  padding: 16px;

  border-top: 1px solid rgba(255, 255, 255, 0.1);
}

.chainlab-chat-input input {
  min-width: 0;
  flex: 1;

  height: 48px;

  padding: 0 15px;

  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 10px;

  outline: none;

  background: rgba(255, 255, 255, 0.05);
  color: #ffffff;

  font-family: inherit;
  font-size: calc((14px) * var(--cl-font-scale, 1));
}

.chainlab-chat-input input::placeholder {
  color: rgba(255, 255, 255, 0.35);
}

.chainlab-chat-input input:focus {
  border-color: #00d9ff;
}

.chainlab-chat-input button {
  width: 48px;
  height: 48px;

  border: 0;
  border-radius: 10px;

  background: #00d9ff;
  color: #02050a;

  font-size: calc((20px) * var(--cl-font-scale, 1));
  font-weight: 700;

  cursor: pointer;
}

.chainlab-chat-input button:hover {
  transform: translateX(2px);
}


/* =========================================================
   MOBILE NAVIGATION BUTTON
   ========================================================= */

.mobile-menu-button {
  display: none;

  width: 44px;
  height: 44px;

  padding: 0;

  border: 1px solid rgba(255, 255, 255, 0.16);
  border-radius: 10px;

  background: transparent;

  cursor: pointer;
}

.mobile-menu-button span {
  display: block;

  width: 19px;
  height: 1px;

  margin: 4px auto;

  background: #ffffff;

  transition:
    transform 0.25s ease,
    opacity 0.25s ease;
}

.mobile-menu-button.open span:nth-child(1) {
  transform: translateY(5px) rotate(45deg);
}

.mobile-menu-button.open span:nth-child(2) {
  opacity: 0;
}

.mobile-menu-button.open span:nth-child(3) {
  transform: translateY(-5px) rotate(-45deg);
}


/* =========================================================
   MOBILE NAVIGATION PANEL
   ========================================================= */

.mobile-navigation {
  position: fixed;
  inset: 0;

  z-index: 9997;

  display: flex;
  flex-direction: column;

  padding: 24px;

  background: #02050a;
  color: #ffffff;

  opacity: 0;
  visibility: hidden;

  transform: translateY(-20px);

  transition:
    opacity 0.25s ease,
    visibility 0.25s ease,
    transform 0.25s ease;
}

.mobile-navigation-open {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}

.mobile-navigation-header {
  display: flex;
  align-items: center;
  justify-content: space-between;

  padding-bottom: 30px;

  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
}

.mobile-navigation-brand {
  color: #ffffff;

  font-size: calc((15px) * var(--cl-font-scale, 1));
  font-weight: 800;
  letter-spacing: 0.08em;
  text-decoration: none;
}

.mobile-navigation-close {
  width: 42px;
  height: 42px;

  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: 10px;

  background: transparent;
  color: #ffffff;

  font-size: calc((25px) * var(--cl-font-scale, 1));

  cursor: pointer;
}

.mobile-navigation-links {
  display: flex;
  flex-direction: column;

  margin-top: 35px;
}

.mobile-navigation-links a {
  display: flex;
  align-items: center;
  gap: 20px;

  padding: 22px 0;

  border-bottom: 1px solid rgba(255, 255, 255, 0.1);

  color: #ffffff;

  font-size: calc((clamp(28px, 8vw, 52px)) * var(--cl-font-scale, 1));
  font-weight: 800;
  letter-spacing: -0.04em;

