/* =========================================
   CHAINLAB CHAT BUTTON
   Glossy pill design inspired by START LEARNING
   ========================================= */

.chainlab-chat-launcher {
  position: fixed !important;
  right: 26px !important;
  bottom: 26px !important;
  top: auto !important;
  left: auto !important;

  z-index: 10010 !important;

  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  gap: 12px !important;

  min-width: 230px;
  min-height: 62px;

  padding: 16px 28px !important;

  border: 1px solid rgba(255, 255, 255, 0.75) !important;
  border-radius: 999px !important;

  background: linear-gradient(
    180deg,
    #222328 0%,
    #101115 48%,
    #08090c 100%
  ) !important;

  color: #f5f6f8 !important;

  font-family: inherit !important;
  font-size: 16px !important;
  font-weight: 700 !important;
  letter-spacing: 0.04em !important;

  cursor: pointer !important;

  box-shadow:
    0 0 0 4px rgba(255, 255, 255, 0.08),
    0 0 0 7px rgba(0, 0, 0, 0.55),
    inset 0 1px 2px rgba(255, 255, 255, 0.3),
    inset 0 -5px 10px rgba(0, 0, 0, 0.7),
    0 8px 20px rgba(0, 0, 0, 0.45);

  transition:
    transform 0.25s ease,
    box-shadow 0.25s ease,
    border-color 0.25s ease;
}

/* Hide the old square icon */
.chainlab-chat-launcher-icon {
  display: none !important;
}

/* Add the arrow */
.chainlab-chat-launcher::after {
  content: "→";
  display: inline-block;

  font-size: 22px;
  font-weight: 400;
  line-height: 1;

  transition: transform 0.25s ease;
}

/* Hover effect */
.chainlab-chat-launcher:hover {
  transform: translateY(-2px);

  border-color: rgba(255, 255, 255, 0.95) !important;

  box-shadow:
    0 0 0 4px rgba(255, 255, 255, 0.12),
    0 0 0 7px rgba(0, 0, 0, 0.6),
    inset 0 1px 3px rgba(255, 255, 255, 0.4),
    inset 0 -5px 10px rgba(0, 0, 0, 0.7),
    0 10px 25px rgba(0, 0, 0, 0.5);
}

.chainlab-chat-launcher:hover::after {
  transform: translateX(4px);
}

/* Pressed effect */
