/* =========================================
   CHAINLAB STUDY NOTES
========================================= */

.study-notes-page {
  width: 100%;
  min-height: 100vh;
  padding-bottom: 80px;
  color: var(--foreground, #f5f5f5);
}

.study-notes-hero {
  position: relative;
  overflow: hidden;
  padding: 100px 24px 75px;
  background:
    radial-gradient(
      circle at 85% 15%,
      rgba(91, 91, 255, 0.16),
      transparent 35%
    ),
    radial-gradient(
      circle at 10% 80%,
      rgba(0, 210, 180, 0.1),
      transparent 35%
    );
}

.study-notes-hero-content {
  width: 100%;
  max-width: 1100px;
  margin: 0 auto;
}

.study-notes-eyebrow {
  display: inline-block;
  margin-bottom: 18px;
  font-size: 0.75rem;
  font-weight: 800;
  letter-spacing: 0.16em;
  color: #55d6c2;
}

.study-notes-hero h1 {
  max-width: 850px;
  margin: 0 0 24px;
  font-size: clamp(2.5rem, 6vw, 5rem);
  line-height: 1.05;
  font-weight: 850;
  letter-spacing: -0.055em;
}

.study-notes-hero h1 span {
  display: block;
  color: #55d6c2;
}

.study-notes-hero-content > p {
  max-width: 720px;
  margin: 0;
  font-size: 1.1rem;
  line-height: 1.8;
  opacity: 0.78;
}

.study-notes-hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 14px;
  margin-top: 32px;
}

.study-notes-primary-button,
.study-notes-secondary-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  min-height: 48px;
  padding: 13px 22px;
  border-radius: 10px;
  font-size: 0.9rem;
  font-weight: 750;
  text-decoration: none;
  transition:
    transform 180ms ease,
    opacity 180ms ease,
    background 180ms ease;
}

.study-notes-primary-button {
  color: #061311;
  background: #55d6c2;
}

.study-notes-secondary-button {
  color: inherit;
  border: 1px solid currentColor;
  background: transparent;
}

.study-notes-primary-button:hover,
.study-notes-secondary-button:hover {
  transform: translateY(-2px);
  opacity: 0.88;
}

.study-notes-stats {
  display: flex;
  flex-wrap: wrap;
  gap: 50px;
  margin-top: 55px;
}

.study-notes-stat {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.study-notes-stat strong {
  font-size: 1.8rem;
  font-weight: 850;
}

.study-notes-stat span {
  font-size: 0.85rem;
  opacity: 0.65;
}

.study-notes-library {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  padding: 70px 24px 30px;
  scroll-margin-top: 100px;
}

.study-notes-section-heading {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 25px;
  margin-bottom: 35px;
}

.study-notes-section-heading h2 {
  margin: 0 0 12px;
  font-size: clamp(1.8rem, 4vw, 2.8rem);
  font-weight: 850;
  letter-spacing: -0.04em;
}

.study-notes-section-heading p {
  margin: 0;
  line-height: 1.7;
  opacity: 0.7;
}

.study-notes-count {
  flex-shrink: 0;
  padding: 9px 13px;
  border: 1px solid rgba(128, 128, 128, 0.3);
  border-radius: 100px;
  font-size: 0.72rem;
  font-weight: 800;
  letter-spacing: 0.08em;
}

.study-notes-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 22px;
}

.study-notes-card {
  display: flex;
  flex-direction: column;
  min-width: 0;
  padding: 27px;
  border: 1px solid rgba(128, 128, 128, 0.24);
  border-radius: 16px;
  background: rgba(128, 128, 128, 0.045);
  transition:
    transform 180ms ease,
    border-color 180ms ease,
    background 180ms ease;
}

.study-notes-card:hover {
  transform: translateY(-4px);
  border-color: rgba(85, 214, 194, 0.65);
  background: rgba(85, 214, 194, 0.045);
}

.study-notes-card-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
  margin-bottom: 24px;
}

.study-notes-number {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 42px;
  height: 42px;
  border-radius: 11px;
  color: #061311;
  background: #55d6c2;
  font-size: 0.9rem;
  font-weight: 900;
}

.study-notes-category {
  padding: 7px 10px;
  border: 1px solid rgba(128, 128, 128, 0.3);
  border-radius: 100px;
  font-size: 0.67rem;
  font-weight: 800;
  letter-spacing: 0.08em;
  opacity: 0.8;
}

.study-notes-card h3 {
  margin: 0 0 13px;
  font-size: 1.35rem;
  line-height: 1.35;
  font-weight: 800;
  letter-spacing: -0.025em;
}

.study-notes-description {
  margin: 0 0 22px;
  font-size: 0.94rem;
  line-height: 1.75;
  opacity: 0.72;
}

.study-notes-topics {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: auto;
  margin-bottom: 25px;
}

.study-notes-topics span {
  padding: 7px 10px;
  border-radius: 7px;
  background: rgba(128, 128, 128, 0.12);
  font-size: 0.72rem;
  line-height: 1.4;
  opacity: 0.85;
}

.study-notes-card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 15px;
  padding-top: 20px;
  border-top: 1px solid rgba(128, 128, 128, 0.2);
}

.study-notes-file-type {
  font-size: 0.68rem;
  font-weight: 800;
  letter-spacing: 0.1em;
  opacity: 0.55;
}

.study-notes-download-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 11px 15px;
  border-radius: 9px;
  color: #061311;
  background: #55d6c2;
  font-size: 0.82rem;
  font-weight: 800;
  text-decoration: none;
  transition:
    transform 180ms ease,
    opacity 180ms ease;
}

.study-notes-download-button:hover {
  transform: translateY(-2px);
  opacity: 0.85;
}

.study-notes-bottom-cta {
  max-width: 1152px;
  margin: 60px auto 0;
  padding: 55px 30px;
  border: 1px solid rgba(128, 128, 128, 0.24);
  border-radius: 18px;
  text-align: center;
  background: rgba(128, 128, 128, 0.045);
}

.study-notes-bottom-cta h2 {
  margin: 0 auto 15px;
  font-size: clamp(1.8rem, 4vw, 2.8rem);
  font-weight: 850;
  letter-spacing: -0.04em;
}

.study-notes-bottom-cta p {
  max-width: 650px;
  margin: 0 auto 25px;
  font-size: 0.98rem;
  line-height: 1.8;
  opacity: 0.7;
}

.study-notes-bottom-cta .study-notes-primary-button {
  display: inline-flex;
}

/* Light theme support */
html[data-theme="light"] .study-notes-page {
  color: #171923;
}

html[data-theme="light"] .study-notes-card,
html[data-theme="light"] .study-notes-bottom-cta {
  border-color: rgba(20, 25, 35, 0.14);
  background: rgba(20, 25, 35, 0.025);
}

html[data-theme="light"] .study-notes-card:hover {
  border-color: rgba(0, 130, 115, 0.55);
  background: rgba(0, 130, 115, 0.045);
}

html[data-theme="light"] .study-notes-secondary-button {
  border-color: rgba(20, 25, 35, 0.35);
}

html[data-theme="light"] .study-notes-topics span {
  background: rgba(20, 25, 35, 0.06);
}

html[data-theme="light"] .study-notes-card-footer {
  border-top-color: rgba(20, 25, 35, 0.12);
}

/* Responsive layout */
@media (max-width: 800px) {
  .study-notes-hero {
    padding-top: 75px;
  }

  .study-notes-grid {
    grid-template-columns: 1fr;
  }

  .study-notes-section-heading {
    align-items: flex-start;
    flex-direction: column;
  }

  .study-notes-bottom-cta {
    margin-right: 20px;
    margin-left: 20px;
  }
}

@media (max-width: 500px) {
  .study-notes-hero {
    padding: 60px 18px 50px;
  }

  .study-notes-library {
    padding: 50px 18px 20px;
  }

  .study-notes-hero-actions {
    align-items: stretch;
    flex-direction: column;
  }

  .study-notes-primary-button,
  .study-notes-secondary-button {
    width: 100%;
  }

  .study-notes-stats {
    gap: 25px;
  }

  .study-notes-card {
    padding: 21px;
  }

  .study-notes-card-footer {
    align-items: flex-start;
    flex-direction: column;
  }

  .study-notes-download-button {
    width: 100%;
  }

  .study-notes-bottom-cta {
    padding: 40px 20px;
  }
}

/* =========================================
   CHAINLAB ACHIEVEMENTS
========================================= */

.achievements-page {
  --achievement-accent: #b7ff3c;
  --achievement-border: rgba(255, 255, 255, 0.12);

  width: 100%;
  min-height: 100vh;
  padding: 90px 6% 100px;
  color: var(--foreground, #f5f5f5);
  background: var(--background, #050505);
}

.achievements-hero {
  max-width: 1200px;
  margin: 0 auto;
  padding: 55px 0 75px;
}

.achievements-eyebrow {
  display: inline-block;
  margin-bottom: 24px;
  color: var(--achievement-accent, #b7ff3c);
  font-family: monospace;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 2px;
}

.achievements-hero h1,
.achievement-modules h2 {
  margin: 0;
  font-size: clamp(42px, 7vw, 92px);
  font-weight: 900;
  line-height: 0.98;
  letter-spacing: -4px;
}

.achievements-hero h1 span,
.achievement-modules h2 span {
  color: var(--achievement-accent, #b7ff3c);
}

.achievements-hero > p,
.achievement-modules > p {
  max-width: 650px;
  margin: 28px 0 40px;
  color: var(--muted-foreground, #a3a3a3);
  font-size: 16px;
  line-height: 1.8;
}

.achievement-summary {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 16px;
  margin-top: 45px;
}

.achievement-summary-card {
  padding: 26px;
  border: 1px solid var(--achievement-border);
  border-radius: 14px;
  background: var(--card, rgba(255, 255, 255, 0.035));
}

.summary-label {
  display: block;
  margin-bottom: 18px;
  color: var(--muted-foreground, #999);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 1.5px;
}

.achievement-summary-card strong {
  font-size: clamp(28px, 4vw, 44px);
  font-weight: 900;
}

.achievement-summary-card strong span {
  color: var(--muted-foreground, #888);
  font-size: 20px;
}

.achievement-progress-track {
  width: 100%;
  height: 9px;
  margin-top: 28px;
  overflow: hidden;
  border-radius: 20px;
  background: rgba(128, 128, 128, 0.2);
}

.achievement-progress-fill {
  height: 100%;
  border-radius: inherit;
  background: var(--achievement-accent, #b7ff3c);
  transition: width 400ms ease;
}

.achievement-section {
  max-width: 1200px;
  margin: 0 auto;
  padding: 45px 0 85px;
}

.achievement-section-heading {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 35px;
}

.achievement-section-heading h2 {
  margin: 0;
  font-size: clamp(28px, 4vw, 48px);
  font-weight: 900;
  letter-spacing: -1.5px;
}

.achievement-count {
  padding: 10px 15px;
  border: 1px solid var(--achievement-border);
  border-radius: 50px;
  color: var(--achievement-accent, #b7ff3c);
  font-family: monospace;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 1px;
  white-space: nowrap;
}

.achievement-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 20px;
}

.achievement-card {
  position: relative;
  display: flex;
  min-height: 300px;
  flex-direction: column;
  padding: 27px;
  overflow: hidden;
  border: 1px solid var(--achievement-border);
  border-radius: 16px;
  background: var(--card, rgba(255, 255, 255, 0.035));
  transition:
    transform 200ms ease,
    border-color 200ms ease,
    opacity 200ms ease;
}

.achievement-card.earned {
  border-color: rgba(183, 255, 60, 0.45);
}

.achievement-card.earned:hover {
  transform: translateY(-5px);
  border-color: var(--achievement-accent, #b7ff3c);
}

.achievement-card.locked {
  opacity: 0.62;
}

.achievement-card-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 25px;
}

.achievement-icon {
  display: grid;
  width: 65px;
  height: 65px;
  place-items: center;
  border: 1px solid var(--achievement-border);
  border-radius: 16px;
  background: rgba(128, 128, 128, 0.08);
  font-size: 32px;
}

.achievement-status {
  padding: 7px 10px;
  border-radius: 50px;
  font-family: monospace;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 1px;
}

.status-earned {
  color: #101500;
  background: var(--achievement-accent, #b7ff3c);
}

.status-locked {
  border: 1px solid var(--achievement-border);
  color: var(--muted-foreground, #999);
}

.achievement-card h3 {
  margin: 0 0 12px;
  font-size: 18px;
  font-weight: 900;
  letter-spacing: 0.5px;
}

.achievement-description {
  margin: 0 0 25px;
  color: var(--muted-foreground, #a3a3a3);
  font-size: 14px;
  line-height: 1.7;
}

.achievement-requirement {
  margin-top: auto;
  padding-top: 18px;
  border-top: 1px solid var(--achievement-border);
}

.achievement-requirement span {
  color: var(--muted-foreground, #999);
  font-family: monospace;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1.5px;
}

.achievement-requirement p {
  margin: 9px 0 0;
  font-size: 12px;
  line-height: 1.6;
}

.achievement-earned-label {
  margin-top: 18px;
  color: var(--achievement-accent, #b7ff3c);
  font-family: monospace;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 1px;
}

.achievement-modules {
  max-width: 1200px;
  margin: 0 auto;
  padding: 75px 0 30px;
  border-top: 1px solid var(--achievement-border);
}

.achievement-modules h2 {
  font-size: clamp(45px, 7vw, 80px);
}

.achievement-module-links {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
  margin: 35px 0;
}

.achievement-module-links a {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  padding: 20px 22px;
  border: 1px solid var(--achievement-border);
  border-radius: 10px;
  color: inherit;
  font-size: 13px;
  font-weight: 800;
  letter-spacing: 1px;
  text-decoration: none;
  transition:
    border-color 200ms ease,
    background 200ms ease;
}

.achievement-module-links a:hover {
  border-color: var(--achievement-accent, #b7ff3c);
  background: rgba(128, 128, 128, 0.06);
}

.achievement-module-links a span {
  color: var(--achievement-accent, #b7ff3c);
  font-size: 20px;
}

.achievement-main-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 20px;
  padding: 17px 24px;
  border: 1px solid var(--achievement-accent, #b7ff3c);
  border-radius: 8px;
  color: #101500;
  background: var(--achievement-accent, #b7ff3c);
  font-size: 12px;
  font-weight: 900;
  letter-spacing: 1px;
  text-decoration: none;
  transition:
    transform 200ms ease,
    opacity 200ms ease;
}

.achievement-main-button:hover {
  transform: translateY(-2px);
  opacity: 0.9;
}

/* Light theme support */

html[data-theme="light"] .achievements-page {
  --achievement-border: rgba(0, 0, 0, 0.13);
}

html[data-theme="light"] .achievement-card,
html[data-theme="light"] .achievement-summary-card {
  background: rgba(0, 0, 0, 0.025);
}

/* Responsive layout */

@media (max-width: 900px) {
  .achievement-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .achievement-summary {
    grid-template-columns: 1fr;
  }

  .achievement-summary-card {
    padding: 22px;
  }
}

@media (max-width: 600px) {
  .achievements-page {
    padding: 55px 5% 70px;
  }

  .achievements-hero {
    padding-top: 35px;
  }

  .achievements-hero h1,
  .achievement-modules h2 {
    letter-spacing: -2px;
  }

  .achievement-grid {
    grid-template-columns: 1fr;
  }

  .achievement-section-heading {
    align-items: flex-start;
    flex-direction: column;
  }

  .achievement-module-links {
    grid-template-columns: 1fr;
  }

  .achievement-card {
    min-height: 270px;
  }
}

/* =====================================================
   CHAINLAB LANGUAGE SELECTOR
===================================================== */

.language-selector {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 40px;
  padding: 6px 10px;
  border: 1px solid var(--border-color, rgba(128, 128, 128, 0.35));
  border-radius: 8px;
  background: var(--control-bg, transparent);
  color: var(--text-color, inherit);
  font-size: 13px;
  white-space: nowrap;
}

.language-selector-icon {
  font-size: 16px;
  line-height: 1;
}

.language-selector-label {
  font-weight: 600;
}

.language-selector select {
  max-width: 150px;
  border: none;
  outline: none;
  background: transparent;
  color: inherit;
  font: inherit;
  font-weight: 500;
  cursor: pointer;
}

.language-selector select option {
  background: var(--dropdown-bg, #ffffff);
  color: var(--dropdown-text, #111111);
}

.language-selector select:focus-visible {
  outline: 2px solid currentColor;
  outline-offset: 3px;
  border-radius: 3px;
}

@media (max-width: 768px) {
  .language-selector {
    gap: 5px;
    padding: 5px 7px;
    font-size: 12px;
  }

  .language-selector-label {
    display: none;
  }

  .language-selector select {
    max-width: 125px;
  }
}

