  align-items: center;
  justify-content: center;

  font-size: 16px;
  line-height: 1;

  pointer-events: none;
}

.language-selector-label {
  font-weight: 600;
  pointer-events: none;
}

.language-selector select {
  position: relative;
  z-index: 100000;

  display: inline-block;

  min-height: 30px;
  max-width: 160px;
  padding: 4px 8px;

  border: 1px solid transparent;
  border-radius: 5px;

  background: var(--control-bg, transparent);
  color: var(--text-color, inherit);

  font-family: inherit;
  font-size: inherit;
  font-weight: 500;

  cursor: pointer;
  pointer-events: auto;
}

.language-selector select:focus {
  outline: 2px solid currentColor;
  outline-offset: 2px;
}

.language-selector select option {
  background: var(--dropdown-bg, #ffffff);
  color: var(--dropdown-text, #111111);
}

/* Keep the selector above nearby toolbar elements. */
.chainlab-utility-bar,
.chainlab-utility-inner,
.chainlab-toolbar-center {
  overflow: visible;
}

.chainlab-toolbar-center {
  position: relative;
  z-index: 99998;
  pointer-events: auto;
}

