}

/* Glowing perspective floor under the network. */
.auth-network::after {
  content: "";
  position: absolute;
  left: 3%;
  right: 0;
  bottom: 14px;
  height: 135px;
  opacity: .42;
  transform: perspective(450px) rotateX(60deg);
  transform-origin: bottom center;
  background-image:
    linear-gradient(rgba(0, 181, 255, .15) 1px, transparent 1px),
    linear-gradient(90deg, rgba(0, 181, 255, .15) 1px, transparent 1px);
  background-size: 42px 42px;
  mask-image: radial-gradient(ellipse at center, black 0%, transparent 72%);
  -webkit-mask-image: radial-gradient(ellipse at center, black 0%, transparent 72%);
  pointer-events: none;
}

.auth-network-core {
  position: absolute;
  z-index: 5;
  left: 54%;
  top: 55%;
  width: 174px;
  height: 145px;
  transform: translate(-50%, -50%) perspective(650px) rotateX(10deg) rotateZ(-1deg);
  display: grid;
  place-items: center;
  border: 1px solid rgba(44, 211, 255, .88);
  border-radius: 9px;
  background:
    linear-gradient(145deg, rgba(20, 120, 192, .38), rgba(2, 16, 29, .91)),
    rgba(3, 20, 34, .9);
  box-shadow:
    0 0 12px rgba(19, 207, 255, .48),
    0 0 42px rgba(0, 183, 255, .24),
    inset 0 0 40px rgba(7, 148, 255, .16);
}

/* Cube side / depth. */
.auth-network-core::before {
  content: "";
  position: absolute;
  z-index: -1;
  left: 17px;
  right: -18px;
  bottom: -25px;
  height: 25px;
  transform: skewX(-38deg);
  transform-origin: top left;
  border: 1px solid rgba(17, 151, 215, .42);
  background: linear-gradient(90deg, rgba(3, 26, 43, .92), rgba(2, 12, 23, .92));
  box-shadow: 0 15px 28px rgba(0, 0, 0, .55);
}

/* Inner glow / top face. */
