}

.learnOrbit {
  position: absolute;
  border: 1px solid rgba(0, 200, 255, 0.35);
  border-radius: 50%;
  box-shadow: 0 0 30px rgba(0, 200, 255, 0.06);
}

.orbitLarge {
  width: 480px;
  height: 480px;
}

.orbitMedium {
  width: 340px;
  height: 340px;
}

.orbitSmall {
  width: 205px;
  height: 205px;
}

.learnCore {
  width: 155px;
  height: 155px;
  border: 1px solid #00c8ff;
  border-radius: 50%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  background: rgba(3, 12, 20, 0.95);
  box-shadow:
    0 0 30px rgba(0, 200, 255, 0.18),
    inset 0 0 30px rgba(0, 200, 255, 0.05);
  z-index: 3;
}

.learnCore span {
  color: #00c8ff;
  font-size: calc((9px) * var(--cl-font-scale, 1));
  font-weight: 900;
  letter-spacing: 2px;
}

.learnCore strong {
  margin-top: 8px;
  font-size: calc((32px) * var(--cl-font-scale, 1));
  font-weight: 900;
}

.learnCore small {
  color: #ffad00;
  font-size: calc((8px) * var(--cl-font-scale, 1));
  font-weight: 900;
  letter-spacing: 2px;
  margin-top: 4px;
}

.learnNode {
  position: absolute;
  min-width: 135px;
  padding: 15px;
  border: 1px solid rgba(0, 200, 255, 0.55);
  background: rgba(3, 12, 20, 0.92);
  color: #00c8ff;
  font-size: calc((9px) * var(--cl-font-scale, 1));
  font-weight: 900;
  letter-spacing: 0.8px;
  text-align: center;
  box-shadow: 0 0 25px rgba(0, 200, 255, 0.08);
  z-index: 5;
}

.learnNode span {
  display: block;
  color: #ffad00;
  font-size: calc((10px) * var(--cl-font-scale, 1));
  margin-bottom: 7px;
}

.nodeOne {
  top: 25px;
  left: 4%;
}

.nodeTwo {
  top: 115px;
