========================================================= */
.chainlab-chatbox.chainlab-chatbox-compose {
  width: min(390px, calc(100vw - 32px));
  height: auto;
  max-height: min(76vh, 650px);
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0;
  overflow: hidden;
  background: transparent;
  border: 0;
  box-shadow: none;
}

.chainlab-chat-compose-shell {
  padding: 1.5px;
  border-radius: 21px;
  background: linear-gradient(to bottom right, #777, #343434 28%, #343434);
  box-shadow: 0 0 0 1px rgba(255,255,255,.08);
  overflow: hidden;
  position: relative;
}

.chainlab-compose-form {
  min-height: 132px;
  background: #191919;
  border: 1px solid #2b2b2b;
  border-radius: 19px;
