  position: relative;
  padding: 12px 13px 0;
}

.chainlab-compose-field textarea {
  display: block;
  width: 100%;
  min-height: 49px;
  max-height: 120px;
  resize: vertical;
  border: 0;
  outline: none;
  background: transparent;
  color: #f3f3f3;
  font: 400 15px/1.45 Arial, sans-serif;
  padding: 0 24px 0 0;
}

.chainlab-compose-field textarea::placeholder {
  color: #eeeeee;
  opacity: 1;
}

.chainlab-compose-sparkle {
  position: absolute;
  top: 13px;
  right: 14px;
  color: #e6e6e6;
  font-size: 14px;
  pointer-events: none;
}

.chainlab-compose-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 9px 12px 12px;
}

.chainlab-compose-tools {
  display: flex;
  align-items: center;
  gap: 9px;
}

.chainlab-compose-tools button {
  display: inline-flex;
  width: 25px;
  height: 27px;
  align-items: center;
  justify-content: center;
  padding: 2px;
  color: #454545;
  background: transparent;
  border: 0;
  border-radius: 6px;
  cursor: pointer;
  transition: color .2s ease, transform .2s ease;
}

.chainlab-compose-tools button:hover {
  color: #d8d8d8;
  transform: translateY(-1px);
}

.chainlab-compose-tools svg {
  width: 22px;
  height: 22px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.8;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.chainlab-compose-send {
  width: 42px;
  height: 42px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 7px;
  border: 1px solid #484848;
  border-radius: 12px;
  color: #9a9a9a;
  background: linear-gradient(180deg, #5b5b5b, #282828);
  box-shadow: inset 0 2px 2px rgba(255,255,255,.28), 0 1px 2px rgba(0,0,0,.5);
  cursor: pointer;
  transition: color .2s ease, transform .2s ease, filter .2s ease;
}

.chainlab-compose-send svg {
  width: 24px;
  height: 24px;
  fill: currentColor;
  stroke: #8a8a8a;
  stroke-width: 1;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.chainlab-compose-send:hover {
  color: #f4f4f4;
  filter: brightness(1.12);
}
.chainlab-compose-send:active { transform: scale(.94); }

.chainlab-compose-suggestions {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
  padding-top: 16px;
}

.chainlab-compose-suggestions button {
  min-height: 31px;
