  padding: 100px 24px 75px;
  background:
    radial-gradient(
      circle at 85% 15%,
      rgba(91, 91, 255, 0.16),
      transparent 35%
    ),
    radial-gradient(
      circle at 10% 80%,
      rgba(0, 210, 180, 0.1),
      transparent 35%
    );
}

.study-notes-hero-content {
  width: 100%;
  max-width: 1100px;
  margin: 0 auto;
}

.study-notes-eyebrow {
  display: inline-block;
  margin-bottom: 18px;
  font-size: 0.75rem;
  font-weight: 800;
  letter-spacing: 0.16em;
  color: #55d6c2;
}

.study-notes-hero h1 {
  max-width: 850px;
  margin: 0 0 24px;
  font-size: clamp(2.5rem, 6vw, 5rem);
  line-height: 1.05;
  font-weight: 850;
  letter-spacing: -0.055em;
}

.study-notes-hero h1 span {
  display: block;
  color: #55d6c2;
}

.study-notes-hero-content > p {
  max-width: 720px;
  margin: 0;
  font-size: 1.1rem;
  line-height: 1.8;
  opacity: 0.78;
}

.study-notes-hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 14px;
  margin-top: 32px;
}

.study-notes-primary-button,
.study-notes-secondary-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  min-height: 48px;
  padding: 13px 22px;
  border-radius: 10px;
  font-size: 0.9rem;
  font-weight: 750;
  text-decoration: none;
  transition:
    transform 180ms ease,
    opacity 180ms ease,
    background 180ms ease;
}

.study-notes-primary-button {
  color: #061311;
  background: #55d6c2;
}

.study-notes-secondary-button {
  color: inherit;
  border: 1px solid currentColor;
  background: transparent;
}

.study-notes-primary-button:hover,
.study-notes-secondary-button:hover {
  transform: translateY(-2px);
  opacity: 0.88;
}

.study-notes-stats {
  display: flex;
  flex-wrap: wrap;
  gap: 50px;
  margin-top: 55px;
}

.study-notes-stat {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.study-notes-stat strong {
  font-size: 1.8rem;
  font-weight: 850;
}

.study-notes-stat span {
  font-size: 0.85rem;
  opacity: 0.65;
}

.study-notes-library {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  padding: 70px 24px 30px;
  scroll-margin-top: 100px;
}

.study-notes-section-heading {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 25px;
  margin-bottom: 35px;
}

.study-notes-section-heading h2 {
  margin: 0 0 12px;
  font-size: clamp(1.8rem, 4vw, 2.8rem);
  font-weight: 850;
  letter-spacing: -0.04em;
}

.study-notes-section-heading p {
  margin: 0;
  line-height: 1.7;
  opacity: 0.7;
}

.study-notes-count {
  flex-shrink: 0;
  padding: 9px 13px;
  border: 1px solid rgba(128, 128, 128, 0.3);
  border-radius: 100px;
  font-size: 0.72rem;
  font-weight: 800;
  letter-spacing: 0.08em;
}

.study-notes-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 22px;
}

.study-notes-card {
  display: flex;
  flex-direction: column;
  min-width: 0;
  padding: 27px;
  border: 1px solid rgba(128, 128, 128, 0.24);
  border-radius: 16px;
  background: rgba(128, 128, 128, 0.045);
  transition:
    transform 180ms ease,
    border-color 180ms ease,
    background 180ms ease;
}

.study-notes-card:hover {
  transform: translateY(-4px);
  border-color: rgba(85, 214, 194, 0.65);
  background: rgba(85, 214, 194, 0.045);
}

.study-notes-card-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
  margin-bottom: 24px;
}

.study-notes-number {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 42px;
  height: 42px;
  border-radius: 11px;
  color: #061311;
  background: #55d6c2;
  font-size: 0.9rem;
  font-weight: 900;
}

.study-notes-category {
  padding: 7px 10px;
  border: 1px solid rgba(128, 128, 128, 0.3);
  border-radius: 100px;
  font-size: 0.67rem;
  font-weight: 800;
  letter-spacing: 0.08em;
  opacity: 0.8;
}

.study-notes-card h3 {
  margin: 0 0 13px;
  font-size: 1.35rem;
  line-height: 1.35;
  font-weight: 800;
  letter-spacing: -0.025em;
}

.study-notes-description {
  margin: 0 0 22px;
  font-size: 0.94rem;
  line-height: 1.75;
  opacity: 0.72;
}

.study-notes-topics {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: auto;
  margin-bottom: 25px;
}

.study-notes-topics span {
  padding: 7px 10px;
  border-radius: 7px;
  background: rgba(128, 128, 128, 0.12);
  font-size: 0.72rem;
  line-height: 1.4;
  opacity: 0.85;
}

.study-notes-card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 15px;
  padding-top: 20px;
  border-top: 1px solid rgba(128, 128, 128, 0.2);
}

.study-notes-file-type {
  font-size: 0.68rem;
  font-weight: 800;
  letter-spacing: 0.1em;
  opacity: 0.55;
}

.study-notes-download-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 11px 15px;
  border-radius: 9px;
  color: #061311;
  background: #55d6c2;
  font-size: 0.82rem;
  font-weight: 800;
  text-decoration: none;
  transition:
    transform 180ms ease,
    opacity 180ms ease;
}

.study-notes-download-button:hover {
  transform: translateY(-2px);
  opacity: 0.85;
}

.study-notes-bottom-cta {
  max-width: 1152px;
  margin: 60px auto 0;
  padding: 55px 30px;
  border: 1px solid rgba(128, 128, 128, 0.24);
  border-radius: 18px;
  text-align: center;
  background: rgba(128, 128, 128, 0.045);
}

.study-notes-bottom-cta h2 {
  margin: 0 auto 15px;
  font-size: clamp(1.8rem, 4vw, 2.8rem);
  font-weight: 850;
  letter-spacing: -0.04em;
}

.study-notes-bottom-cta p {
  max-width: 650px;
  margin: 0 auto 25px;
  font-size: 0.98rem;
  line-height: 1.8;
  opacity: 0.7;
}

.study-notes-bottom-cta .study-notes-primary-button {
  display: inline-flex;
}

