  }

  .study-notes-library {
    padding: 50px 18px 20px;
  }

  .study-notes-hero-actions {
    align-items: stretch;
    flex-direction: column;
  }

  .study-notes-primary-button,
  .study-notes-secondary-button {
    width: 100%;
  }

  .study-notes-stats {
    gap: 25px;
  }

  .study-notes-card {
    padding: 21px;
  }

  .study-notes-card-footer {
    align-items: flex-start;
    flex-direction: column;
  }

