.auth-password-toggle {
  position: absolute;
  right: 14px;
  top: 50%;
  width: 30px;
  height: 30px;
  display: grid;
  place-items: center;
  transform: translateY(-50%);
  border: 0;
  background: transparent;
  color: #8ea2b5;
