}

.forgot-password:hover {
  color: #7beaff;
}

.auth-primary-button {
  width: 100%;
  height: 55px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  border: 0;
  border-radius: 10px;
  color: #02131c;
  background: linear-gradient(90deg, #13d9f6, #17baf0);
  font: inherit;
  font-size: 16px;
  font-weight: 800;
  cursor: pointer;
  box-shadow: 0 10px 25px rgba(7, 195, 239, 0.13);
