  opacity: 0.7;
}

.auth-message {
  position: relative;
  z-index: 1;
  margin: 14px 0 0;
  padding: 10px 12px;
  border: 1px solid rgba(19, 216, 255, 0.2);
  border-radius: 8px;
  color: #9defff;
  background: rgba(10, 168, 211, 0.06);
  font-size: 13px;
  line-height: 1.45;
}

.auth-divider {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
  gap: 16px;
  margin: 29px 0 23px;
  color: #91a3b5;
  font-size: 13px;
}

.auth-divider::before,
.auth-divider::after {
  content: "";
  flex: 1;
  height: 1px;
  background: rgba(129, 151, 170, 0.32);
}

.auth-divider span {
  flex: 0 0 auto;
}

.auth-social-buttons {
  position: relative;
  z-index: 1;
  display: grid;
  gap: 11px;
}

.auth-social-button {
  width: 100%;
  min-height: 51px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  border: 1px solid rgba(87, 119, 145, 0.48);
  border-radius: 9px;
  color: #edf5fb;
  background: rgba(10, 24, 38, 0.62);
