  font-size: 15px;
  font-weight: 500;
  cursor: pointer;
  transition: all 160ms ease;
}

.auth-social-button:hover {
  border-color: rgba(19, 211, 255, 0.52);
  background: rgba(13, 37, 54, 0.82);
  transform: translateY(-1px);
}

.google-icon,
.apple-icon,
.phantom-icon {
  display: grid;
  place-items: center;
  width: 23px;
  height: 23px;
}

.google-icon svg,
.apple-icon svg,
.phantom-icon svg {
  width: 22px;
  height: 22px;
}

.apple-icon {
  color: #fff;
}

.apple-icon svg {
  fill: currentColor;
}

.phantom-icon {
  color: #a477ff;
}

.phantom-icon svg {
  fill: currentColor;
  filter: drop-shadow(0 0 5px rgba(164, 119, 255, 0.35));
}

.auth-switch {
  position: relative;
  z-index: 1;
  margin: 34px 0 0;
  text-align: center;
  color: #aabaca;
  font-size: 15px;
}

.auth-switch a {
  color: #13d8ff;
  font-weight: 600;
  text-decoration: none;
}

.auth-switch a:hover {
  text-decoration: underline;
}

.auth-back {
  position: relative;
  z-index: 1;
  display: block;
  margin-top: 25px;
  color: #7f93a6;
  font-size: 13px;
  text-align: center;
  text-decoration: none;
}

.auth-back:hover {
  color: #13d8ff;
}

