}

.orbitLarge {
  width: 480px;
  height: 480px;
}

.orbitMedium {
  width: 340px;
  height: 340px;
}

.orbitSmall {
  width: 205px;
  height: 205px;
}

.learnCore {
  width: 155px;
  height: 155px;
  border: 1px solid #00c8ff;
  border-radius: 50%;
