}

.learnCore strong {
  margin-top: 8px;
  font-size: calc((32px) * var(--cl-font-scale, 1));
  font-weight: 900;
}

.learnCore small {
  color: #ffad00;
  font-size: calc((8px) * var(--cl-font-scale, 1));
  font-weight: 900;
  letter-spacing: 2px;
