}

.learningModule:hover {
  border-color: rgba(0, 200, 255, 0.6);
  transform: translateX(8px);
  background: rgba(0, 200, 255, 0.035);
}

.featuredModule {
  border-color: rgba(255, 173, 0, 0.4);
}

.featuredModule:hover {
  border-color: #ffad00;
}

.moduleNumber {
  color: #00c8ff;
  font-size: calc((40px) * var(--cl-font-scale, 1));
  font-weight: 900;
  letter-spacing: -2px;
}

.moduleLabel {
  color: #00c8ff;
  font-size: calc((9px) * var(--cl-font-scale, 1));
  font-weight: 900;
  letter-spacing: 2px;
  margin-bottom: 10px;
}

.moduleMain h3 {
  margin: 0;
  font-size: calc((34px) * var(--cl-font-scale, 1));
  font-weight: 900;
  letter-spacing: -1px;
}

.moduleMain p {
  max-width: 720px;
  color: #8497aa;
  line-height: 1.7;
  font-size: calc((14px) * var(--cl-font-scale, 1));
  margin: 14px 0 20px;
}

.moduleTopics {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.moduleTopics span {
  padding: 7px 10px;
  border: 1px solid rgba(0, 200, 255, 0.15);
  color: #718599;
  font-size: calc((8px) * var(--cl-font-scale, 1));
  font-weight: 900;
  letter-spacing: 0.7px;
}

.moduleAction {
  display: flex;
  justify-content: flex-end;
  align-items: center;
  gap: 18px;
  color: #00c8ff;
  font-size: calc((9px) * var(--cl-font-scale, 1));
  font-weight: 900;
  letter-spacing: 1px;
}

.moduleAction strong {
  font-size: calc((22px) * var(--cl-font-scale, 1));
}

.securityModule {
  border-color: rgba(0, 200, 255, 0.3);
}

.comingModule {
  opacity: 0.65;
