.hero-section {
  position: relative;
  width: calc(100% - 80px);
  max-width: 1600px;
  margin: 70px auto 100px;
  padding: 0;
  overflow: hidden;

  border: 1px solid rgba(255, 255, 255, 0.10);
  border-radius: 32px;

  background:
    radial-gradient(
      circle at 78% 35%,
      rgba(0, 126, 255, 0.12),
      transparent 32%
    ),
    radial-gradient(
      circle at 20% 70%,
      rgba(0, 80, 160, 0.08),
