    0 30px 100px rgba(0, 0, 0, 0.45),
    inset 0 1px 0 rgba(255, 255, 255, 0.025);
}

/* Subtle technical grid inside the card */

.hero-section::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 0.45;

  background-image:
    linear-gradient(
      rgba(0, 174, 255, 0.035) 1px,
      transparent 1px
    ),
    linear-gradient(
      90deg,
      rgba(0, 174, 255, 0.035) 1px,
      transparent 1px
    );

  background-size: 44px 44px;
}

/* Keep all hero content above the grid */

.hero-section > * {
  position: relative;
  z-index: 1;
}


/* =========================================================
   MAIN HERO
   ========================================================= */

.hero-grid {
  min-height: 720px;
  padding: 70px 70px 40px;

  display: grid;
  grid-template-columns: minmax(0, 0.95fr) minmax(0, 1.25fr);
  gap: 45px;
  align-items: center;
