  position: relative !important;
  z-index: 2147483601 !important;
}

/* Appearance + language controls must sit above the header. */
.chainlab-toolbar-center {
  position: relative !important;
  z-index: 2147483640 !important;
  pointer-events: auto !important;
}

/* Language selector gets the highest interaction layer. */
.language-selector {
  position: relative !important;
  z-index: 2147483645 !important;
  pointer-events: auto !important;
}

/* Native select must receive the mouse click. */
.language-selector select {
  position: relative !important;
  z-index: 2147483646 !important;
  pointer-events: auto !important;
  cursor: pointer !important;
}

/* The header must remain below the toolbar controls. */
.chainlab-utility-inner > .site-header,
header.site-header {
  z-index: 2147483000 !important;
}

/* Keep navigation links clickable. */
header.site-header a {
  pointer-events: auto !important;
}

/* Language selector's decorative elements must not block clicks. */
.language-selector-icon,
.language-selector-label {
  pointer-events: none !important;
}

/* Prevent clipping. */
.chainlab-utility-bar,
.chainlab-utility-inner,
.chainlab-toolbar-center,
.language-selector {
  overflow: visible !important;
}

