.nodeOne {
  top: 25px;
  left: 4%;
}

.nodeTwo {
  top: 115px;
  right: 0;
}

.nodeThree {
  bottom: 80px;
  left: 0;
}

.nodeFour {
  bottom: 20px;
  right: 8%;
}

.learningPath {
