}

.moduleMain h3 {
  margin: 0;
  font-size: calc((34px) * var(--cl-font-scale, 1));
  font-weight: 900;
  letter-spacing: -1px;
}

.moduleMain p {
  max-width: 720px;
  color: #8497aa;
