  align-items: center;
  justify-content: center;
  color: #00c8ff;
  font-size: calc((13px) * var(--cl-font-scale, 1));
  font-weight: 900;
  margin-bottom: 60px;
}

.processCard h3 {
  font-size: calc((15px) * var(--cl-font-scale, 1));
  margin: 0 0 12px;
}

.processCard p {
  color: #778a9e;
  line-height: 1.7;
  font-size: calc((13px) * var(--cl-font-scale, 1));
}

.principlesSection {
