}

.principlesList {
  border-top: 1px solid rgba(0, 200, 255, 0.18);
}

.principle {
  display: grid;
  grid-template-columns: 65px 1fr;
  gap: 20px;
  padding: 30px 0;
  border-bottom: 1px solid rgba(0, 200, 255, 0.15);
}

.principle > span {
  color: #00c8ff;
  font-size: calc((11px) * var(--cl-font-scale, 1));
  font-weight: 900;
}

.principle h3 {
  margin: 0 0 10px;
  font-size: calc((14px) * var(--cl-font-scale, 1));
}

.principle p {
  margin: 0;
  color: #778a9e;
  line-height: 1.7;
  font-size: calc((13px) * var(--cl-font-scale, 1));
}

.learnFinal {
  position: relative;
  min-height: 520px;
  padding: 100px 6%;
  overflow: hidden;
  border-top: 1px solid rgba(0, 200, 255, 0.15);
  background:
    radial-gradient(
      circle at 70% 50%,
      rgba(0, 145, 255, 0.13),
      transparent 35%
    ),
    #02060b;
}

.learnFinalInner {
  position: relative;
  z-index: 3;
  max-width: 720px;
}

.learnFinal h2 {
  margin: 0;
  font-size: calc((clamp(60px, 8vw, 120px)) * var(--cl-font-scale, 1));
  line-height: 0.85;
  letter-spacing: -6px;
}

.learnFinal h2 span {
  color: #ffad00;
}

.learnFinal p {
  max-width: 600px;
  margin: 35px 0;
  color: #8497aa;
  line-height: 1.8;
  font-size: calc((15px) * var(--cl-font-scale, 1));
}

.learnStartButton {
  display: inline-flex;
  gap: 25px;
  align-items: center;
  padding: 18px 25px;
  background: #ffad00;
  color: #050505;
  font-size: calc((11px) * var(--cl-font-scale, 1));
  font-weight: 900;
  transition: 0.25s ease;
}

.learnStartButton:hover {
  transform: translateY(-3px);
  box-shadow: 0 15px 35px rgba(255, 173, 0, 0.2);
}

.learnStartButton span {
  font-size: calc((20px) * var(--cl-font-scale, 1));
}

.finalGrid {
  position: absolute;
  right: 5%;
  top: 50%;
  width: 500px;
  height: 500px;
  transform: translateY(-50%);
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
  opacity: 0.5;
}

.finalGrid span {
  border: 1px solid rgba(0, 200, 255, 0.2);
  background: rgba(0, 200, 255, 0.015);
}

.learnFooter {
  padding: 75px 6% 30px;
  background: #010409;
  border-top: 1px solid rgba(0, 200, 255, 0.15);
}

.learnFooterTop {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 60px;
  padding-bottom: 60px;
}

.learnFooterBrand strong {
  font-size: calc((20px) * var(--cl-font-scale, 1));
  font-weight: 900;
}

.learnFooterBrand p,
.learnFooterColumn p {
  color: #687c91;
  font-size: calc((12px) * var(--cl-font-scale, 1));
  line-height: 1.8;
}

.learnFooterColumn {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.learnFooterColumn h4 {
  color: #00c8ff;
  font-size: calc((9px) * var(--cl-font-scale, 1));
  letter-spacing: 1.5px;
  margin: 0 0 8px;
}

.learnFooterColumn a {
  color: #8799ab;
  font-size: calc((11px) * var(--cl-font-scale, 1));
}

.learnFooterColumn a:hover {
  color: white;
}

.learnFooterBottom {
  display: flex;
  justify-content: space-between;
  gap: 30px;
  padding-top: 25px;
  border-top: 1px solid rgba(0, 200, 255, 0.1);
  color: #506276;
  font-size: calc((8px) * var(--cl-font-scale, 1));
  font-weight: 800;
  letter-spacing: 0.7px;
}

/* =========================================================
   LEARNING RESPONSIVE
========================================================= */

@media (max-width: 1000px) {
  .learnNavLinks {
    display: none;
  }

  .learnHero {
    grid-template-columns: 1fr;
  }

  .learnHeroVisual {
    height: 480px;
  }

  .learnSectionHeader {
    grid-template-columns: 1fr;
    gap: 30px;
  }

  .learningModule {
    grid-template-columns: 70px 1fr;
  }

  .moduleAction {
    grid-column: 2;
    justify-content: flex-start;
  }

  .processCards {
    grid-template-columns: repeat(2, 1fr);
  }

  .processCard:nth-child(2) {
    border-right: 0;
  }

  .processCard:nth-child(1),
  .processCard:nth-child(2) {
    border-bottom: 1px solid rgba(0, 200, 255, 0.15);
  }

  .principlesSection {
    grid-template-columns: 1fr;
    gap: 60px;
  }

  .learnFooterTop {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 650px) {
  .learnNav {
    padding: 0 20px;
  }

  .learnNavStatus {
    display: none;
  }

  .learnHero {
    padding: 70px 25px;
  }

  .learnHero h1 {
    font-size: calc((70px) * var(--cl-font-scale, 1));
    letter-spacing: -4px;
  }

  .learnHeroMeta {
    flex-direction: column;
  }

  .learnHeroMeta div {
    border-right: 0;
    border-bottom: 1px solid rgba(0, 200, 255, 0.15);
  }

  .learnHeroVisual {
    transform: scale(0.75);
    margin: -50px;
  }

  .learningPath,
  .learnProcess,
  .principlesSection {
    padding: 80px 25px;
  }

  .learningModule {
    grid-template-columns: 1fr;
    gap: 20px;
    padding: 30px 25px;
  }

  .moduleAction {
    grid-column: auto;
  }

  .processCards {
    grid-template-columns: 1fr;
  }

  .processCard {
    border-right: 0;
    border-bottom: 1px solid rgba(0, 200, 255, 0.15);
  }

  .processCard:last-child {
    border-bottom: 0;
  }

  .learnFinal {
    padding: 80px 25px;
  }

  .learnFinal h2 {
    font-size: calc((65px) * var(--cl-font-scale, 1));
    letter-spacing: -4px;
  }

  .finalGrid {
    width: 300px;
    height: 300px;
    right: -100px;
    opacity: 0.25;
  }

  .learnFooter {
    padding-left: 25px;
    padding-right: 25px;
  }

  .learnFooterTop {
    grid-template-columns: 1fr;
    gap: 40px;
  }

  .learnFooterBottom {
    flex-direction: column;
  }
}

/* =========================================================
   ABOUT VALUES — PROFESSIONAL ICONS
========================================================= */

.about-values .feature-icon {
  width: 52px;
  height: 52px;
  margin-bottom: 28px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1px solid rgba(0, 200, 255, 0.35);
