}

.about-values h3 {
  margin-top: 0;
}

/* =========================================================
   CHAINLAB — LEARNING PATH IMAGE CARDS
   LANDING PAGE ONLY
========================================================= */

.paths-section {
  width: min(1320px, calc(100% - 60px));
  margin: 0 auto;
  padding: 150px 0 170px;
}

.paths-section .section-heading-row {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 50px;
  margin-bottom: 70px;
}

.paths-section .section-label {
  margin-bottom: 28px;
}

.paths-section h2 {
  margin: 0;
  color: #ffffff;
  font-size: calc((clamp(58px, 7vw, 108px)) * var(--cl-font-scale, 1));
  font-weight: 900;
  line-height: 0.9;
  letter-spacing: -0.06em;
}

.paths-section h2 span {
  color: #ffb000;
}

.paths-section .text-link {
  flex-shrink: 0;
  color: #ffb000;
  text-decoration: none;
  font-size: calc((13px) * var(--cl-font-scale, 1));
  font-weight: 900;
  letter-spacing: 0.04em;
  white-space: nowrap;
  transition:
    color 180ms ease,
    transform 180ms ease;
}

.paths-section .text-link:hover {
  color: #ffffff;
  transform: translateX(4px);
}


/* =========================================================
   FIVE LEARNING CARDS
========================================================= */

.paths-section .paths-grid {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 14px;
}


/* =========================================================
   CARD
========================================================= */

.paths-section .path-card {
  position: relative;

  min-width: 0;
  min-height: 560px;

  padding: 16px;

  display: flex;
  flex-direction: column;

  color: #ffffff;
  text-decoration: none;

  background:
    linear-gradient(
      180deg,
      #06121c 0%,
      #020a11 100%
    );

  border: 1px solid
    rgba(0, 191, 255, 0.25);

  overflow: hidden;

  transition:
    transform 220ms ease,
    border-color 220ms ease,
    box-shadow 220ms ease;
}

.paths-section .path-card:hover {
  transform: translateY(-7px);

  border-color:
    rgba(0, 191, 255, 0.75);

  box-shadow:
    0 25px 70px
    rgba(0, 170, 255, 0.14);
}


/* =========================================================
   4K IMAGE
========================================================= */

.paths-section .path-visual {
  position: relative;

  width: 100%;
  aspect-ratio: 1 / 1;

  margin-bottom: 28px;

  overflow: hidden;

  background: #02070c;

  border: 1px solid
    rgba(0, 191, 255, 0.24);
}

.paths-section .path-visual::after {
  content: "";

  position: absolute;
  inset: 0;

  pointer-events: none;

  background:
    linear-gradient(
      180deg,
      rgba(0, 0, 0, 0) 55%,
      rgba(0, 0, 0, 0.3) 100%
    );
}

.paths-section .path-visual img {
  display: block;

  width: 100%;
  height: 100%;

  object-fit: cover;
  object-position: center;

  image-rendering: auto;

  transition:
    transform 500ms
    cubic-bezier(0.2, 0.7, 0.2, 1);
}

.paths-section .path-card:hover
.path-visual img {
  transform: scale(1.055);
}


/* =========================================================
   NUMBER
========================================================= */

.paths-section .path-number {
  margin-bottom: 12px;

  color: #00bfff;

  font-size: calc((12px) * var(--cl-font-scale, 1));
  font-weight: 900;

  letter-spacing: 0.08em;
}


/* =========================================================
   TITLE
========================================================= */

.paths-section .path-card h3 {
  margin: 0 0 14px;

  color: #ffffff;

  font-size: calc((20px) * var(--cl-font-scale, 1));
  font-weight: 900;

  line-height: 1;

  letter-spacing: -0.02em;
}


/* =========================================================
   DESCRIPTION
========================================================= */

.paths-section .path-card p {
  margin: 0;

  color: rgba(255, 255, 255, 0.72);

  font-size: calc((13px) * var(--cl-font-scale, 1));
  line-height: 1.65;
}


/* =========================================================
   ACTION
========================================================= */

.paths-section .path-card strong {
  margin-top: auto;
  padding-top: 30px;

  color: #ffb000;

  font-size: calc((11px) * var(--cl-font-scale, 1));
  font-weight: 900;

  letter-spacing: 0.05em;
}


/* =========================================================
   TABLET
========================================================= */

@media (max-width: 1150px) {
  .paths-section {
    width: calc(100% - 48px);
  }

  .paths-section .paths-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .paths-section .path-card {
    min-height: 540px;
  }
}


/* =========================================================
   MOBILE
========================================================= */

@media (max-width: 850px) {
  .paths-section {
    width: calc(100% - 30px);
    padding-top: 100px;
    padding-bottom: 110px;
  }

  .paths-section .section-heading-row {
    display: block;
    margin-bottom: 50px;
  }

  .paths-section .text-link {
    display: inline-block;
    margin-top: 28px;
  }

  .paths-section h2 {
    font-size: calc((clamp(50px, 11vw, 82px)) * var(--cl-font-scale, 1));
  }

  .paths-section .paths-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}


/* =========================================================
   SMALL MOBILE
========================================================= */

@media (max-width: 560px) {
  .paths-section {
    width: calc(100% - 30px);
    padding-top: 80px;
    padding-bottom: 90px;
  }

  .paths-section h2 {
    font-size: calc((48px) * var(--cl-font-scale, 1));
  }

  .paths-section .paths-grid {
    grid-template-columns: 1fr;
  }

  .paths-section .path-card {
    min-height: auto;
  }

  .paths-section .path-visual {
    aspect-ratio: 16 / 10;
  }
}

