  color: #10141a;
  border-color: rgba(0, 0, 0, 0.14);
}

html[data-theme="light"] .chainlab-tool-button:hover,
html[data-theme="light"] .chainlab-chat-button:hover {
  background: #10141a;
  color: #ffffff;
  border-color: #10141a;
}

