  background: #ffffff;
  border-color: rgba(0, 0, 0, 0.12);
}

html[data-theme="light"] .font-control-panel button {
  color: #10141a;
  border-color: rgba(0, 0, 0, 0.1);
}

/* Mobile navigation */

