/* =========================================================
   CHAINLAB — MOBILE NAVIGATION / COOKIE / PROGRESS / LOADING
   ========================================================= */


/* =========================================================
   READING PROGRESS
   ========================================================= */

.reading-progress {
  position: fixed;
  top: 0;
  left: 0;

  width: 100%;
  height: 3px;

  z-index: 10050;

  pointer-events: none;

  background: transparent;
}

.reading-progress-bar {
  height: 100%;
  width: 0;

  background: #00d9ff;

  transition: width 0.08s linear;

  box-shadow:
    0 0 10px rgba(0, 217, 255, 0.55);
}


/* =========================================================
   COOKIE CONSENT
   ========================================================= */

.cookie-consent {
  position: fixed;

  left: 24px;
  right: 24px;
  bottom: 24px;

  z-index: 10020;

  padding: 22px 24px;

  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 18px;

  background: rgba(2, 5, 10, 0.96);

  color: #ffffff;

  box-shadow:
    0 25px 80px rgba(0, 0, 0, 0.45);

  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);

  animation:
    cookie-consent-enter
    0.45s ease both;
}

.cookie-consent-content {
  display: flex;

  align-items: center;
  justify-content: space-between;

  gap: 40px;

  max-width: 1400px;
  margin: 0 auto;
}

.cookie-consent-text {
  max-width: 760px;
}

.cookie-consent-label {
  display: block;

  margin-bottom: 8px;

  color: #00d9ff;

  font-size: calc((10px) * var(--cl-font-scale, 1));
  font-weight: 800;

  letter-spacing: 0.14em;
}

.cookie-consent-text h2 {
  margin: 0 0 8px;

  color: #ffffff;

  font-size: calc((18px) * var(--cl-font-scale, 1));
  font-weight: 700;
}

.cookie-consent-text p {
  margin: 0;

  color: rgba(255, 255, 255, 0.62);

  font-size: calc((13px) * var(--cl-font-scale, 1));
  line-height: 1.7;
}

.cookie-consent-actions {
  display: flex;

  align-items: center;

  gap: 10px;

  flex-shrink: 0;
}

.cookie-button {
  min-width: 110px;

  padding: 13px 18px;

  border-radius: 10px;

  font-family: inherit;

  font-size: calc((11px) * var(--cl-font-scale, 1));
  font-weight: 800;

  letter-spacing: 0.08em;

  cursor: pointer;

  transition:
    background 0.2s ease,
    color 0.2s ease,
    border-color 0.2s ease,
    transform 0.2s ease;
}

.cookie-button:hover {
  transform: translateY(-2px);
}

.cookie-button-primary {
  border: 1px solid #00d9ff;

  background: #00d9ff;
  color: #02050a;
}

.cookie-button-primary:hover {
  background: #ffffff;
  border-color: #ffffff;
}

.cookie-button-secondary {
  border: 1px solid rgba(255, 255, 255, 0.18);

  background: transparent;
  color: #ffffff;
}

.cookie-button-secondary:hover {
  border-color: #ffffff;
  background: #ffffff;
  color: #02050a;
}

@keyframes cookie-consent-enter {
  from {
    opacity: 0;
    transform: translateY(25px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}


/* =========================================================
   PAGE TRANSITION
   ========================================================= */

.page-transition {
  position: fixed;

  inset: 0;

  z-index: 10040;

  display: flex;

  align-items: center;
  justify-content: center;

  background: #02050a;

  color: #ffffff;

  pointer-events: none;

  opacity: 0;
  visibility: hidden;

  transition:
    opacity 0.35s ease,
    visibility 0.35s ease;
}

.page-transition-active {
  opacity: 1;
  visibility: visible;

  pointer-events: all;
}

.page-transition-content {
  width: min(520px, 80%);

  text-align: center;
}

.page-transition-brand {
  margin-bottom: 25px;

  color: #ffffff;

  font-size: calc((18px) * var(--cl-font-scale, 1));
  font-weight: 900;

  letter-spacing: 0.1em;
}

.page-transition-line {
  width: 100%;
  height: 2px;

  overflow: hidden;

  background: rgba(255, 255, 255, 0.1);
}

.page-transition-line span {
  display: block;

  width: 35%;
  height: 100%;

  background: #00d9ff;

  animation:
    page-transition-loading
    0.9s ease-in-out infinite;
}

.page-transition-label {
  margin-top: 15px;

  color: rgba(255, 255, 255, 0.45);

  font-size: calc((9px) * var(--cl-font-scale, 1));
  font-weight: 700;

  letter-spacing: 0.16em;
}

@keyframes page-transition-loading {
  0% {
    transform: translateX(-120%);
  }

  50% {
    transform: translateX(180%);
  }

  100% {
    transform: translateX(350%);
  }
}


/* =========================================================
   MOBILE NAVIGATION — GLOBAL BUTTON
   ========================================================= */

.mobile-menu-button {
  display: none;

  position: fixed;

  top: 18px;
  right: 20px;

  z-index: 10001;

  width: 44px;
  height: 44px;

  padding: 0;

  border: 1px solid rgba(255, 255, 255, 0.16);
  border-radius: 10px;

  background: rgba(2, 5, 10, 0.9);

  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);

  cursor: pointer;
}

.mobile-menu-button span {
  display: block;

  width: 19px;
  height: 1px;

  margin: 4px auto;

  background: #ffffff;

  transition:
    transform 0.25s ease,
    opacity 0.25s ease;
}

.mobile-menu-button.open span:nth-child(1) {
  transform:
    translateY(5px)
    rotate(45deg);
}

.mobile-menu-button.open span:nth-child(2) {
  opacity: 0;
}

.mobile-menu-button.open span:nth-child(3) {
  transform:
    translateY(-5px)
    rotate(-45deg);
}


/* =========================================================
   MOBILE NAVIGATION PANEL
   ========================================================= */

.mobile-navigation {
  position: fixed;

  inset: 0;

  z-index: 10000;

  display: flex;
  flex-direction: column;

  padding: 24px;

  background: #02050a;
  color: #ffffff;

  opacity: 0;
  visibility: hidden;

  transform: translateY(-20px);

  transition:
    opacity 0.25s ease,
    visibility 0.25s ease,
    transform 0.25s ease;
}

.mobile-navigation-open {
  opacity: 1;
  visibility: visible;

  transform: translateY(0);
}

.mobile-navigation-header {
  display: flex;

  align-items: center;
  justify-content: space-between;

  padding-bottom: 30px;

  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
}

.mobile-navigation-brand {
  color: #ffffff;

  font-size: calc((15px) * var(--cl-font-scale, 1));
  font-weight: 800;

  letter-spacing: 0.08em;

  text-decoration: none;
}

.mobile-navigation-close {
  width: 42px;
  height: 42px;

  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: 10px;

  background: transparent;

  color: #ffffff;

  font-size: calc((25px) * var(--cl-font-scale, 1));

  cursor: pointer;
}

.mobile-navigation-links {
