  border-bottom: 1px solid rgba(255, 255, 255, 0.1);

  color: #ffffff;

  font-size: calc((clamp(28px, 8vw, 52px)) * var(--cl-font-scale, 1));

  font-weight: 800;

  letter-spacing: -0.04em;

  text-decoration: none;

  transition:
    color 0.2s ease,
