/* =========================================
   CHAINLAB TOOLBAR LAYOUT
   ========================================= */

.chainlab-utility-inner {
  position: relative;

  display: flex;
  align-items: center;
  justify-content: space-between;

  width: 100%;
  box-sizing: border-box;

  padding: 0 20px;
}

/* Font size and theme controls */

.chainlab-toolbar-center {
  display: flex;
  align-items: center;
  justify-content: flex-start;
}

/* Device button at the far right */

.chainlab-toolbar-right {
  display: flex;
  align-items: center;
  justify-content: flex-end;

  margin-left: auto;
}

/* Device button wrapper */

.chainlab-toolbar-right .device-preview-control {
  position: relative;
  margin-left: auto;
}

/* Mobile layout */

@media (max-width: 600px) {
  .chainlab-utility-inner {
    padding: 0 10px;
  }
}

/* DEVICE BUTTON — INCREASED SIZE */

.device-preview-button {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;

  /* Make the button bigger */
  min-width: 160px;
  min-height: 60px;
  padding: 20px 40px;

  box-sizing: border-box;

  background-color: #212121;
  color: #fefefe;

  /* Thick, visible border */
  border: 3px solid #fefefe;
  border-radius: 6px;

  /* Larger, clearer text */
  font-family: inherit;
  font-size: 20px;
  font-weight: 700;
  letter-spacing: 2px;
  text-transform: uppercase;

  white-space: nowrap;
  cursor: pointer;
  isolation: isolate;
  overflow: hidden;

  transition:
    color 0.3s ease,
    border-color 0.3s ease,
    background-color 0.3s ease;
}

/* Keep the text above the animated background */

.device-preview-button span {
  position: relative;
  z-index: 3;
}

/* Light mode */

html[data-theme="light"] .device-preview-button {
  background-color: #e8e8e8;
  color: #212121;
  border-color: #212121;
}

/* Mobile adjustment */

@media (max-width: 600px) {
  .device-preview-button {
    min-width: 130px;
    min-height: 52px;
    padding: 16px 24px;
    font-size: 16px;
  }
}

/* =========================================================
   CHAINLAB LANDING PAGE — REMOVE SOLID DARK CARD BOXES
   Keeps the content and borders, but lets the page background
   show through instead of rendering cards as black panels.
========================================================= */

.paths-section .path-card {
