  font-weight: 800;
  letter-spacing: 0.16em;
  color: #55d6c2;
}

.study-notes-hero h1 {
  max-width: 850px;
  margin: 0 0 24px;
  font-size: clamp(2.5rem, 6vw, 5rem);
  line-height: 1.05;
  font-weight: 850;
  letter-spacing: -0.055em;
}

.study-notes-hero h1 span {
  display: block;
  color: #55d6c2;
}

.study-notes-hero-content > p {
  max-width: 720px;
  margin: 0;
  font-size: 1.1rem;
  line-height: 1.8;
  opacity: 0.78;
}

.study-notes-hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 14px;
  margin-top: 32px;
}

.study-notes-primary-button,
.study-notes-secondary-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  min-height: 48px;
  padding: 13px 22px;
  border-radius: 10px;
  font-size: 0.9rem;
  font-weight: 750;
  text-decoration: none;
  transition:
    transform 180ms ease,
    opacity 180ms ease,
    background 180ms ease;
}

.study-notes-primary-button {
  color: #061311;
  background: #55d6c2;
}

.study-notes-secondary-button {
  color: inherit;
  border: 1px solid currentColor;
  background: transparent;
}

.study-notes-primary-button:hover,
.study-notes-secondary-button:hover {
  transform: translateY(-2px);
  opacity: 0.88;
}

.study-notes-stats {
  display: flex;
  flex-wrap: wrap;
  gap: 50px;
  margin-top: 55px;
}

.study-notes-stat {
