  border-color: rgba(85, 214, 194, 0.65);
  background: rgba(85, 214, 194, 0.045);
}

.study-notes-card-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
  margin-bottom: 24px;
}

.study-notes-number {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 42px;
  height: 42px;
  border-radius: 11px;
  color: #061311;
  background: #55d6c2;
  font-size: 0.9rem;
  font-weight: 900;
}

.study-notes-category {
  padding: 7px 10px;
  border: 1px solid rgba(128, 128, 128, 0.3);
  border-radius: 100px;
  font-size: 0.67rem;
  font-weight: 800;
  letter-spacing: 0.08em;
  opacity: 0.8;
}

.study-notes-card h3 {
  margin: 0 0 13px;
  font-size: 1.35rem;
  line-height: 1.35;
  font-weight: 800;
  letter-spacing: -0.025em;
}

.study-notes-description {
  margin: 0 0 22px;
  font-size: 0.94rem;
  line-height: 1.75;
  opacity: 0.72;
}

.study-notes-topics {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: auto;
  margin-bottom: 25px;
}

.study-notes-topics span {
  padding: 7px 10px;
  border-radius: 7px;
  background: rgba(128, 128, 128, 0.12);
  font-size: 0.72rem;
  line-height: 1.4;
  opacity: 0.85;
}

.study-notes-card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 15px;
  padding-top: 20px;
  border-top: 1px solid rgba(128, 128, 128, 0.2);
}

.study-notes-file-type {
  font-size: 0.68rem;
  font-weight: 800;
  letter-spacing: 0.1em;
  opacity: 0.55;
}

.study-notes-download-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 11px 15px;
  border-radius: 9px;
  color: #061311;
  background: #55d6c2;
  font-size: 0.82rem;
  font-weight: 800;
  text-decoration: none;
  transition:
    transform 180ms ease,
    opacity 180ms ease;
}

.study-notes-download-button:hover {
  transform: translateY(-2px);
  opacity: 0.85;
}

.study-notes-bottom-cta {
  max-width: 1152px;
  margin: 60px auto 0;
  padding: 55px 30px;
  border: 1px solid rgba(128, 128, 128, 0.24);
  border-radius: 18px;
  text-align: center;
  background: rgba(128, 128, 128, 0.045);
}

.study-notes-bottom-cta h2 {
  margin: 0 auto 15px;
  font-size: clamp(1.8rem, 4vw, 2.8rem);
