  border-color: rgba(183, 255, 60, 0.45);
}

.achievement-card.earned:hover {
  transform: translateY(-5px);
  border-color: var(--achievement-accent, #b7ff3c);
}

.achievement-card.locked {
  opacity: 0.62;
}

.achievement-card-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 25px;
}

.achievement-icon {
  display: grid;
  width: 65px;
  height: 65px;
  place-items: center;
  border: 1px solid var(--achievement-border);
  border-radius: 16px;
  background: rgba(128, 128, 128, 0.08);
  font-size: 32px;
}

.achievement-status {
  padding: 7px 10px;
  border-radius: 50px;
  font-family: monospace;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 1px;
}

.status-earned {
  color: #101500;
  background: var(--achievement-accent, #b7ff3c);
}

.status-locked {
  border: 1px solid var(--achievement-border);
  color: var(--muted-foreground, #999);
}

.achievement-card h3 {
  margin: 0 0 12px;
  font-size: 18px;
  font-weight: 900;
  letter-spacing: 0.5px;
}

.achievement-description {
  margin: 0 0 25px;
  color: var(--muted-foreground, #a3a3a3);
  font-size: 14px;
  line-height: 1.7;
}

.achievement-requirement {
  margin-top: auto;
  padding-top: 18px;
  border-top: 1px solid var(--achievement-border);
}

.achievement-requirement span {
  color: var(--muted-foreground, #999);
  font-family: monospace;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1.5px;
}

.achievement-requirement p {
  margin: 9px 0 0;
  font-size: 12px;
  line-height: 1.6;
}

.achievement-earned-label {
  margin-top: 18px;
  color: var(--achievement-accent, #b7ff3c);
  font-family: monospace;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 1px;
}

.achievement-modules {
  max-width: 1200px;
  margin: 0 auto;
  padding: 75px 0 30px;
  border-top: 1px solid var(--achievement-border);
}

.achievement-modules h2 {
  font-size: clamp(45px, 7vw, 80px);
}

.achievement-module-links {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
  margin: 35px 0;
}

.achievement-module-links a {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  padding: 20px 22px;
  border: 1px solid var(--achievement-border);
  border-radius: 10px;
  color: inherit;
  font-size: 13px;
  font-weight: 800;
  letter-spacing: 1px;
  text-decoration: none;
  transition:
    border-color 200ms ease,
    background 200ms ease;
}

.achievement-module-links a:hover {
  border-color: var(--achievement-accent, #b7ff3c);
  background: rgba(128, 128, 128, 0.06);
}

.achievement-module-links a span {
  color: var(--achievement-accent, #b7ff3c);
  font-size: 20px;
}

.achievement-main-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 20px;
  padding: 17px 24px;
  border: 1px solid var(--achievement-accent, #b7ff3c);
  border-radius: 8px;
  color: #101500;
  background: var(--achievement-accent, #b7ff3c);
  font-size: 12px;
  font-weight: 900;
  letter-spacing: 1px;
  text-decoration: none;
  transition:
    transform 200ms ease,
    opacity 200ms ease;
}

.achievement-main-button:hover {
  transform: translateY(-2px);
  opacity: 0.9;
}

/* Light theme support */

html[data-theme="light"] .achievements-page {
  --achievement-border: rgba(0, 0, 0, 0.13);
}

html[data-theme="light"] .achievement-card,
html[data-theme="light"] .achievement-summary-card {
  background: rgba(0, 0, 0, 0.025);
}

/* Responsive layout */

@media (max-width: 900px) {
  .achievement-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .achievement-summary {
    grid-template-columns: 1fr;
  }

  .achievement-summary-card {
    padding: 22px;
  }
}

@media (max-width: 600px) {
  .achievements-page {
    padding: 55px 5% 70px;
  }

  .achievements-hero {
    padding-top: 35px;
  }

  .achievements-hero h1,
  .achievement-modules h2 {
    letter-spacing: -2px;
  }

  .achievement-grid {
    grid-template-columns: 1fr;
  }

  .achievement-section-heading {
    align-items: flex-start;
    flex-direction: column;
  }

  .achievement-module-links {
    grid-template-columns: 1fr;
  }

  .achievement-card {
    min-height: 270px;
  }
}

