/* =========================================================
   CHAINLAB LOGIN PAGE — REFERENCE-MATCHED FINAL OVERRIDE
   This section intentionally recreates the supplied reference:
   dark full-screen shell, 76px top navigation, left Web3 hero,
   glowing blockchain network, and glass login card.
   ========================================================= */

/* The global site header is not used on the login page. */
body:has(.auth-page) {
  padding-top: 0 !important;
  margin: 0 !important;
  background: #02070d !important;
  overflow-x: hidden !important;
}

body:has(.auth-page) .site-header,
body:has(.auth-page) .chainlab-utility-bar,
body:has(.auth-page) .chainlab-utility-inner {
  display: none !important;
}

.auth-page {
  position: relative;
  min-height: 100vh;
  width: 100%;
  overflow: hidden;
  color: #f7fbff;
  background:
    radial-gradient(circle at 18% 60%, rgba(0, 108, 255, .16), transparent 28%),
    radial-gradient(circle at 72% 46%, rgba(0, 190, 255, .075), transparent 26%),
    radial-gradient(circle at 100% 70%, rgba(0, 90, 255, .08), transparent 25%),
    #02070d;
}

/* ---------- TOP NAV ---------- */

.auth-topbar {
  position: relative;
  z-index: 50;
  width: 100%;
  height: 76px;
  display: flex;
  align-items: center;
  padding: 0 clamp(28px, 5.8vw, 90px);
  gap: 42px;
  border-bottom: 1px solid rgba(34, 153, 219, .18);
  background: rgba(2, 7, 13, .84);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
}

.auth-brand {
  flex: 0 0 auto;
  color: #f8fbff;
  text-decoration: none;
  font-size: 30px;
  line-height: 1;
  font-weight: 800;
  letter-spacing: -1.5px;
}

.auth-brand span {
  color: #13d7ff;
}

.auth-nav {
  display: flex;
  align-items: center;
  gap: clamp(24px, 2.7vw, 43px);
  margin-left: 36px;
}

.auth-nav a {
  position: relative;
  color: #b9c9d8;
  text-decoration: none;
  font-size: 14px;
  line-height: 1;
  font-weight: 500;
  letter-spacing: .015em;
  transition: color .18s ease;
}

.auth-nav a::after {
  content: "";
  position: absolute;
  left: 0;
  right: 100%;
  bottom: -9px;
  height: 1px;
  background: #18d9ff;
  transition: right .18s ease;
}

.auth-nav a:hover {
  color: #fff;
}

.auth-nav a:hover::after {
  right: 0;
}

.auth-top-actions {
  display: flex;
  align-items: center;
  gap: 20px;
  margin-left: auto;
}

.auth-icon-button {
  width: 31px;
  height: 31px;
  display: grid;
  place-items: center;
  padding: 0;
  border: 0;
  background: transparent;
  color: #9eb1c3;
  cursor: pointer;
  transition: color .18s ease, transform .18s ease;
}

.auth-icon-button:hover {
  color: #19d8ff;
  transform: translateY(-1px);
}

.auth-icon-button svg {
  width: 22px;
  height: 22px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.55;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.auth-get-started {
  min-width: 148px;
  height: 45px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0 19px;
  border: 1px solid #0fd3ff;
  border-radius: 11px;
  color: #f8fcff;
  background: rgba(0, 178, 255, .025);
  text-decoration: none;
  font-size: 13px;
  font-weight: 700;
  letter-spacing: .035em;
  box-shadow: 0 0 24px rgba(0, 205, 255, .09);
  transition: background .18s ease, box-shadow .18s ease, transform .18s ease;
}

.auth-get-started:hover {
  background: rgba(0, 205, 255, .10);
  box-shadow: 0 0 30px rgba(0, 205, 255, .20);
  transform: translateY(-1px);
}

/* ---------- MAIN SHELL ---------- */

.auth-shell {
  position: relative;
  z-index: 2;
  width: min(1450px, 100%);
  min-height: calc(100vh - 76px);
  margin: 0 auto;
  padding: 48px clamp(28px, 5.8vw, 90px) 52px;
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(500px, 610px);
  align-items: center;
  column-gap: clamp(48px, 6.8vw, 105px);
}

.auth-background-grid {
  position: absolute;
  z-index: 0;
  inset: 0;
  pointer-events: none;
  opacity: .26;
  background-image:
    linear-gradient(rgba(30, 147, 226, .07) 1px, transparent 1px),
    linear-gradient(90deg, rgba(30, 147, 226, .07) 1px, transparent 1px);
  background-size: 64px 64px;
  mask-image: linear-gradient(to bottom, transparent 0%, black 13%, black 86%, transparent 100%);
  -webkit-mask-image: linear-gradient(to bottom, transparent 0%, black 13%, black 86%, transparent 100%);
}

.auth-glow {
  position: absolute;
  z-index: 0;
  pointer-events: none;
  border-radius: 50%;
  filter: blur(85px);
}

.auth-glow-one {
  width: 520px;
  height: 520px;
  left: -110px;
  top: 18%;
  background: rgba(0, 106, 255, .095);
}

.auth-glow-two {
  width: 390px;
  height: 390px;
  right: 17%;
  bottom: -80px;
  background: rgba(0, 213, 255, .055);
}

/* ---------- LEFT HERO ---------- */

.auth-hero {
  position: relative;
  z-index: 4;
  min-width: 0;
  padding-left: clamp(0px, 1.2vw, 18px);
}

.auth-eyebrow {
  margin: 0 0 24px;
  color: #27d9ff;
  font-size: 13px;
  line-height: 1;
  font-weight: 700;
  letter-spacing: .31em;
}

.auth-hero h1 {
  margin: 0;
  color: #f8fbff;
  font-size: clamp(60px, 5.7vw, 88px);
  line-height: .965;
  font-weight: 800;
  letter-spacing: -.057em;
}

.auth-hero h1 span {
  color: #12d8ff;
  text-shadow: 0 0 34px rgba(18, 216, 255, .14);
}

.auth-hero-copy {
  max-width: 595px;
  margin: 27px 0 0;
  color: #b8c8d8;
  font-size: 19px;
  line-height: 1.58;
}

/* ---------- BLOCKCHAIN ART ---------- */

.auth-network {
  position: relative;
  width: min(100%, 690px);
  height: 305px;
  margin: 3px 0 -2px;
  overflow: visible;
}

/* Glowing perspective floor under the network. */
.auth-network::after {
  content: "";
  position: absolute;
  left: 3%;
  right: 0;
  bottom: 14px;
  height: 135px;
  opacity: .42;
  transform: perspective(450px) rotateX(60deg);
  transform-origin: bottom center;
  background-image:
    linear-gradient(rgba(0, 181, 255, .15) 1px, transparent 1px),
    linear-gradient(90deg, rgba(0, 181, 255, .15) 1px, transparent 1px);
  background-size: 42px 42px;
  mask-image: radial-gradient(ellipse at center, black 0%, transparent 72%);
  -webkit-mask-image: radial-gradient(ellipse at center, black 0%, transparent 72%);
  pointer-events: none;
}

.auth-network-core {
  position: absolute;
  z-index: 5;
  left: 54%;
  top: 55%;
  width: 174px;
  height: 145px;
  transform: translate(-50%, -50%) perspective(650px) rotateX(10deg) rotateZ(-1deg);
  display: grid;
  place-items: center;
  border: 1px solid rgba(44, 211, 255, .88);
  border-radius: 9px;
  background:
    linear-gradient(145deg, rgba(20, 120, 192, .38), rgba(2, 16, 29, .91)),
    rgba(3, 20, 34, .9);
  box-shadow:
    0 0 12px rgba(19, 207, 255, .48),
    0 0 42px rgba(0, 183, 255, .24),
    inset 0 0 40px rgba(7, 148, 255, .16);
}

/* Cube side / depth. */
.auth-network-core::before {
  content: "";
  position: absolute;
  z-index: -1;
  left: 17px;
  right: -18px;
  bottom: -25px;
  height: 25px;
  transform: skewX(-38deg);
  transform-origin: top left;
  border: 1px solid rgba(17, 151, 215, .42);
  background: linear-gradient(90deg, rgba(3, 26, 43, .92), rgba(2, 12, 23, .92));
  box-shadow: 0 15px 28px rgba(0, 0, 0, .55);
}

/* Inner glow / top face. */
.auth-network-core::after {
  content: "";
  position: absolute;
  inset: -18px;
  border: 1px solid rgba(28, 199, 255, .18);
  border-radius: 13px;
  box-shadow: 0 0 42px rgba(0, 180, 255, .13);
  pointer-events: none;
}

.auth-chain-symbol {
  position: relative;
  z-index: 2;
  width: 66px;
  height: 48px;
  filter: drop-shadow(0 0 12px rgba(23, 207, 255, .72));
}

.auth-chain-symbol span {
  position: absolute;
  width: 39px;
  height: 23px;
  border: 6px solid #16caff;
  border-radius: 20px;
  transform: rotate(-37deg);
}

.auth-chain-symbol span:first-child {
  left: 0;
  top: 18px;
}

.auth-chain-symbol span:last-child {
  right: 0;
  top: 4px;
}

/* Small blockchain cubes. */
.auth-network-node {
  position: absolute;
  z-index: 4;
  width: 54px;
  height: 54px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(35, 210, 255, .78);
  border-radius: 5px;
  background:
    linear-gradient(145deg, rgba(16, 107, 169, .48), rgba(2, 24, 41, .92));
  box-shadow:
    0 0 18px rgba(0, 190, 255, .25),
    inset 0 0 17px rgba(0, 173, 255, .10);
  transform: perspective(400px) rotateX(7deg) rotateZ(-1deg);
}

.auth-network-node::before {
  content: "";
  position: absolute;
  left: 9px;
  right: -10px;
  bottom: -10px;
  height: 10px;
  transform: skewX(-42deg);
  background: rgba(2, 28, 45, .84);
  border-right: 1px solid rgba(29, 189, 239, .4);
  border-bottom: 1px solid rgba(29, 189, 239, .3);
}

.auth-network-node span {
  width: 13px;
  height: 13px;
  border-radius: 2px;
  background: #12d7ff;
  box-shadow:
    0 0 9px #12d7ff,
    0 0 24px rgba(18, 215, 255, .72);
}

.node-one { left: 15%; top: 52%; }
.node-two { left: 36%; top: 12%; }
.node-three { right: 8%; top: 44%; }
.node-four { right: 26%; top: 2%; }

.auth-network-line {
  position: absolute;
  z-index: 2;
  height: 1px;
  transform-origin: left center;
  background: linear-gradient(
    90deg,
    rgba(18, 202, 255, .04),
    rgba(18, 202, 255, .58),
    rgba(18, 202, 255, .08)
  );
  box-shadow: 0 0 8px rgba(20, 196, 255, .30);
}

.line-one {
  width: 270px;
  left: 20%;
  top: 60%;
  transform: rotate(-16deg);
}

.line-two {
  width: 225px;
  left: 41%;
  top: 31%;
  transform: rotate(29deg);
}

.line-three {
  width: 245px;
  left: 53%;
  top: 61%;
  transform: rotate(-10deg);
}

/* ---------- BENEFITS ---------- */

.auth-benefits {
  position: relative;
  z-index: 5;
  display: grid;
  gap: 15px;
  max-width: 575px;
  margin-top: -1px;
}

.auth-benefit {
  display: flex;
  align-items: center;
  gap: 18px;
}

.auth-benefit-icon {
  flex: 0 0 54px;
  width: 54px;
  height: 54px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(21, 170, 255, .23);
  border-radius: 11px;
  background: linear-gradient(145deg, rgba(5, 52, 84, .78), rgba(2, 19, 33, .76));
  box-shadow:
    inset 0 0 18px rgba(8, 157, 255, .08),
    0 5px 20px rgba(0, 0, 0, .14);
}

.auth-benefit-icon svg {
  width: 26px;
  height: 26px;
  fill: none;
  stroke: #36d9ff;
  stroke-width: 1.45;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.auth-benefit strong {
  display: block;
  margin: 0 0 4px;
  color: #fff;
  font-size: 13px;
  line-height: 1.1;
  letter-spacing: .02em;
}

.auth-benefit span {
  display: block;
  color: #9fb1c3;
  font-size: 14px;
  line-height: 1.4;
}

/* ---------- LOGIN CARD ---------- */

.auth-card {
  position: relative;
  z-index: 10;
  width: 100%;
  padding: 55px 78px 45px;
  border: 1px solid rgba(46, 161, 224, .66);
  border-radius: 17px;
  background:
    linear-gradient(145deg, rgba(9, 28, 45, .84), rgba(4, 14, 24, .96)),
    rgba(4, 13, 23, .90);
  box-shadow:
    0 30px 90px rgba(0, 0, 0, .42),
    0 0 38px rgba(0, 157, 255, .075),
    inset 0 1px 0 rgba(255, 255, 255, .045);
  backdrop-filter: blur(24px);
  -webkit-backdrop-filter: blur(24px);
}

.auth-card::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  border-radius: inherit;
  background:
    linear-gradient(
      135deg,
      rgba(31, 204, 255, .06),
      transparent 27%,
      transparent 73%,
      rgba(31, 204, 255, .025)
    );
}

.auth-card-header {
  position: relative;
  z-index: 1;
  margin-bottom: 38px;
}

.auth-card-header h2 {
  margin: 0 0 9px;
  color: #f7fbff;
  font-size: 38px;
  line-height: 1.1;
  font-weight: 750;
  letter-spacing: -.025em;
}

.auth-card-header p {
  margin: 0;
  color: #b6c5d4;
  font-size: 16px;
  line-height: 1.5;
}

.auth-form {
  position: relative;
  z-index: 1;
}

.auth-field {
  display: block;
  margin-bottom: 25px;
}

.auth-field > span {
  display: block;
  margin-bottom: 10px;
  color: #f3f8fc;
  font-size: 15px;
  font-weight: 600;
}

.auth-input-wrapper {
  position: relative;
}

.auth-input-icon {
  position: absolute;
  left: 17px;
  top: 50%;
  z-index: 2;
  width: 22px;
  height: 22px;
  display: grid;
  place-items: center;
  transform: translateY(-50%);
  color: #c0cfdd;
}

.auth-input-icon svg {
  width: 21px;
  height: 21px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.45;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.auth-input-wrapper input {
  width: 100%;
  height: 52px;
  padding: 0 48px;
  border: 1px solid rgba(93, 127, 153, .56);
  border-radius: 10px;
  outline: none;
  color: #f3f8ff;
  background: rgba(5, 16, 28, .68);
  font: inherit;
  font-size: 15px;
  box-sizing: border-box;
  transition: border-color .18s ease, box-shadow .18s ease, background .18s ease;
}

.auth-input-wrapper input::placeholder {
  color: #718396;
}

.auth-input-wrapper input:focus {
  border-color: rgba(18, 211, 255, .82);
  background: rgba(7, 22, 37, .86);
  box-shadow:
    0 0 0 3px rgba(18, 211, 255, .08),
    0 0 25px rgba(18, 211, 255, .05);
}

.auth-input-wrapper input:disabled {
  opacity: .62;
}

.auth-password-toggle {
  position: absolute;
  right: 13px;
  top: 50%;
  width: 31px;
  height: 31px;
  display: grid;
  place-items: center;
  padding: 0;
  transform: translateY(-50%);
  border: 0;
  background: transparent;
  color: #8ea2b5;
  cursor: pointer;
}

.auth-password-toggle:hover {
  color: #16d5ff;
}

.auth-password-toggle svg {
  width: 21px;
  height: 21px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.45;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.auth-options {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin: 1px 0 27px;
}

.remember-me {
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: 11px;
  color: #dce6ee;
  font-size: 14px;
  cursor: pointer;
  user-select: none;
}

.remember-me input {
  position: absolute;
  opacity: 0;
  pointer-events: none;
}

.custom-checkbox {
  width: 18px;
  height: 18px;
  display: inline-block;
  border: 1px solid #8ea2b5;
  border-radius: 4px;
  background: rgba(2, 10, 17, .72);
  transition: all .16s ease;
}

.remember-me input:checked + .custom-checkbox {
  border-color: #11d4ff;
  background: #11d4ff;
  box-shadow: 0 0 14px rgba(17, 212, 255, .22);
}

.remember-me input:checked + .custom-checkbox::after {
  content: "✓";
  display: block;
  color: #02121d;
  font-size: 13px;
  font-weight: 900;
  line-height: 17px;
  text-align: center;
}

.forgot-password {
  padding: 0;
  border: 0;
  background: transparent;
  color: #13d8ff;
  font: inherit;
  font-size: 14px;
  cursor: pointer;
}

.forgot-password:hover {
  color: #7beaff;
}

.auth-primary-button {
  width: 100%;
  height: 55px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  border: 0;
  border-radius: 10px;
  color: #02131c;
  background: linear-gradient(90deg, #14d9f7, #18b9ef);
  font: inherit;
  font-size: 16px;
  font-weight: 800;
  cursor: pointer;
  box-shadow: 0 10px 25px rgba(7, 195, 239, .13);
  transition: transform .16s ease, box-shadow .16s ease, filter .16s ease;
}

.auth-primary-button span {
  font-size: 23px;
  line-height: 0;
}

.auth-primary-button:hover:not(:disabled) {
  transform: translateY(-1px);
  box-shadow: 0 14px 32px rgba(7, 195, 239, .20);
  filter: brightness(1.04);
}

.auth-primary-button:disabled {
  cursor: wait;
  opacity: .7;
}

.auth-message {
  position: relative;
  z-index: 1;
  margin: 14px 0 0;
  padding: 10px 12px;
  border: 1px solid rgba(19, 216, 255, .20);
  border-radius: 8px;
  color: #9defff;
  background: rgba(10, 168, 211, .06);
  font-size: 13px;
  line-height: 1.45;
}

.auth-divider {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
  gap: 16px;
  margin: 29px 0 23px;
  color: #91a3b5;
  font-size: 13px;
}

.auth-divider::before,
.auth-divider::after {
  content: "";
  flex: 1;
  height: 1px;
  background: rgba(129, 151, 170, .32);
}

.auth-divider span {
  flex: 0 0 auto;
}

.auth-social-buttons {
  position: relative;
  z-index: 1;
  display: grid;
  gap: 11px;
}

.auth-social-button {
  width: 100%;
  min-height: 51px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  border: 1px solid rgba(87, 119, 145, .48);
  border-radius: 9px;
  color: #edf5fb;
  background: rgba(10, 24, 38, .62);
  font: inherit;
  font-size: 15px;
  font-weight: 500;
  cursor: pointer;
  transition: border-color .16s ease, background .16s ease, transform .16s ease;
}

.auth-social-button:hover {
  border-color: rgba(19, 211, 255, .52);
  background: rgba(13, 37, 54, .82);
  transform: translateY(-1px);
}

.google-icon,
.apple-icon,
.phantom-icon {
  width: 23px;
  height: 23px;
  display: grid;
  place-items: center;
}

.google-icon svg,
.apple-icon svg,
.phantom-icon svg {
  width: 22px;
  height: 22px;
}

.apple-icon {
  color: #fff;
}

.apple-icon svg {
  fill: currentColor;
}

.phantom-icon {
  color: #a477ff;
}

.phantom-icon svg {
  fill: currentColor;
  filter: drop-shadow(0 0 5px rgba(164, 119, 255, .35));
}

.auth-switch {
  position: relative;
  z-index: 1;
  margin: 34px 0 0;
  color: #aabaca;
  text-align: center;
  font-size: 15px;
}

.auth-switch a {
  color: #13d8ff;
  font-weight: 600;
  text-decoration: none;
}

.auth-switch a:hover {
  text-decoration: underline;
}

.auth-back {
  position: relative;
  z-index: 1;
  display: block;
  margin-top: 25px;
  color: #7f93a6;
  font-size: 13px;
  text-align: center;
  text-decoration: none;
}

.auth-back:hover {
  color: #13d8ff;
}

/* Login is intentionally dark even if the global site is in light mode. */
html.light body:has(.auth-page),
body.light:has(.auth-page) {
  background: #02070d !important;
}

/* ---------- RESPONSIVE ---------- */

@media (max-width: 1220px) {
  .auth-topbar {
    gap: 25px;
    padding-inline: 4vw;
  }

  .auth-nav {
    gap: 23px;
    margin-left: 20px;
  }

  .auth-shell {
    grid-template-columns: minmax(0, 1fr) minmax(440px, 540px);
    column-gap: 42px;
    padding-inline: 4vw;
  }

  .auth-card {
    padding: 46px 48px 40px;
  }

  .auth-network {
    transform: scale(.91);
    transform-origin: left center;
    width: 110%;
    margin-top: -2px;
    margin-bottom: -18px;
  }
}

@media (max-width: 940px) {
  .auth-nav {
    display: none;
  }

  .auth-top-actions {
    margin-left: auto;
  }

  .auth-shell {
    grid-template-columns: 1fr;
    max-width: 700px;
    min-height: auto;
    padding-top: 46px;
  }

  .auth-hero {
    padding-left: 0;
    text-align: center;
  }

  .auth-hero-copy {
    margin-inline: auto;
  }

  .auth-network {
    width: 100%;
    max-width: 690px;
    margin-inline: auto;
    transform: scale(.82);
    transform-origin: center;
    margin-top: -2px;
    margin-bottom: -30px;
  }

  .auth-benefits {
    margin-inline: auto;
    text-align: left;
  }

  .auth-card {
    padding: 43px 42px 38px;
  }
}

@media (max-width: 620px) {
  .auth-topbar {
    height: 68px;
    padding-inline: 20px;
  }

  .auth-brand {
    font-size: 25px;
  }

  .auth-icon-button {
    display: none;
  }

  .auth-get-started {
    min-width: 118px;
    height: 40px;
    font-size: 11px;
  }

  .auth-shell {
    min-height: auto;
    padding: 35px 18px 45px;
  }

  .auth-eyebrow {
    margin-bottom: 20px;
    font-size: 10px;
    letter-spacing: .22em;
  }

  .auth-hero h1 {
    font-size: clamp(49px, 15vw, 68px);
  }

  .auth-hero-copy {
    margin-top: 22px;
    font-size: 16px;
  }

  .auth-network {
    height: 220px;
    transform: scale(.62);
    width: 161%;
    margin-top: -9px;
    margin-bottom: -34px;
    margin-left: -30.5%;
  }

  .auth-benefit-icon {
    flex-basis: 48px;
    width: 48px;
    height: 48px;
  }

  .auth-benefit span {
    font-size: 13px;
  }

  .auth-card {
    padding: 34px 22px 30px;
    border-radius: 14px;
  }

  .auth-card-header h2 {
    font-size: 31px;
  }

  .auth-card-header p {
    font-size: 14px;
  }

  .auth-options {
    align-items: flex-start;
    flex-direction: column;
  }
}

@import url("https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&display=swap");

:root {
  --background: #02050a;
  --surface: #050a11;
  --surface-light: #08111c;
  --border: #123047;
  --border-bright: #075c86;
  --text: #f4f7fb;
  --muted: #8794a6;
  --cyan: #00c8ff;
  --cyan-dark: #007aa8;
  --orange: #ffab00;
  --orange-bright: #ffbd27;
}

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  background: var(--background);
  color: var(--text);
  font-family: "Inter", Arial, Helvetica, sans-serif;
}

a {
  color: inherit;
  text-decoration: none;
}

button,
a {
  -webkit-tap-highlight-color: transparent;
}

main {
  width: 100%;
  overflow: hidden;
}

/* =========================================================
   HEADER
========================================================= */

.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  width: 100%;
  background: rgba(2, 5, 10, 0.92);
  backdrop-filter: blur(16px);
  border-bottom: 1px solid #102031;
}

.nav-inner {
  width: min(1500px, calc(100% - 96px));
  min-height: 96px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 40px;
}

.brand {
  font-size: calc((25px) * var(--cl-font-scale, 1));
  font-weight: 900;
  letter-spacing: -1px;
  white-space: nowrap;
}

.main-nav {
  display: flex;
  align-items: center;
  gap: 34px;
}

.main-nav a {
  position: relative;
  color: #b7c0cd;
  font-size: calc((13px) * var(--cl-font-scale, 1));
  font-weight: 800;
  letter-spacing: 0.5px;
  transition: color 0.2s ease;
}

.main-nav a:hover,
.main-nav a.active {
  color: white;
}

.main-nav a.active::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: -15px;
  height: 3px;
  background: var(--orange);
  box-shadow: 0 0 16px rgba(255, 171, 0, 0.7);
}

.nav-button,
.primary-button,
.secondary-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 14px;
  min-height: 56px;
  padding: 0 28px;
  font-size: calc((13px) * var(--cl-font-scale, 1));
  font-weight: 900;
  letter-spacing: 0.4px;
  transition:
    transform 0.2s ease,
    box-shadow 0.2s ease,
    background 0.2s ease;
}

.nav-button {
  border: 1px solid var(--orange);
  color: var(--orange);
  border-radius: 13px;
}

.nav-button:hover {
  background: var(--orange);
  color: #050505;
}

.primary-button {
  background: var(--orange);
  color: #050505;
  border: 1px solid var(--orange);
  box-shadow: 0 12px 35px rgba(255, 171, 0, 0.12);
}

.primary-button:hover {
  transform: translateY(-3px);
  background: var(--orange-bright);
  box-shadow: 0 18px 45px rgba(255, 171, 0, 0.25);
}

.secondary-button {
  border: 1px solid var(--cyan);
  color: var(--cyan);
  background: transparent;
}

.secondary-button:hover {
  transform: translateY(-3px);
  background: rgba(0, 200, 255, 0.08);
  box-shadow: 0 15px 40px rgba(0, 200, 255, 0.12);
}

/* =========================================================
   HERO
========================================================= */

.hero-section {
  position: relative;
  padding: 78px 0 0;
  background:
    linear-gradient(rgba(0, 200, 255, 0.025) 1px, transparent 1px),
    linear-gradient(90deg, rgba(0, 200, 255, 0.025) 1px, transparent 1px),
    radial-gradient(circle at 75% 40%, rgba(0, 120, 255, 0.12), transparent 30%),
    #02050a;
  background-size: 48px 48px, 48px 48px, auto, auto;
}

.hero-grid {
  width: min(1500px, calc(100% - 96px));
  margin: 0 auto;
  min-height: 690px;
  display: grid;
  grid-template-columns: 0.9fr 1.1fr;
  align-items: center;
}

.hero-content {
  position: relative;
  z-index: 2;
  padding: 30px 0 70px;
}

.eyebrow,
.section-label {
  color: var(--cyan);
  font-size: calc((12px) * var(--cl-font-scale, 1));
  font-weight: 900;
  letter-spacing: 1.6px;
}

.eyebrow {
  display: inline-flex;
  padding: 15px 20px;
  border: 1px solid var(--cyan);
  margin-bottom: 38px;
}

.hero-content h1 {
  margin: 0;
  font-size: calc((clamp(65px, 7vw, 116px)) * var(--cl-font-scale, 1));
  line-height: 0.88;
  letter-spacing: -6px;
  font-weight: 900;
}

.hero-content h1 span,
h2 span {
  color: var(--orange);
}

.hero-description {
  max-width: 670px;
  margin: 40px 0 28px;
  color: #aab5c4;
  font-size: calc((18px) * var(--cl-font-scale, 1));
  line-height: 1.75;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 18px;
}

.hero-note {
  max-width: 610px;
  margin-top: 38px;
  color: #758294;
  font-size: calc((13px) * var(--cl-font-scale, 1));
  line-height: 1.7;
}

.hero-visual {
  position: relative;
  min-height: 680px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.visual-glow {
  position: absolute;
  width: 440px;
  height: 440px;
  border-radius: 50%;
  background: radial-gradient(
    circle,
    rgba(255, 151, 0, 0.42),
    rgba(0, 153, 255, 0.12) 45%,
    transparent 70%
  );
  filter: blur(12px);
}

.visual-orbit {
  position: absolute;
  border: 1px solid rgba(0, 200, 255, 0.65);
  border-radius: 50%;
  transform: rotateX(67deg);
}

.orbit-one {
  width: 570px;
  height: 220px;
}

.orbit-two {
  width: 440px;
  height: 170px;
}

.orbit-three {
  width: 320px;
  height: 125px;
}

.coin-wrapper {
  position: relative;
  z-index: 3;
  width: 430px;
  height: 430px;
}

.hero-coin {
  object-fit: contain;
  filter:
    drop-shadow(0 0 25px rgba(255, 145, 0, 0.35))
    drop-shadow(0 0 55px rgba(0, 170, 255, 0.12));
}

.floating-card {
  position: absolute;
  z-index: 4;
  min-width: 130px;
  padding: 18px 20px;
  border: 1px solid rgba(0, 200, 255, 0.6);
  background: rgba(3, 13, 22, 0.9);
  box-shadow: 0 0 30px rgba(0, 180, 255, 0.12);
  color: var(--cyan);
  font-size: calc((10px) * var(--cl-font-scale, 1));
  font-weight: 900;
  letter-spacing: 1px;
}

.floating-card span {
  display: block;
  margin-bottom: 7px;
  font-size: calc((18px) * var(--cl-font-scale, 1));
}

.card-learn {
  left: 4%;
  top: 22%;
}

.card-blockchain {
  right: 2%;
  top: 26%;
}

.card-security {
  left: 8%;
  bottom: 22%;
}

.card-community {
  right: 3%;
  bottom: 19%;
}

.hero-features {
  width: min(1320px, calc(100% - 96px));
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  border: 1px solid var(--border);
}

.feature-item {
  min-height: 150px;
  padding: 30px;
  display: flex;
  gap: 20px;
  border-right: 1px solid var(--border);
}

.feature-item:last-child {
  border-right: 0;
}

.feature-icon {
  flex: 0 0 auto;
  color: var(--cyan);
  font-size: calc((30px) * var(--cl-font-scale, 1));
  text-shadow: 0 0 20px rgba(0, 200, 255, 0.6);
}

.feature-item h3 {
  margin: 3px 0 12px;
  font-size: calc((13px) * var(--cl-font-scale, 1));
  font-weight: 900;
}

.feature-item p {
  margin: 0;
  color: var(--muted);
  font-size: calc((12px) * var(--cl-font-scale, 1));
  line-height: 1.7;
}

.stats-grid {
  width: min(1320px, calc(100% - 96px));
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  border: 1px solid var(--border);
  border-top: 0;
}

.stat {
  min-height: 115px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  border-right: 1px solid var(--border);
}

.stat:last-child {
  border-right: 0;
}

.stat strong {
  color: var(--orange);
  font-size: calc((26px) * var(--cl-font-scale, 1));
  font-weight: 900;
}

.stat span {
  margin-top: 8px;
  color: #8190a2;
  font-size: calc((10px) * var(--cl-font-scale, 1));
  font-weight: 800;
  letter-spacing: 1px;
}

/* =========================================================
   ABOUT BIRTHDAY MESSAGING
========================================================= */

.about-section,
.mission-section,
.paths-section,
.process-section,
.testimonials-section,
.faq-section {
  width: min(1320px, calc(100% - 96px));
  margin: 0 auto;
}

.about-section {
  padding: 150px 0;
}

.about-grid {
  margin-top: 50px;
  display: grid;
  grid-template-columns: 0.9fr 1.1fr;
  gap: 90px;
  align-items: center;
}

.about-content h2,
.mission-heading h2,
.paths-section h2,
.process-section h2,
.featured-content h2,
.security-content h2,
.testimonials-section h2,
.faq-heading h2,
.final-inner h2 {
  margin: 0;
  font-size: calc((clamp(45px, 5vw, 72px)) * var(--cl-font-scale, 1));
  line-height: 0.98;
  letter-spacing: -3px;
  font-weight: 900;
}

.about-content p {
  max-width: 650px;
  color: var(--muted);
  font-size: calc((16px) * var(--cl-font-scale, 1));
  line-height: 1.8;
}

.about-content .primary-button {
  margin-top: 20px;
}

/* =========================================================
   4K HEADQUARTERS IMAGE
========================================================= */

.about-visual {
  position: relative;
  width: 100%;
}

.about-image-frame {
  position: relative;
  width: 100%;
  aspect-ratio: 16 / 9;
  overflow: hidden;
  border: 1px solid var(--border);
  background: #02060b;
}

.about-image-frame img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center center;
}

.about-image {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center center;
  opacity: 0.92;
}

.image-overlay {
  position: absolute;
  inset: auto 30px 30px;
  z-index: 2;
  padding: 28px;
  background: rgba(2, 6, 11, 0.85);
  border: 1px solid rgba(0, 200, 255, 0.3);
}

.image-overlay span {
  display: block;
  color: var(--cyan);
  font-size: calc((10px) * var(--cl-font-scale, 1));
  font-weight: 900;
  letter-spacing: 1.5px;
}

.image-overlay strong {
  display: block;
  margin-top: 8px;
  font-size: calc((31px) * var(--cl-font-scale, 1));
  font-weight: 900;
}

.image-overlay small {
  display: block;
  margin-top: 8px;
  color: var(--orange);
  font-size: calc((10px) * var(--cl-font-scale, 1));
  font-weight: 900;
  letter-spacing: 1px;
}

.about-values {
  margin-top: 80px;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  border-top: 1px solid var(--border);
}

.about-values > div {
  padding: 35px 35px 0 0;
  border-right: 1px solid var(--border);
}

.about-values > div:not(:first-child) {
  padding-left: 35px;
}

.about-values > div:last-child {
  border-right: 0;
}

.about-values span,
.number,
.path-number {
  color: var(--cyan);
  font-size: calc((11px) * var(--cl-font-scale, 1));
  font-weight: 900;
  letter-spacing: 1px;
}

.about-values h3,
.mission-grid h3,
.process-step h3 {
  margin: 14px 0 10px;
  font-size: calc((14px) * var(--cl-font-scale, 1));
  font-weight: 900;
}

.about-values p,
.mission-grid p,
.process-step p {
  margin: 0;
  color: var(--muted);
  line-height: 1.7;
  font-size: calc((13px) * var(--cl-font-scale, 1));
}

/* =========================================================
   MISSION
========================================================= */

.mission-section {
  padding: 100px 0 150px;
}

.mission-heading {
  margin-top: 40px;
  display: grid;
  grid-template-columns: 1.2fr 0.8fr;
  gap: 80px;
  align-items: end;
}

.mission-heading p {
  color: var(--muted);
  font-size: calc((16px) * var(--cl-font-scale, 1));
  line-height: 1.8;
}

.mission-grid {
  margin-top: 75px;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  border: 1px solid var(--border);
}

.mission-grid article {
  min-height: 280px;
  padding: 35px;
  border-right: 1px solid var(--border);
}

.mission-grid article:last-child {
  border-right: 0;
}

.mission-grid h3 {
  margin-top: 60px;
  line-height: 1.4;
}

/* =========================================================
   LEARNING PATHS
   LANDING PAGE — 4K IMAGE CARDS
========================================================= */

.paths-section {
  width: min(1320px, calc(100% - 60px));
  margin: 0 auto;
  padding: 150px 0 170px;
}

.paths-section .section-heading-row {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 50px;
  margin-bottom: 70px;
}

.paths-section .section-label {
  margin-bottom: 28px;
}

.paths-section h2 {
  margin: 0;
  color: #ffffff;
  font-size: calc((clamp(58px, 7vw, 108px)) * var(--cl-font-scale, 1));
  font-weight: 900;
  line-height: 0.9;
  letter-spacing: -0.06em;
}

.paths-section h2 span {
  color: #ffb000;
}

.paths-section .text-link {
  flex-shrink: 0;
  color: #ffb000;
  text-decoration: none;
  font-size: calc((13px) * var(--cl-font-scale, 1));
  font-weight: 900;
  letter-spacing: 0.04em;
  white-space: nowrap;
  transition: color 180ms ease, transform 180ms ease;
}

.paths-section .text-link:hover {
  color: #ffffff;
  transform: translateX(4px);
}

.paths-section .paths-grid {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 14px;
}

.paths-section .path-card {
  position: relative;
  min-width: 0;
  min-height: 560px;
  padding: 16px;
  display: flex;
  flex-direction: column;
  color: #ffffff;
  text-decoration: none;
  background: linear-gradient(180deg, #06121c 0%, #020a11 100%);
  border: 1px solid rgba(0, 191, 255, 0.25);
  overflow: hidden;
  transition:
    transform 220ms ease,
    border-color 220ms ease,
    box-shadow 220ms ease;
}

.paths-section .path-card:hover {
  transform: translateY(-7px);
  border-color: rgba(0, 191, 255, 0.75);
  box-shadow: 0 25px 70px rgba(0, 170, 255, 0.14);
}

.paths-section .path-visual {
  position: relative;
  width: 100%;
  aspect-ratio: 1 / 1;
  margin-bottom: 28px;
  overflow: hidden;
  background: #02070c;
  border: 1px solid rgba(0, 191, 255, 0.24);
}

.paths-section .path-visual::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: linear-gradient(
    180deg,
    rgba(0, 0, 0, 0) 55%,
    rgba(0, 0, 0, 0.3) 100%
  );
}

.paths-section .path-visual img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;
  image-rendering: auto;
  transition: transform 500ms cubic-bezier(0.2, 0.7, 0.2, 1);
}

.paths-section .path-card:hover .path-visual img {
  transform: scale(1.055);
}

.paths-section .path-number {
  margin-bottom: 12px;
  color: #00bfff;
  font-size: calc((12px) * var(--cl-font-scale, 1));
  font-weight: 900;
  letter-spacing: 0.08em;
}

.paths-section .path-card h3 {
  margin: 0 0 14px;
  color: #ffffff;
  font-size: calc((20px) * var(--cl-font-scale, 1));
  font-weight: 900;
  line-height: 1;
  letter-spacing: -0.02em;
}

.paths-section .path-card p {
  margin: 0;
  color: rgba(255, 255, 255, 0.72);
  font-size: calc((13px) * var(--cl-font-scale, 1));
  line-height: 1.65;
}

.paths-section .path-card strong {
  margin-top: auto;
  padding-top: 30px;
  color: #ffb000;
  font-size: calc((11px) * var(--cl-font-scale, 1));
  font-weight: 900;
  letter-spacing: 0.05em;
}

@media (max-width: 1150px) {
  .paths-section {
    width: calc(100% - 48px);
  }

  .paths-section .paths-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .paths-section .path-card {
    min-height: 540px;
  }
}

@media (max-width: 850px) {
  .paths-section {
    width: calc(100% - 30px);
    padding-top: 100px;
    padding-bottom: 110px;
  }

  .paths-section .section-heading-row {
    display: block;
    margin-bottom: 50px;
  }

  .paths-section .text-link {
    display: inline-block;
    margin-top: 28px;
  }

  .paths-section h2 {
    font-size: calc((clamp(50px, 11vw, 82px)) * var(--cl-font-scale, 1));
  }

  .paths-section .paths-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 560px) {
  .paths-section {
    width: calc(100% - 30px);
    padding-top: 80px;
    padding-bottom: 90px;
  }

  .paths-section h2 {
    font-size: calc((48px) * var(--cl-font-scale, 1));
  }

  .paths-section .paths-grid {
    grid-template-columns: 1fr;
  }

  .paths-section .path-card {
    min-height: auto;
  }

  .paths-section .path-visual {
    aspect-ratio: 16 / 10;
  }
}

/* =========================================================
   PROCESS
========================================================= */

.process-section {
  padding: 80px 0 150px;
}

.process-section h2 {
  margin-top: 25px;
}

.process-grid {
  margin-top: 70px;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
}

.process-step {
  min-height: 250px;
  padding: 30px;
  border-top: 1px solid var(--border);
  border-right: 1px solid var(--border);
}

.process-step:last-child {
  border-right: 0;
}

.step-number {
  width: 52px;
  height: 52px;
  border: 1px solid var(--cyan);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--cyan);
  font-weight: 900;
  box-shadow: 0 0 20px rgba(0, 200, 255, 0.1);
}

.process-step h3 {
  margin-top: 35px;
}

/* =========================================================
   FEATURED
========================================================= */

.featured-section {
  min-height: 670px;
  display: grid;
  grid-template-columns: 1.2fr 0.8fr;
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
  background: #03070c;
}

.featured-image {
  position: relative;
  min-height: 670px;
  overflow: hidden;
  background:
    radial-gradient(
      circle at 50% 50%,
      rgba(0, 150, 255, 0.18),
      transparent 30%
    ),
    #02060b;
}

.featured-grid {
  position: absolute;
  inset: 0;
  opacity: 0.3;
  background:
    linear-gradient(rgba(0, 200, 255, 0.06) 1px, transparent 1px),
    linear-gradient(90deg, rgba(0, 200, 255, 0.06) 1px, transparent 1px);
  background-size: 55px 55px;
}

.featured-orb {
  position: absolute;
  border-radius: 50%;
  border: 1px solid var(--cyan);
  box-shadow: 0 0 40px rgba(0, 200, 255, 0.15);
}

.orb-one {
  width: 500px;
  height: 500px;
  left: 15%;
  top: 12%;
}

.orb-two {
  width: 350px;
  height: 350px;
  left: 27%;
  top: 25%;
}

.featured-center {
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  width: 230px;
  height: 230px;
  border-radius: 50%;
  border: 1px solid var(--cyan);
  background: rgba(2, 10, 17, 0.95);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  box-shadow:
    0 0 40px rgba(0, 200, 255, 0.25),
    inset 0 0 40px rgba(0, 200, 255, 0.08);
}

.featured-center span {
  color: var(--cyan);
  font-size: calc((10px) * var(--cl-font-scale, 1));
  font-weight: 900;
  letter-spacing: 2px;
}

.featured-center strong {
  margin-top: 8px;
  font-size: calc((40px) * var(--cl-font-scale, 1));
  font-weight: 900;
}

.featured-center small {
  color: var(--orange);
  margin-top: 5px;
  font-weight: 900;
  letter-spacing: 2px;
}

.featured-cube {
  position: absolute;
  padding: 22px 18px;
  border: 1px solid var(--cyan);
  background: rgba(2, 12, 20, 0.85);
  color: var(--cyan);
  font-size: calc((9px) * var(--cl-font-scale, 1));
  font-weight: 900;
  box-shadow: 0 0 30px rgba(0, 200, 255, 0.12);
}

.cube-one {
  left: 13%;
  top: 25%;
}

.cube-two {
  right: 13%;
  top: 21%;
}

.cube-three {
  left: 19%;
  bottom: 19%;
}

.featured-content {
  padding: 90px 70px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  border-left: 1px solid var(--border);
}

.featured-content h2 {
  margin-top: 25px;
}

.featured-content p {
  color: var(--muted);
  line-height: 1.8;
  font-size: calc((15px) * var(--cl-font-scale, 1));
}

.featured-content .primary-button {
  align-self: flex-start;
  margin-top: 18px;
}

/* =========================================================
   SECURITY
========================================================= */

.security-section {
  width: min(1320px, calc(100% - 96px));
  margin: 0 auto;
  padding: 150px 0;
  display: grid;
  grid-template-columns: 0.9fr 1.1fr;
  gap: 80px;
  align-items: center;
}

.security-content h2 {
  margin-top: 25px;
}

.security-content p {
  max-width: 650px;
  color: var(--muted);
  line-height: 1.8;
  font-size: calc((15px) * var(--cl-font-scale, 1));
}

.security-content .secondary-button {
  margin-top: 20px;
}

.security-visual {
  position: relative;
  height: 500px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.security-ring {
  position: absolute;
  border: 1px solid rgba(0, 200, 255, 0.45);
  border-radius: 50%;
}

.ring-one {
  width: 470px;
  height: 470px;
}

.ring-two {
  width: 350px;
  height: 350px;
}

.ring-three {
  width: 230px;
  height: 230px;
}

.security-lock {
  position: relative;
  z-index: 2;
  width: 210px;
  height: 210px;
  border: 1px solid var(--cyan);
  background: rgba(3, 12, 20, 0.94);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  box-shadow: 0 0 50px rgba(0, 200, 255, 0.16);
}

.security-lock span {
  color: var(--cyan);
  font-size: calc((52px) * var(--cl-font-scale, 1));
}

.security-lock strong {
  margin-top: 8px;
  font-size: calc((18px) * var(--cl-font-scale, 1));
  font-weight: 900;
}

.security-lock small {
  margin-top: 8px;
  color: var(--orange);
  font-size: calc((8px) * var(--cl-font-scale, 1));
  font-weight: 900;
  letter-spacing: 1px;
}

/* =========================================================
   TESTIMONIALS
========================================================= */

.testimonials-section {
  padding: 100px 0 150px;
}

.testimonial-grid {
  margin-top: 55px;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 15px;
}

.testimonial-card {
  min-height: 320px;
  padding: 35px;
  border: 1px solid var(--border);
  background: linear-gradient(
    160deg,
    rgba(6, 17, 28, 0.8),
    rgba(2, 7, 13, 0.95)
  );
}

.quote {
  color: var(--cyan);
  font-size: calc((50px) * var(--cl-font-scale, 1));
  line-height: 0.7;
}

.testimonial-card p {
  min-height: 130px;
  color: #a8b4c4;
  font-size: calc((14px) * var(--cl-font-scale, 1));
  line-height: 1.8;
}

.testimonial-author {
  display: flex;
  flex-direction: column;
  border-top: 1px solid var(--border);
  padding-top: 20px;
}

.testimonial-author strong {
  font-size: calc((11px) * var(--cl-font-scale, 1));
  letter-spacing: 1px;
}

.testimonial-author span {
  margin-top: 6px;
  color: var(--muted);
  font-size: calc((11px) * var(--cl-font-scale, 1));
}

/* =========================================================
   FAQ
========================================================= */

.faq-section {
  padding: 80px 0 150px;
  display: grid;
  grid-template-columns: 0.8fr 1.2fr;
  gap: 100px;
}

.faq-heading h2 {
  margin-top: 25px;
}

.faq-list {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.faq-list details {
  border: 1px solid var(--border);
  background: rgba(4, 11, 18, 0.8);
}

.faq-list summary {
  min-height: 75px;
  padding: 0 25px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  cursor: pointer;
  list-style: none;
  font-size: calc((13px) * var(--cl-font-scale, 1));
  font-weight: 800;
}

.faq-list summary::-webkit-details-marker {
  display: none;
}

.faq-list summary span {
  color: var(--cyan);
  font-size: calc((25px) * var(--cl-font-scale, 1));
  font-weight: 400;
}

.faq-list details[open] summary span {
  transform: rotate(45deg);
}

.faq-list p {
  margin: 0;
  padding: 0 25px 25px;
  color: var(--muted);
  line-height: 1.7;
  font-size: calc((13px) * var(--cl-font-scale, 1));
}

/* =========================================================
   FINAL
========================================================= */

.final-section {
  padding: 150px 30px;
  border-top: 1px solid var(--border);
  background:
    radial-gradient(
      circle at 50% 40%,
      rgba(0, 160, 255, 0.12),
      transparent 35%
    ),
    #02060b;
  text-align: center;
}

.final-inner {
  max-width: 900px;
  margin: 0 auto;
}

.final-inner h2 {
  margin-top: 25px;
}

.final-inner p {
  max-width: 600px;
  margin: 35px auto;
  color: var(--muted);
  line-height: 1.8;
}

.large-button {
  min-width: 220px;
}

/* =========================================================
   FOOTER
========================================================= */

.site-footer {
  padding: 80px max(48px, calc((100vw - 1320px) / 2)) 30px;
  border-top: 1px solid var(--border);
  background: #010408;
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 70px;
}

.footer-brand p {
  max-width: 390px;
  color: var(--muted);
  line-height: 1.7;
  font-size: calc((12px) * var(--cl-font-scale, 1));
}

.footer-tagline {
  display: inline-block;
  margin-top: 18px;
  color: var(--cyan);
  font-size: calc((9px) * var(--cl-font-scale, 1));
  font-weight: 900;
  letter-spacing: 2px;
}

.footer-column {
  display: flex;
  flex-direction: column;
  gap: 13px;
}

.footer-column h4 {
  margin: 0 0 10px;
  color: white;
  font-size: calc((11px) * var(--cl-font-scale, 1));
  letter-spacing: 1px;
}

.footer-column a,
.footer-column span {
  color: var(--muted);
  font-size: calc((11px) * var(--cl-font-scale, 1));
}

.footer-column a:hover {
  color: var(--cyan);
}

.footer-bottom {
  margin-top: 65px;
  padding-top: 25px;
  border-top: 1px solid var(--border);
  display: flex;
  justify-content: space-between;
  gap: 30px;
  color: #536171;
  font-size: calc((10px) * var(--cl-font-scale, 1));
  letter-spacing: 0.5px;
}

/* =========================================================
   TABLET
========================================================= */

@media (max-width: 1150px) {
  .main-nav {
    gap: 17px;
  }

  .main-nav a {
    font-size: calc((11px) * var(--cl-font-scale, 1));
  }

  .nav-inner,
  .hero-grid,
  .hero-features,
  .stats-grid,
  .about-section,
  .mission-section,
  .paths-section,
  .process-section,
  .security-section,
  .testimonials-section,
  .faq-section {
    width: min(100% - 48px, 1320px);
  }

  .paths-grid {
    grid-template-columns: repeat(3, 1fr);
  }

  .mission-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .mission-grid article:nth-child(2) {
    border-right: 0;
  }

  .mission-grid article:nth-child(1),
  .mission-grid article:nth-child(2) {
    border-bottom: 1px solid var(--border);
  }
}

/* =========================================================
   MOBILE
========================================================= */

