  .site-header {
    position: relative;
  }

  .nav-inner {
    width: calc(100% - 30px);
    min-height: 78px;
  }

  .brand {
    font-size: calc((19px) * var(--cl-font-scale, 1));
  }

  .main-nav {
    display: none;
  }

  .nav-button {
    min-height: 44px;
    padding: 0 15px;
