  }

  .orbit-two {
    width: 310px;
    height: 120px;
  }

  .orbit-three {
    width: 230px;
    height: 90px;
  }

  .floating-card {
    min-width: auto;
    padding: 12px;
    font-size: calc((8px) * var(--cl-font-scale, 1));
  }

  .card-learn {
    left: 0;
    top: 18%;
  }

  .card-blockchain {
    right: 0;
    top: 22%;
  }

  .card-security {
