    border-right: 0;
    border-bottom: 1px solid var(--border);
  }

  .mission-grid {
    grid-template-columns: 1fr;
  }

  .mission-grid article,
  .mission-grid article:nth-child(2) {
    border-right: 0;
    border-bottom: 1px solid var(--border);
  }

  .mission-grid article:last-child {
    border-bottom: 0;
  }

  .paths-grid {
    grid-template-columns: 1fr;
  }

  .path-card {
    min-height: 390px;
  }

  .section-heading-row {
    display: block;
  }

  .section-heading-row .text-link {
    display: inline-block;
    margin-top: 25px;
  }

  .process-grid {
    grid-template-columns: 1fr;
  }

  .process-step {
    border-right: 0;
    border-bottom: 1px solid var(--border);
  }

  .featured-section {
    display: block;
  }

  .featured-image {
    min-height: 470px;
  }

  .featured-content {
    padding: 70px 25px;
    border-left: 0;
    border-top: 1px solid var(--border);
  }

  .security-visual {
    height: 390px;
  }

  .ring-one {
    width: 350px;
    height: 350px;
  }

  .ring-two {
    width: 270px;
    height: 270px;
  }

  .ring-three {
    width: 190px;
    height: 190px;
  }

  .testimonial-grid {
    grid-template-columns: 1fr;
  }

  .footer-grid {
    grid-template-columns: 1fr 1fr;
    gap: 45px;
  }

  .footer-brand {
    grid-column: 1 / -1;
  }

  .footer-bottom {
    flex-direction: column;
  }
}

@media (max-width: 500px) {
  .nav-button {
    display: none;
  }

  .hero-actions {
    flex-direction: column;
  }

  .hero-actions a {
    width: 100%;
  }

  .hero-visual {
    min-height: 400px;
  }

  .coin-wrapper {
    width: 280px;
    height: 280px;
  }

  .floating-card {
    transform: scale(0.8);
  }

  .eyebrow {
    font-size: calc((9px) * var(--cl-font-scale, 1));
  }

  /*
    Headquarters image remains 16:9.
    Do NOT use a fixed height here.
  */
  .about-image-frame {
    width: 100%;
    aspect-ratio: 16 / 9;
    min-height: 0;
  }

  .about-image {
    width: 100%;
    height: 100%;
    object-fit: cover;
  }

  .featured-center {
    width: 180px;
    height: 180px;
  }

  .featured-center strong {
    font-size: calc((30px) * var(--cl-font-scale, 1));
  }

  .footer-grid {
    grid-template-columns: 1fr;
  }

  .footer-brand {
    grid-column: auto;
  }

  .site-footer {
    padding-left: 25px;
    padding-right: 25px;
  }
}

/* =========================================================
   CHAINLAB LEARNING HUB
========================================================= */

.learnPage {
