  font-size: calc((clamp(60px, 8vw, 120px)) * var(--cl-font-scale, 1));
  line-height: 0.85;
  letter-spacing: -6px;
}

.learnFinal h2 span {
  color: #ffad00;
}

.learnFinal p {
  max-width: 600px;
  margin: 35px 0;
