  line-height: 1.8;
  font-size: calc((15px) * var(--cl-font-scale, 1));
}

.learnStartButton {
  display: inline-flex;
  gap: 25px;
  align-items: center;
  padding: 18px 25px;
  background: #ffad00;
  color: #050505;
