  font-size: calc((12px) * var(--cl-font-scale, 1));
  line-height: 1.8;
}

.learnFooterColumn {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.learnFooterColumn h4 {
  color: #00c8ff;
  font-size: calc((9px) * var(--cl-font-scale, 1));
  letter-spacing: 1.5px;
  margin: 0 0 8px;
}

.learnFooterColumn a {
  color: #8799ab;
  font-size: calc((11px) * var(--cl-font-scale, 1));
}

.learnFooterColumn a:hover {
  color: white;
}

.learnFooterBottom {
  display: flex;
  justify-content: space-between;
  gap: 30px;
  padding-top: 25px;
  border-top: 1px solid rgba(0, 200, 255, 0.1);
  color: #506276;
  font-size: calc((8px) * var(--cl-font-scale, 1));
  font-weight: 800;
  letter-spacing: 0.7px;
}

/* =========================================================
   LEARNING RESPONSIVE
========================================================= */

@media (max-width: 1000px) {
  .learnNavLinks {
    display: none;
  }

  .learnHero {
    grid-template-columns: 1fr;
  }

  .learnHeroVisual {
    height: 480px;
  }

  .learnSectionHeader {
    grid-template-columns: 1fr;
    gap: 30px;
  }

  .learningModule {
    grid-template-columns: 70px 1fr;
  }

  .moduleAction {
    grid-column: 2;
    justify-content: flex-start;
  }

  .processCards {
    grid-template-columns: repeat(2, 1fr);
  }

  .processCard:nth-child(2) {
    border-right: 0;
  }

  .processCard:nth-child(1),
  .processCard:nth-child(2) {
    border-bottom: 1px solid rgba(0, 200, 255, 0.15);
  }

  .principlesSection {
    grid-template-columns: 1fr;
    gap: 60px;
  }

  .learnFooterTop {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 650px) {
  .learnNav {
    padding: 0 20px;
  }

  .learnNavStatus {
    display: none;
  }

  .learnHero {
    padding: 70px 25px;
  }

  .learnHero h1 {
    font-size: calc((70px) * var(--cl-font-scale, 1));
    letter-spacing: -4px;
  }

  .learnHeroMeta {
    flex-direction: column;
  }

  .learnHeroMeta div {
    border-right: 0;
    border-bottom: 1px solid rgba(0, 200, 255, 0.15);
  }

  .learnHeroVisual {
    transform: scale(0.75);
    margin: -50px;
  }

  .learningPath,
  .learnProcess,
  .principlesSection {
    padding: 80px 25px;
  }

  .learningModule {
    grid-template-columns: 1fr;
    gap: 20px;
    padding: 30px 25px;
  }

  .moduleAction {
    grid-column: auto;
  }

  .processCards {
    grid-template-columns: 1fr;
  }

  .processCard {
    border-right: 0;
    border-bottom: 1px solid rgba(0, 200, 255, 0.15);
  }

  .processCard:last-child {
    border-bottom: 0;
  }

  .learnFinal {
    padding: 80px 25px;
  }

  .learnFinal h2 {
    font-size: calc((65px) * var(--cl-font-scale, 1));
    letter-spacing: -4px;
  }

  .finalGrid {
    width: 300px;
    height: 300px;
    right: -100px;
    opacity: 0.25;
  }

  .learnFooter {
    padding-left: 25px;
    padding-right: 25px;
  }

  .learnFooterTop {
    grid-template-columns: 1fr;
    gap: 40px;
  }

  .learnFooterBottom {
    flex-direction: column;
  }
}

/* =========================================================
   ABOUT VALUES — PROFESSIONAL ICONS
========================================================= */

.about-values .feature-icon {
  width: 52px;
  height: 52px;
  margin-bottom: 28px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1px solid rgba(0, 200, 255, 0.35);
  color: #00c8ff;
  background: rgba(0, 200, 255, 0.035);
  box-shadow:
    0 0 25px rgba(0, 200, 255, 0.07),
    inset 0 0 20px rgba(0, 200, 255, 0.025);
  transition:
    border-color 0.25s ease,
    background 0.25s ease,
    box-shadow 0.25s ease,
    transform 0.25s ease;
}

.about-values > div:hover .feature-icon {
  border-color: rgba(0, 200, 255, 0.8);
  background: rgba(0, 200, 255, 0.08);
  box-shadow:
    0 0 30px rgba(0, 200, 255, 0.16),
    inset 0 0 25px rgba(0, 200, 255, 0.04);
  transform: translateY(-3px);
}

.about-values .feature-icon svg {
  display: block;
  width: 29px;
  height: 29px;
}

.about-values > div > span {
  display: block;
  margin-bottom: 14px;
}

.about-values h3 {
  margin-top: 0;
}

/* =========================================================
   CHAINLAB — LEARNING PATH IMAGE CARDS
   LANDING PAGE ONLY
========================================================= */

.paths-section {
  width: min(1320px, calc(100% - 60px));
  margin: 0 auto;
  padding: 150px 0 170px;
}

.paths-section .section-heading-row {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 50px;
  margin-bottom: 70px;
}

.paths-section .section-label {
  margin-bottom: 28px;
}

.paths-section h2 {
  margin: 0;
  color: #ffffff;
  font-size: calc((clamp(58px, 7vw, 108px)) * var(--cl-font-scale, 1));
  font-weight: 900;
  line-height: 0.9;
  letter-spacing: -0.06em;
}

.paths-section h2 span {
  color: #ffb000;
}

.paths-section .text-link {
  flex-shrink: 0;
  color: #ffb000;
  text-decoration: none;
  font-size: calc((13px) * var(--cl-font-scale, 1));
  font-weight: 900;
  letter-spacing: 0.04em;
  white-space: nowrap;
  transition:
    color 180ms ease,
    transform 180ms ease;
}

.paths-section .text-link:hover {
  color: #ffffff;
  transform: translateX(4px);
}


/* =========================================================
   FIVE LEARNING CARDS
========================================================= */

.paths-section .paths-grid {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 14px;
}


/* =========================================================
   CARD
========================================================= */

.paths-section .path-card {
  position: relative;

  min-width: 0;
  min-height: 560px;

  padding: 16px;

