    border-radius: 0;
  }

  .mobile-navigation {
    padding: 20px;
  }

  .mobile-navigation-links a {
    font-size: calc((28px) * var(--cl-font-scale, 1));
    padding: 18px 0;
  }
}


/* =========================================================
