    bottom: 84px;

    width: calc(100vw - 24px);
    max-width: none;

    height: min(540px, calc(100dvh - 110px));
    max-height: calc(100dvh - 110px);

    border-radius: 16px;
  }
}

/* =====================================================
   CHAINLAB TOOLBAR LAYOUT
===================================================== */

/* Toolbar container */

.chainlab-utility-bar {
  position: relative;
  width: 100%;
  z-index: 1000;
}

/* Toolbar inner container */

.chainlab-utility-inner {
  position: relative;
  width: 100%;
  min-height: 76px;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 12px 20px;
  box-sizing: border-box;
}

/* Center the font, theme, and device controls */

.chainlab-toolbar-center {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 14px;
  margin-inline: auto;
}

/* Font size and theme controls */

.chainlab-tools {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 14px;
  position: relative;
}

/* =====================================================
   UNIFORM TOOLBAR BUTTON SIZES
===================================================== */

.chainlab-tool-button {
  width: 72px;
  height: 64px;
  min-width: 72px;
  min-height: 64px;

  display: inline-flex;
  align-items: center;
  justify-content: center;

  box-sizing: border-box;

  border: 1px solid #263142;
  border-radius: 18px;

  background: #080f1d;
  color: #f5f7fa;

  font-size: 20px;
  font-weight: 700;

  cursor: pointer;

  transition:
    background 0.2s ease,
    border-color 0.2s ease,
    transform 0.2s ease;
}

.chainlab-tool-button:hover {
  background: #101b2d;
  border-color: #00c8df;
}

.chainlab-tool-button:focus-visible {
  outline: 2px solid #00c8df;
  outline-offset: 3px;
}

/* =====================================================
   DEVICE PREVIEW CONTROL
===================================================== */

/*
   The DevicePreview component should retain its existing
   functionality.

   These rules normalize the visible device button.
*/

.chainlab-toolbar-center .chainlab-device-button {
  width: 72px;
  height: 64px;
  min-width: 72px;
  min-height: 64px;

  display: inline-flex;
  align-items: center;
  justify-content: center;

  box-sizing: border-box;

  border: 1px solid #263142;
  border-radius: 18px;

  background: #080f1d;
  color: #f5f7fa;

  cursor: pointer;
}

/* =====================================================
   FONT SIZE PANEL
===================================================== */

.font-control-wrapper {
  position: relative;
  display: flex;
  align-items: center;
}

.font-control-panel {
  position: absolute;
  bottom: calc(100% + 10px);
  left: 50%;
  transform: translateX(-50%);

  display: flex;
  align-items: center;
  gap: 6px;

  padding: 8px;

  background: #080f1d;
  border: 1px solid #263142;
  border-radius: 14px;

  box-shadow: 0 12px 35px rgba(0, 0, 0, 0.3);

  z-index: 1100;
}

.font-control-panel button {
  width: 42px;
  height: 42px;

  border: 1px solid #263142;
  border-radius: 10px;

  background: #101827;
  color: #f5f7fa;

  font-weight: 700;
  cursor: pointer;
}

.font-control-panel button:hover,
.font-control-panel button.active {
  background: #00c8df;
  color: #02050a;
  border-color: #00c8df;
}

/* =====================================================
   FLOATING CHAT LAUNCHER
===================================================== */

.chainlab-chat-launcher {
  position: fixed !important;

  right: 24px !important;
  bottom: 24px !important;

  top: auto !important;
  left: auto !important;

  width: 150px;
  min-width: 150px;
  height: 58px;

  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;

  box-sizing: border-box;

  padding: 0 20px;

  border: 1px solid #00d4e8;
  border-radius: 16px;

  background: #00c8df;
  color: #02050a;

  font-size: 15px;
  font-weight: 800;
  letter-spacing: 0.04em;

  cursor: pointer;

  box-shadow: 0 8px 28px rgba(0, 0, 0, 0.25);

  z-index: 9998;

  transition:
    background 0.2s ease,
    transform 0.2s ease;
}

.chainlab-chat-launcher:hover {
  background: #36d8e8;
  transform: translateY(-2px);
}

.chainlab-chat-launcher-icon {
  font-size: 20px;
  line-height: 1;
}

/* =====================================================
   FLOATING CHAT WINDOW
===================================================== */

.chainlab-chatbox {
  position: fixed !important;

  right: 24px !important;
  bottom: 96px !important;

  top: auto !important;
  left: auto !important;

  width: 380px;
  max-width: calc(100vw - 32px);

  height: 520px;
  max-height: calc(100dvh - 125px);

  display: flex;
  flex-direction: column;

  box-sizing: border-box;

  overflow: hidden;

  background: #080d18;
  color: #f5f7fa;

  border: 1px solid #263142;
  border-radius: 22px;

  box-shadow: 0 18px 60px rgba(0, 0, 0, 0.45);

  z-index: 9999;
}

/* =====================================================
   CHAT HEADER
===================================================== */

.chainlab-chat-header {
  display: flex;
  align-items: center;
  justify-content: space-between;

  padding: 20px;

  border-bottom: 1px solid #263142;

  flex-shrink: 0;
}

.chainlab-chat-label {
  color: #00c8df;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.08em;
}

.chainlab-chat-header h2 {
  margin: 8px 0 0;
  font-size: 20px;
  font-weight: 800;
}

.chainlab-chat-close {
  width: 38px;
  height: 38px;

  display: flex;
  align-items: center;
  justify-content: center;

  border: 1px solid #263142;
  border-radius: 10px;

  background: #101827;
  color: #f5f7fa;

  font-size: 25px;

  cursor: pointer;
}

.chainlab-chat-close:hover {
  background: #1b2739;
}

/* =====================================================
   CHAT MESSAGES
===================================================== */

.chainlab-chat-messages {
  flex: 1;
  min-height: 0;

  display: flex;
  flex-direction: column;
  gap: 12px;

  overflow-y: auto;

  padding: 20px;
}

.chainlab-message {
  max-width: 90%;

  padding: 12px 15px;

  border-radius: 14px;

  font-size: 14px;
  line-height: 1.6;

  overflow-wrap: anywhere;
}

.assistant-message {
  align-self: flex-start;

  background: #111c2e;
  color: #e7edf5;

  border: 1px solid #263142;
}

.user-message {
  align-self: flex-end;

  background: #00c8df;
  color: #02050a;

  font-weight: 600;
}

/* =====================================================
   QUICK QUESTIONS
===================================================== */

.chainlab-chat-quick {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;

  padding: 12px 16px;

  border-top: 1px solid #263142;
}

.chainlab-chat-quick button {
  padding: 9px 12px;

  border: 1px solid #263142;
  border-radius: 20px;

  background: #101827;
  color: #dce5ef;

  font-size: 12px;
  cursor: pointer;

  transition:
    background 0.2s ease,
    border-color 0.2s ease;
}

.chainlab-chat-quick button:hover {
  background: #17243a;
  border-color: #00c8df;
}

/* =====================================================
   CHAT INPUT
===================================================== */

.chainlab-chat-input {
  display: flex;
  align-items: center;
  gap: 10px;

  padding: 14px 16px;

  border-top: 1px solid #263142;

  flex-shrink: 0;
}

.chainlab-chat-input input {
  flex: 1;
  min-width: 0;
  height: 48px;

  box-sizing: border-box;

  padding: 0 14px;

  border: 1px solid #263142;
  border-radius: 12px;

  outline: none;

  background: #f3f5f8;
  color: #101827;

  font-size: 14px;
}

.chainlab-chat-input input:focus {
  border-color: #00c8df;
  box-shadow: 0 0 0 2px rgba(0, 200, 223, 0.15);
}

.chainlab-chat-input input::placeholder {
  color: #7b8797;
}

.chainlab-chat-input button {
  width: 48px;
  min-width: 48px;
  height: 48px;

  display: flex;
  align-items: center;
  justify-content: center;

  border: none;
  border-radius: 12px;

  background: #00c8df;
  color: #02050a;

  font-size: 24px;
  font-weight: 700;

  cursor: pointer;
}

.chainlab-chat-input button:hover {
  background: #36d8e8;
}

/* =====================================================
   MOBILE RESPONSIVENESS
===================================================== */

@media (max-width: 600px) {
  .chainlab-utility-inner {
    min-height: 68px;
    padding: 8px 12px;
  }

  .chainlab-toolbar-center {
    gap: 8px;
  }

  .chainlab-tools {
    gap: 8px;
  }

  .chainlab-tool-button {
    width: 52px;
    min-width: 52px;
    height: 52px;
    min-height: 52px;

    border-radius: 14px;

    font-size: 17px;
  }

  .chainlab-toolbar-center .chainlab-device-button {
    width: 52px;
    min-width: 52px;
    height: 52px;
    min-height: 52px;

    border-radius: 14px;
  }

  .chainlab-chat-launcher {
    right: 16px !important;
    bottom: 16px !important;

    width: 128px;
    min-width: 128px;
    height: 52px;

    border-radius: 14px;
  }

  .chainlab-chatbox {
    right: 12px !important;
    bottom: 78px !important;

    width: calc(100vw - 24px);

    height: 500px;
    max-height: calc(100dvh - 100px);

    border-radius: 18px;
  }
}
/* =========================================================
   CHAINLAB VISUAL POLISH — modern palette and utilities
   Kept as overrides so existing page/component selectors remain intact.
========================================================= */
:root {
  --background: #080d16;
  --surface: #0d1522;
  --surface-light: #121e2e;
  --border: #26364b;
  --border-bright: #3b82a8;
  --text: #edf3fb;
  --muted: #a0aec0;
  --cyan: #55d6e8;
  --cyan-dark: #178ba7;
  --orange: #f6b94b;
  --orange-bright: #ffd078;
  --cl-focus: rgba(85, 214, 232, 0.38);
}

html[data-theme="light"] {
  --background: #f5f7fb;
  --surface: #ffffff;
  --surface-light: #edf2f8;
  --border: #d8e1ec;
  --border-bright: #83b8ca;
  --text: #172437;
  --muted: #5d6b7e;
  --cyan: #087f9b;
  --cyan-dark: #08647a;
  --orange: #a96308;
  --orange-bright: #8a5207;
  --cl-focus: rgba(8, 127, 155, 0.24);
  color-scheme: light;
}

html[data-theme="dark"] { color-scheme: dark; }
body { background: var(--background); color: var(--text); }
button, input, textarea, select { font: inherit; }
button:focus-visible, a:focus-visible, input:focus-visible {
  outline: 3px solid var(--cl-focus);
  outline-offset: 3px;
}

/* Fixed utility strip: evenly spaced, centered controls */
.chainlab-utility-bar {
  background: color-mix(in srgb, var(--background) 88%, transparent);
  border-bottom: 1px solid var(--border);
  backdrop-filter: blur(18px);
}
.chainlab-utility-inner {
  width: min(100% - 32px, 1240px);
  margin-inline: auto;
}
.chainlab-toolbar-center {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
}
.chainlab-tools { display: flex; align-items: center; justify-content: center; gap: 10px; }
.chainlab-tool-button,
.chainlab-toolbar-center .chainlab-device-button,
.device-preview-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 44px;
  min-width: 44px;
  height: 44px;
  min-height: 44px;
  border: 1px solid var(--border);
  border-radius: 12px;
  background: var(--surface);
  color: var(--text);
  box-shadow: 0 4px 14px rgba(0,0,0,.08);
  transition: background .18s ease, border-color .18s ease, transform .18s ease;
}
.chainlab-tool-button:hover, .device-preview-button:hover {
  background: var(--surface-light); border-color: var(--border-bright); transform: translateY(-1px);
}
.font-control-wrapper, .device-preview-control { position: relative; }
.font-control-panel, .device-preview-menu {
  border: 1px solid var(--border);
  border-radius: 14px;
  background: var(--surface);
  color: var(--text);
  box-shadow: 0 18px 50px rgba(0,0,0,.22);
  padding: 8px;
}
.font-control-panel button, .device-preview-option {
  border: 1px solid transparent; border-radius: 9px; color: var(--text); background: transparent;
}
.font-control-panel button:hover, .device-preview-option:hover,
.font-control-panel button.active, .device-preview-option-active {
  background: var(--surface-light); border-color: var(--border-bright);
}

/* Chat is viewport-fixed, independent of page/toolbar layout */
.chainlab-chat-launcher {
  position: fixed !important;
  right: max(22px, env(safe-area-inset-right)) !important;
  bottom: max(22px, env(safe-area-inset-bottom)) !important;
  z-index: 10000 !important;
  display: inline-flex; align-items: center; justify-content: center; gap: 9px;
  min-width: 112px; min-height: 48px; padding: 0 18px;
  border: 1px solid var(--border-bright); border-radius: 999px;
  background: var(--text); color: var(--background);
  box-shadow: 0 10px 32px rgba(0,0,0,.24);
  font-weight: 700; letter-spacing: .06em;
}
.chainlab-chat-launcher:hover { transform: translateY(-2px); }
.chainlab-chatbox {
  position: fixed !important;
  right: max(22px, env(safe-area-inset-right)) !important;
  bottom: calc(max(22px, env(safe-area-inset-bottom)) + 62px) !important;
  z-index: 9999 !important;
  width: min(390px, calc(100vw - 28px));
  max-height: min(620px, calc(100dvh - 110px));
  overflow: hidden;
  border: 1px solid var(--border);
  border-radius: 20px;
  background: var(--surface);
  color: var(--text);
  box-shadow: 0 24px 80px rgba(0,0,0,.3);
}
.chainlab-chat-header { border-bottom: 1px solid var(--border); background: var(--surface-light); }
.chainlab-chat-messages { color: var(--text); }
.chainlab-message { border: 1px solid var(--border); border-radius: 14px; }
.chainlab-message.assistant-message { background: var(--surface-light); color: var(--text); }
.chainlab-message.user-message { background: var(--cyan-dark); color: #fff; }
.chainlab-chat-quick button { border: 1px solid var(--border); border-radius: 999px; background: var(--surface-light); color: var(--text); }
.chainlab-chat-input { border-top: 1px solid var(--border); }
.chainlab-chat-input input { background: var(--background); color: var(--text); border: 1px solid var(--border); border-radius: 12px; }

@media (max-width: 600px) {
  .chainlab-utility-inner { width: calc(100% - 20px); }
  .chainlab-toolbar-center, .chainlab-tools { gap: 7px; }
  .chainlab-tool-button, .chainlab-toolbar-center .chainlab-device-button, .device-preview-button {
    width: 42px; min-width: 42px; height: 42px; min-height: 42px; border-radius: 11px;
  }
  .chainlab-chat-launcher { right: 14px !important; bottom: 14px !important; }
  .chainlab-chatbox { right: 12px !important; bottom: 72px !important; width: calc(100vw - 24px); }
}


/* =========================================================
   CHAINLAB LANDING PAGE — UIVERSE / DEXTER-ST BUTTON THEME
   Applied to existing landing-page CTA links without changing
   their hrefs, labels, or behavior.
   ========================================================= */

:root {
  --cl-button-radius: 999px;
  --cl-button-bg: #101010;
  --cl-button-border: rgba(255, 255, 255, 0.22);
  --cl-button-text: #f7f8fa;
  --cl-button-glow: 210deg;
  --cl-button-transition: 0.35s ease;
}

/* Button-shaped links on the landing page */
.site-header .nav-button,
.hero-actions .primary-button,
.hero-actions .secondary-button,
.company-content .company-button,
.about-content .primary-button,
.featured-content .primary-button,
.security-content .secondary-button,
.final-inner .large-button,
.featured-card .featured-button {
  position: relative;
  isolation: isolate;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.65rem;
  min-height: 48px;
  padding: 0.85rem 1.45rem;
  overflow: visible;
  border: 1px solid var(--cl-button-border);
  border-radius: var(--cl-button-radius);
  background: var(--cl-button-bg);
  color: var(--cl-button-text);
  font-family: inherit;
  font-size: 0.88rem;
  font-weight: 600;
  line-height: 1.15;
  letter-spacing: 0.045em;
  text-decoration: none;
  text-transform: uppercase;
  cursor: pointer;
  box-shadow:
    inset 0 1px 1px rgba(255, 255, 255, 0.22),
    inset 0 2px 3px rgba(255, 255, 255, 0.12),
    inset 0 7px 12px rgba(255, 255, 255, 0.035),
    0 -1px 1px rgba(0, 0, 0, 0.08),
    0 5px 12px rgba(0, 0, 0, 0.22),
    0 12px 28px rgba(0, 0, 0, 0.16);
  transition:
    box-shadow var(--cl-button-transition),
    border-color var(--cl-button-transition),
    background-color var(--cl-button-transition),
    color var(--cl-button-transition),
    transform var(--cl-button-transition);
}

/* Outer metallic rim */
.site-header .nav-button::before,
.hero-actions .primary-button::before,
.hero-actions .secondary-button::before,
.company-content .company-button::before,
.about-content .primary-button::before,
.featured-content .primary-button::before,
.security-content .secondary-button::before,
.final-inner .large-button::before,
.featured-card .featured-button::before {
  content: "";
  position: absolute;
  z-index: -1;
  inset: -5px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: inherit;
  background: linear-gradient(145deg, rgba(255,255,255,.13), rgba(0,0,0,.7));
  box-shadow:
    0 1px 1px rgba(255,255,255,.14),
    0 -2px 8px rgba(0,0,0,.45),
    inset 0 1px 2px rgba(255,255,255,.08);
  pointer-events: none;
  transition: box-shadow var(--cl-button-transition), opacity var(--cl-button-transition);
}

/* Soft top-edge reflection */
.site-header .nav-button::after,
.hero-actions .primary-button::after,
.hero-actions .secondary-button::after,
.company-content .company-button::after,
.about-content .primary-button::after,
.featured-content .primary-button::after,
.security-content .secondary-button::after,
.final-inner .large-button::after,
.featured-card .featured-button::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: linear-gradient(
    180deg,
    rgba(255,255,255,.28) 0%,
    rgba(170,210,255,.14) 18%,
    rgba(255,255,255,0) 54%
  );
  opacity: 0;
  pointer-events: none;
  transition: opacity var(--cl-button-transition);
}

/* Keep button content above the shine */
.site-header .nav-button > *,
.hero-actions .primary-button > *,
.hero-actions .secondary-button > *,
.company-content .company-button > *,
.about-content .primary-button > *,
.featured-content .primary-button > *,
.security-content .secondary-button > *,
.final-inner .large-button > *,
.featured-card .featured-button > * {
  position: relative;
  z-index: 1;
}

.site-header .nav-button:hover,
.hero-actions .primary-button:hover,
.hero-actions .secondary-button:hover,
.company-content .company-button:hover,
.about-content .primary-button:hover,
.featured-content .primary-button:hover,
.security-content .secondary-button:hover,
.final-inner .large-button:hover,
.featured-card .featured-button:hover {
  transform: translateY(-1px);
  border-color: rgba(190, 222, 255, 0.72);
  background: #15191e;
  color: #fff;
  box-shadow:
    inset 0 1px 1px rgba(255,255,255,.32),
    inset 0 5px 12px rgba(255,255,255,.07),
    0 0 0 1px rgba(160,205,255,.08),
    0 0 20px rgba(126,184,255,.14),
    0 9px 22px rgba(0,0,0,.3);
}

.site-header .nav-button:hover::after,
.hero-actions .primary-button:hover::after,
.hero-actions .secondary-button:hover::after,
.company-content .company-button:hover::after,
.about-content .primary-button:hover::after,
.featured-content .primary-button:hover::after,
.security-content .secondary-button:hover::after,
.final-inner .large-button:hover::after,
.featured-card .featured-button:hover::after {
  opacity: 0.9;
}

.site-header .nav-button:hover::before,
.hero-actions .primary-button:hover::before,
.hero-actions .secondary-button:hover::before,
.company-content .company-button:hover::before,
.about-content .primary-button:hover::before,
.featured-content .primary-button:hover::before,
.security-content .secondary-button:hover::before,
.final-inner .large-button:hover::before,
.featured-card .featured-button:hover::before {
  box-shadow:
    0 1px 2px rgba(255,255,255,.2),
    0 -2px 10px rgba(0,0,0,.48),
    inset 0 1px 3px rgba(255,255,255,.16),
    0 0 14px rgba(125,190,255,.12);
}

.site-header .nav-button:active,
.hero-actions .primary-button:active,
.hero-actions .secondary-button:active,
.company-content .company-button:active,
.about-content .primary-button:active,
.featured-content .primary-button:active,
.security-content .secondary-button:active,
.final-inner .large-button:active,
.featured-card .featured-button:active {
  transform: translateY(1px) scale(0.985);
  background: #080a0d;
  border-color: rgba(205, 230, 255, 0.82);
  box-shadow:
    inset 0 2px 8px rgba(0,0,0,.72),
    inset 0 1px 2px rgba(255,255,255,.15),
    0 0 0 1px rgba(150,200,255,.12);
}

.site-header .nav-button:focus-visible,
.hero-actions .primary-button:focus-visible,
.hero-actions .secondary-button:focus-visible,
.company-content .company-button:focus-visible,
.about-content .primary-button:focus-visible,
.featured-content .primary-button:focus-visible,
.security-content .secondary-button:focus-visible,
.final-inner .large-button:focus-visible,
.featured-card .featured-button:focus-visible {
  outline: 2px solid #a9d6ff;
  outline-offset: 5px;
}

/* Arrow/icon details */
.site-header .nav-button span,
.hero-actions .primary-button span,
.company-content .company-button span,
.about-content .primary-button span,
.featured-content .primary-button span,
