/* =========================================
   CHAINLAB CHATBOX — ANIMATED CARD DESIGN
   Inspired by Uiverse.io by ElSombrero2
   ========================================= */

.chainlab-chatbox {
  position: fixed !important;

  right: 28px !important;
  bottom: 105px !important;

  width: 360px !important;
  max-width: calc(100vw - 32px) !important;

  height: 480px !important;
  max-height: calc(100dvh - 140px) !important;

  z-index: 10009 !important;

  display: flex !important;
  flex-direction: column !important;

  overflow: hidden !important;

  background: #151515 !important;
  color: #ffffff !important;

  border: 1px solid rgba(255, 153, 102, 0.35) !important;
  border-radius: 8px !important;

  box-shadow:
    0 0 10px 1px #000000ee,
    0 0 25px rgba(255, 153, 102, 0.08);

  isolation: isolate;

  animation: chainlab-chat-appear 300ms ease-out;
}

/* Animated orange border */

.chainlab-chatbox::before {
  content: "";

  position: absolute;
  inset: -50%;

  width: 200%;
  height: 200%;

  background: linear-gradient(
    90deg,
    transparent,
    #ff9966,
    #ff9966,
    #ff9966,
    transparent
  );

  animation: chainlab-chat-border 5s linear infinite;

  z-index: -2;

  pointer-events: none;
}

/* Dark inner surface */

.chainlab-chatbox::after {
  content: "";

  position: absolute;
  inset: 2px;

  background: #151515;

  border-radius: 6px;

  z-index: -1;

  pointer-events: none;
}

/* =========================================
   CHAT HEADER
   ========================================= */

.chainlab-chat-header {
  position: relative;

  display: flex;
  align-items: center;
  justify-content: space-between;

  padding: 20px;

  background: #151515;

  border-bottom: 1px solid rgba(255, 153, 102, 0.2);

  flex-shrink: 0;
}

.chainlab-chat-label {
  display: block;

  margin-bottom: 6px;

  color: #ff9966;

  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.12em;
}

.chainlab-chat-header h2 {
  margin: 0;

  color: #ffffff;

  font-size: 20px;
  font-weight: 700;
}

/* Close button */

.chainlab-chat-close {
  display: flex;
  align-items: center;
  justify-content: center;

  width: 34px;
  height: 34px;

  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: 50%;

  background: #202020;

  color: #ffffff;

  font-size: 23px;

  cursor: pointer;

  transition:
    background 200ms ease,
    border-color 200ms ease;
}

.chainlab-chat-close:hover {
  background: #303030;
  border-color: #ff9966;
}

/* =========================================
   CHAT MESSAGES
   ========================================= */

.chainlab-chat-messages {
  position: relative;

  display: flex;
  flex-direction: column;
  gap: 14px;

  flex: 1;

  min-height: 0;

  padding: 20px;

  overflow-y: auto;

  background: #151515;

  scrollbar-width: thin;
  scrollbar-color: #454545 #151515;
}

/* Individual message bubbles */

.chainlab-message {
  max-width: 90%;

  padding: 12px 14px;

  border-radius: 6px;

  font-size: 14px;
  line-height: 1.6;

  overflow-wrap: anywhere;
}

/* ChainLab assistant messages */

.assistant-message {
  align-self: flex-start;

  background: #222222;

  border: 1px solid rgba(255, 255, 255, 0.08);

  color: #eeeeee;
}

/* User messages */

.user-message {
  align-self: flex-end;

  background: rgba(255, 153, 102, 0.12);

  border: 1px solid rgba(255, 153, 102, 0.4);

  color: #ffffff;
}

/* =========================================
   QUICK QUESTIONS
   ========================================= */

.chainlab-chat-quick {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;

  padding: 12px 16px;

  background: #151515;

  border-top: 1px solid rgba(255, 255, 255, 0.07);
}

.chainlab-chat-quick button {
  padding: 8px 11px;

  border: 1px solid rgba(255, 153, 102, 0.35);
  border-radius: 5px;

  background: #202020;

  color: #eeeeee;

  font-size: 11px;

  cursor: pointer;

  transition:
    background 200ms ease,
    border-color 200ms ease;
}

.chainlab-chat-quick button:hover {
  background: #292929;
  border-color: #ff9966;
}

/* =========================================
   CHAT INPUT
   ========================================= */

.chainlab-chat-input {
  display: flex;
  align-items: center;
  gap: 10px;

  padding: 14px 16px;

  background: #151515;

  border-top: 1px solid rgba(255, 255, 255, 0.1);

  flex-shrink: 0;
}

.chainlab-chat-input input {
  flex: 1;

  min-width: 0;

  padding: 12px 14px;

  border: 1px solid #353535;
  border-radius: 5px;

  outline: none;

  background: #202020;

  color: #ffffff;

  font-family: inherit;
  font-size: 13px;

  transition: border-color 200ms ease;
}

.chainlab-chat-input input::placeholder {
  color: #888888;
}

.chainlab-chat-input input:focus {
  border-color: #ff9966;
}

/* Send button */

.chainlab-chat-input button {
  display: flex;
  align-items: center;
  justify-content: center;

  width: 44px;
  height: 44px;

  border: 1px solid rgba(255, 153, 102, 0.7);
  border-radius: 5px;

  background: #ff9966;

  color: #151515;

  font-size: 24px;
  font-weight: 700;

  cursor: pointer;

  transition:
    background 200ms ease,
    transform 200ms ease;
}

.chainlab-chat-input button:hover {
  background: #ffb38c;
  transform: translateY(-2px);
}

/* =========================================
   ANIMATIONS
   ========================================= */

@keyframes chainlab-chat-border {
  0% {
    transform: rotate(0deg);
  }

  100% {
    transform: rotate(360deg);
  }
