  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 20px;
  padding: 17px 24px;
  border: 1px solid var(--achievement-accent, #b7ff3c);
  border-radius: 8px;
  color: #101500;
  background: var(--achievement-accent, #b7ff3c);
