/* =========================================================
   CHAINLAB LOGIN — REFERENCE STYLE
   CSS-only visual background: no image assets required.
   ========================================================= */

.auth-reference-page {
  --auth-bg: #020811;
  --auth-panel: rgba(5, 15, 27, 0.92);
  --auth-border: rgba(31, 156, 255, 0.52);
  --auth-text: #f7fbff;
  --auth-muted: #91a1b5;
  --auth-blue: #168cff;
  --auth-cyan: #00d8ff;

  position: relative !important;
  min-height: 100vh !important;
  overflow: hidden !important;
  isolation: isolate !important;
  background:
    radial-gradient(circle at 50% 115%, rgba(0, 126, 255, 0.32), transparent 32%),
    radial-gradient(circle at 10% 20%, rgba(0, 130, 255, 0.10), transparent 28%),
    radial-gradient(circle at 90% 20%, rgba(0, 210, 255, 0.07), transparent 25%),
    linear-gradient(180deg, #020711 0%, #030b16 55%, #02060d 100%) !important;
  color: var(--auth-text) !important;
}

.auth-reference-container {
  position: relative;
  z-index: 10;
  width: min(100%, 760px);
  min-height: 100vh;
  margin: 0 auto;
  padding: 30px 24px 46px;
}

.auth-reference-header {
  display: flex;
  justify-content: center;
  align-items: center;
  margin-bottom: 44px;
}

.auth-reference-brand {
  color: #f7fbff !important;
  text-decoration: none !important;
  font-size: 2rem;
  line-height: 1;
  font-weight: 800;
  letter-spacing: -0.055em;
  text-shadow: 0 0 24px rgba(0, 157, 255, 0.15);
}

.auth-reference-brand span {
  color: var(--auth-blue);
}

.auth-reference-content {
  width: min(100%, 560px);
  margin: 0 auto;
}

.auth-reference-intro {
  text-align: center;
  margin-bottom: 28px;
}

.auth-reference-intro .auth-eyebrow {
  margin-bottom: 10px;
  color: var(--auth-cyan);
  font-size: 0.62rem;
  font-weight: 800;
  letter-spacing: 0.34em;
  text-transform: uppercase;
}

.auth-reference-intro h1 {
  margin: 0;
  color: #fff !important;
  font-size: clamp(3.4rem, 8vw, 5.2rem);
  line-height: 0.92;
  letter-spacing: -0.075em;
  font-weight: 900;
}

.auth-reference-intro h1 span {
  color: var(--auth-blue);
}

.auth-reference-intro p {
  margin: 17px auto 0;
  max-width: 430px;
  color: var(--auth-muted);
  font-size: 0.95rem;
  line-height: 1.5;
}

.auth-reference-card {
  width: 100%;
  margin: 0 auto;
  padding: 28px 26px 24px !important;
  border: 1px solid var(--auth-border) !important;
  border-radius: 18px !important;
  background: linear-gradient(
    180deg,
    rgba(4, 16, 30, 0.96),
    rgba(2, 9, 18, 0.94)
  ) !important;
  box-shadow:
    0 0 0 1px rgba(0, 178, 255, 0.06),
    0 0 38px rgba(0, 132, 255, 0.20),
    0 28px 80px rgba(0, 0, 0, 0.46) !important;
  backdrop-filter: blur(16px);
}

.auth-reference-card .auth-form {
  gap: 15px;
}

.auth-reference-card .auth-field > span {
  display: block;
  margin-bottom: 7px;
  color: #dfeaf5;
  font-size: 0.72rem;
  font-weight: 700;
}

.auth-reference-card .auth-input-wrapper {
  min-height: 48px;
  border: 1px solid rgba(121, 151, 180, 0.38) !important;
  border-radius: 7px !important;
  background: rgba(2, 10, 19, 0.72) !important;
  transition: border-color 160ms ease, box-shadow 160ms ease;
}

.auth-reference-card .auth-input-wrapper:focus-within {
  border-color: rgba(0, 184, 255, 0.82) !important;
  box-shadow: 0 0 0 3px rgba(0, 156, 255, 0.09);
}

.auth-reference-card .auth-input-icon {
  color: #a7b9ca !important;
}

.auth-reference-card input {
  color: #f5faff !important;
  background: transparent !important;
}

.auth-reference-card input::placeholder {
  color: #6d7d8e !important;
}

.auth-reference-card .auth-options {
  margin-top: 1px;
}

.auth-reference-card .remember-me {
  color: #d2deea !important;
  font-size: 0.68rem;
}

.auth-reference-card .custom-checkbox {
  border-radius: 3px !important;
}

.auth-reference-card .remember-me input:checked + .custom-checkbox {
  background: var(--auth-blue) !important;
  border-color: var(--auth-blue) !important;
}

.auth-reference-card .forgot-password,
.auth-reference-card .auth-switch a,
.auth-reference-card .auth-back {
  color: var(--auth-blue) !important;
}

.auth-reference-card .auth-primary-button {
  min-height: 47px;
  margin-top: 2px;
  border: 0 !important;
  border-radius: 7px !important;
  background: linear-gradient(90deg, #05d8ef 0%, #168cff 100%) !important;
  color: #02101b !important;
  font-weight: 850 !important;
  box-shadow: 0 0 25px rgba(0, 167, 255, 0.24);
}

.auth-reference-card .auth-primary-button:hover:not(:disabled) {
  transform: translateY(-1px);
  box-shadow: 0 0 34px rgba(0, 167, 255, 0.36);
}

.auth-reference-card .auth-divider {
  color: #718194 !important;
}

.auth-reference-card .auth-divider::before,
.auth-reference-card .auth-divider::after {
  background: rgba(126, 148, 169, 0.28) !important;
}

.auth-reference-card .auth-social-buttons {
  display: grid;
  gap: 8px;
}

.auth-reference-card .auth-social-button {
  min-height: 40px;
  border: 1px solid rgba(121, 151, 180, 0.34) !important;
  border-radius: 6px !important;
  background: rgba(4, 13, 23, 0.62) !important;
  color: #dce7f1 !important;
  font-size: 0.69rem;
}

.auth-reference-card .auth-social-button:hover {
  border-color: rgba(0, 165, 255, 0.62) !important;
  background: rgba(9, 30, 50, 0.82) !important;
}

.auth-reference-card .auth-switch {
  margin: 19px 0 0 !important;
  color: #8595a7 !important;
  font-size: 0.68rem;
}

.auth-reference-card .auth-back {
  display: block;
  margin-top: 16px;
  padding-top: 15px;
  border-top: 1px solid rgba(126, 148, 169, 0.18);
  text-align: center;
  font-size: 0.7rem;
  text-decoration: none;
}

/* CSS-only orbital/glow background. No image. */
.auth-orbit {
  position: absolute;
  z-index: 1;
  left: 50%;
  top: 58%;
  width: min(1100px, 130vw);
  height: min(430px, 52vw);
  transform: translate(-50%, -50%) rotate(-8deg);
  border: 1px solid rgba(0, 160, 255, 0.34);
  border-radius: 50%;
  box-shadow:
    0 0 14px rgba(0, 158, 255, 0.30),
    inset 0 0 20px rgba(0, 158, 255, 0.05);
  pointer-events: none;
}

.auth-orbit::after {
  content: "";
  position: absolute;
  left: 14%;
  top: 42%;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #13cfff;
  box-shadow:
    0 0 10px #13cfff,
    0 0 24px rgba(19, 207, 255, 0.85);
}

.auth-orbit-one {
  opacity: 0.9;
}

.auth-orbit-two {
  top: 64%;
  width: min(1200px, 145vw);
  height: min(500px, 60vw);
  transform: translate(-50%, -50%) rotate(18deg);
  opacity: 0.42;
}

.auth-orbit-two::after {
  left: auto;
  right: 18%;
  top: 50%;
  width: 5px;
  height: 5px;
}

.auth-horizon {
  position: absolute;
  z-index: 2;
  left: 50%;
  bottom: -280px;
  width: min(1150px, 145vw);
  height: 470px;
  transform: translateX(-50%);
  border-radius: 50% 50% 0 0;
  background:
    radial-gradient(
      ellipse at 50% 0%,
      rgba(0, 211, 255, 0.34),
      rgba(0, 109, 255, 0.18) 28%,
      transparent 64%
    );
  filter: blur(12px);
  pointer-events: none;
}

.auth-background-grid,
.auth-glow,
.auth-network,
.auth-benefits,
.auth-topbar,
.auth-hero,
.auth-card-header {
  display: none !important;
