}

.learnHeroInner {
  max-width: 700px;
}

.learnEyebrow {
  color: #00c8ff;
  font-size: calc((11px) * var(--cl-font-scale, 1));
  font-weight: 900;
  letter-spacing: 2px;
  margin-bottom: 30px;
}

.learnHero h1 {
  margin: 0;
  font-size: calc((clamp(70px, 9vw, 145px)) * var(--cl-font-scale, 1));
