}

.orbitLarge {
  width: 480px;
  height: 480px;
}

.orbitMedium {
  width: 340px;
  height: 340px;
}

.orbitSmall {
  width: 205px;
  height: 205px;
}

.learnCore {
  width: 155px;
  height: 155px;
  border: 1px solid #00c8ff;
  border-radius: 50%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  background: rgba(3, 12, 20, 0.95);
