}

.learnCore span {
  color: #00c8ff;
  font-size: calc((9px) * var(--cl-font-scale, 1));
  font-weight: 900;
  letter-spacing: 2px;
}

.learnCore strong {
  margin-top: 8px;
  font-size: calc((32px) * var(--cl-font-scale, 1));
  font-weight: 900;
}

.learnCore small {
  color: #ffad00;
  font-size: calc((8px) * var(--cl-font-scale, 1));
  font-weight: 900;
  letter-spacing: 2px;
  margin-top: 4px;
}

.learnNode {
  position: absolute;
  min-width: 135px;
  padding: 15px;
  border: 1px solid rgba(0, 200, 255, 0.55);
  background: rgba(3, 12, 20, 0.92);
  color: #00c8ff;
  font-size: calc((9px) * var(--cl-font-scale, 1));
  font-weight: 900;
  letter-spacing: 0.8px;
  text-align: center;
  box-shadow: 0 0 25px rgba(0, 200, 255, 0.08);
  z-index: 5;
}

.learnNode span {
  display: block;
  color: #ffad00;
  font-size: calc((10px) * var(--cl-font-scale, 1));
  margin-bottom: 7px;
}

.nodeOne {
  top: 25px;
  left: 4%;
}

.nodeTwo {
  top: 115px;
  right: 0;
}

.nodeThree {
  bottom: 80px;
  left: 0;
}

.nodeFour {
  bottom: 20px;
  right: 8%;
}

.learningPath {
  padding: 120px 6%;
}

.learnSectionHeader {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 80px;
  align-items: end;
  margin-bottom: 65px;
}

.learnSectionHeader h2 {
  margin: 0;
  font-size: calc((clamp(48px, 6vw, 90px)) * var(--cl-font-scale, 1));
  line-height: 0.9;
  letter-spacing: -4px;
  font-weight: 900;
}

.learnSectionHeader h2 span {
  color: #ffad00;
}

.learnSectionHeader > p {
  max-width: 550px;
  color: #8194a9;
  line-height: 1.8;
  font-size: calc((15px) * var(--cl-font-scale, 1));
}

.learningModule {
  display: grid;
  grid-template-columns: 100px 1fr 190px;
  gap: 35px;
  align-items: center;
  min-height: 230px;
  padding: 35px 40px;
  margin-bottom: 14px;
  border: 1px solid rgba(0, 200, 255, 0.16);
  background: rgba(3, 10, 17, 0.7);
  transition: 0.3s ease;
}

.learningModule:hover {
  border-color: rgba(0, 200, 255, 0.6);
  transform: translateX(8px);
  background: rgba(0, 200, 255, 0.035);
}

.featuredModule {
  border-color: rgba(255, 173, 0, 0.4);
}

.featuredModule:hover {
  border-color: #ffad00;
}

.moduleNumber {
  color: #00c8ff;
  font-size: calc((40px) * var(--cl-font-scale, 1));
  font-weight: 900;
  letter-spacing: -2px;
}

.moduleLabel {
  color: #00c8ff;
  font-size: calc((9px) * var(--cl-font-scale, 1));
  font-weight: 900;
  letter-spacing: 2px;
  margin-bottom: 10px;
}

.moduleMain h3 {
  margin: 0;
  font-size: calc((34px) * var(--cl-font-scale, 1));
  font-weight: 900;
  letter-spacing: -1px;
}

.moduleMain p {
  max-width: 720px;
  color: #8497aa;
  line-height: 1.7;
  font-size: calc((14px) * var(--cl-font-scale, 1));
  margin: 14px 0 20px;
}

.moduleTopics {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.moduleTopics span {
  padding: 7px 10px;
  border: 1px solid rgba(0, 200, 255, 0.15);
  color: #718599;
  font-size: calc((8px) * var(--cl-font-scale, 1));
  font-weight: 900;
  letter-spacing: 0.7px;
}

.moduleAction {
  display: flex;
  justify-content: flex-end;
  align-items: center;
  gap: 18px;
  color: #00c8ff;
  font-size: calc((9px) * var(--cl-font-scale, 1));
  font-weight: 900;
  letter-spacing: 1px;
}

.moduleAction strong {
  font-size: calc((22px) * var(--cl-font-scale, 1));
}

.securityModule {
  border-color: rgba(0, 200, 255, 0.3);
}

.comingModule {
  opacity: 0.65;
  cursor: default;
}

.comingModule .moduleAction {
  color: #ffad00;
}

.learnProcess {
  padding: 120px 6%;
  border-top: 1px solid rgba(0, 200, 255, 0.12);
  border-bottom: 1px solid rgba(0, 200, 255, 0.12);
}

.processCards {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  border: 1px solid rgba(0, 200, 255, 0.15);
}

.processCard {
  min-height: 260px;
  padding: 32px;
  border-right: 1px solid rgba(0, 200, 255, 0.15);
}

.processCard:last-child {
  border-right: 0;
}

.processNumber {
  width: 48px;
  height: 48px;
  border: 1px solid #00c8ff;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #00c8ff;
  font-size: calc((13px) * var(--cl-font-scale, 1));
  font-weight: 900;
  margin-bottom: 60px;
}

.processCard h3 {
  font-size: calc((15px) * var(--cl-font-scale, 1));
  margin: 0 0 12px;
}

.processCard p {
  color: #778a9e;
  line-height: 1.7;
  font-size: calc((13px) * var(--cl-font-scale, 1));
}

.principlesSection {
  padding: 130px 6%;
  display: grid;
  grid-template-columns: 0.9fr 1.1fr;
  gap: 100px;
}

.principlesIntro h2 {
  margin: 0;
  font-size: calc((clamp(48px, 6vw, 82px)) * var(--cl-font-scale, 1));
  line-height: 0.92;
  letter-spacing: -4px;
}

.principlesIntro h2 span {
  color: #ffad00;
}

.principlesIntro p {
  max-width: 500px;
  margin-top: 35px;
  color: #8497aa;
  font-size: calc((15px) * var(--cl-font-scale, 1));
  line-height: 1.8;
}

.principlesList {
  border-top: 1px solid rgba(0, 200, 255, 0.18);
}

.principle {
  display: grid;
  grid-template-columns: 65px 1fr;
  gap: 20px;
  padding: 30px 0;
  border-bottom: 1px solid rgba(0, 200, 255, 0.15);
}

.principle > span {
  color: #00c8ff;
  font-size: calc((11px) * var(--cl-font-scale, 1));
  font-weight: 900;
}

.principle h3 {
  margin: 0 0 10px;
  font-size: calc((14px) * var(--cl-font-scale, 1));
}

.principle p {
  margin: 0;
  color: #778a9e;
  line-height: 1.7;
  font-size: calc((13px) * var(--cl-font-scale, 1));
}

.learnFinal {
  position: relative;
  min-height: 520px;
  padding: 100px 6%;
  overflow: hidden;
  border-top: 1px solid rgba(0, 200, 255, 0.15);
  background:
    radial-gradient(
      circle at 70% 50%,
      rgba(0, 145, 255, 0.13),
      transparent 35%
    ),
    #02060b;
}

.learnFinalInner {
  position: relative;
  z-index: 3;
  max-width: 720px;
}

.learnFinal h2 {
  margin: 0;
  font-size: calc((clamp(60px, 8vw, 120px)) * var(--cl-font-scale, 1));
  line-height: 0.85;
  letter-spacing: -6px;
}

.learnFinal h2 span {
  color: #ffad00;
}

.learnFinal p {
  max-width: 600px;
  margin: 35px 0;
  color: #8497aa;
  line-height: 1.8;
  font-size: calc((15px) * var(--cl-font-scale, 1));
}

.learnStartButton {
  display: inline-flex;
  gap: 25px;
  align-items: center;
  padding: 18px 25px;
  background: #ffad00;
  color: #050505;
  font-size: calc((11px) * var(--cl-font-scale, 1));
  font-weight: 900;
  transition: 0.25s ease;
}

.learnStartButton:hover {
  transform: translateY(-3px);
  box-shadow: 0 15px 35px rgba(255, 173, 0, 0.2);
}

.learnStartButton span {
  font-size: calc((20px) * var(--cl-font-scale, 1));
}

.finalGrid {
  position: absolute;
  right: 5%;
  top: 50%;
  width: 500px;
  height: 500px;
  transform: translateY(-50%);
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
  opacity: 0.5;
}

.finalGrid span {
  border: 1px solid rgba(0, 200, 255, 0.2);
  background: rgba(0, 200, 255, 0.015);
}

.learnFooter {
  padding: 75px 6% 30px;
  background: #010409;
  border-top: 1px solid rgba(0, 200, 255, 0.15);
}

.learnFooterTop {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 60px;
  padding-bottom: 60px;
}

.learnFooterBrand strong {
  font-size: calc((20px) * var(--cl-font-scale, 1));
  font-weight: 900;
}

.learnFooterBrand p,
.learnFooterColumn p {
  color: #687c91;
  font-size: calc((12px) * var(--cl-font-scale, 1));
  line-height: 1.8;
}

.learnFooterColumn {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.learnFooterColumn h4 {
  color: #00c8ff;
  font-size: calc((9px) * var(--cl-font-scale, 1));
  letter-spacing: 1.5px;
  margin: 0 0 8px;
}

.learnFooterColumn a {
  color: #8799ab;
  font-size: calc((11px) * var(--cl-font-scale, 1));
}

.learnFooterColumn a:hover {
  color: white;
}

.learnFooterBottom {
  display: flex;
  justify-content: space-between;
  gap: 30px;
  padding-top: 25px;
  border-top: 1px solid rgba(0, 200, 255, 0.1);
  color: #506276;
  font-size: calc((8px) * var(--cl-font-scale, 1));
  font-weight: 800;
  letter-spacing: 0.7px;
}

/* =========================================================
   LEARNING RESPONSIVE
========================================================= */

@media (max-width: 1000px) {
  .learnNavLinks {
    display: none;
  }

  .learnHero {
    grid-template-columns: 1fr;
  }

  .learnHeroVisual {
    height: 480px;
  }

  .learnSectionHeader {
    grid-template-columns: 1fr;
    gap: 30px;
  }

  .learningModule {
    grid-template-columns: 70px 1fr;
  }

  .moduleAction {
    grid-column: 2;
    justify-content: flex-start;
  }

  .processCards {
    grid-template-columns: repeat(2, 1fr);
  }

  .processCard:nth-child(2) {
    border-right: 0;
  }

  .processCard:nth-child(1),
  .processCard:nth-child(2) {
    border-bottom: 1px solid rgba(0, 200, 255, 0.15);
  }

  .principlesSection {
    grid-template-columns: 1fr;
    gap: 60px;
  }

  .learnFooterTop {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 650px) {
  .learnNav {
    padding: 0 20px;
  }

  .learnNavStatus {
    display: none;
  }

  .learnHero {
    padding: 70px 25px;
  }

  .learnHero h1 {
    font-size: calc((70px) * var(--cl-font-scale, 1));
    letter-spacing: -4px;
  }

  .learnHeroMeta {
    flex-direction: column;
  }

  .learnHeroMeta div {
    border-right: 0;
    border-bottom: 1px solid rgba(0, 200, 255, 0.15);
  }

  .learnHeroVisual {
    transform: scale(0.75);
    margin: -50px;
  }

  .learningPath,
  .learnProcess,
  .principlesSection {
    padding: 80px 25px;
  }

  .learningModule {
    grid-template-columns: 1fr;
    gap: 20px;
    padding: 30px 25px;
  }

  .moduleAction {
    grid-column: auto;
  }

  .processCards {
    grid-template-columns: 1fr;
  }

  .processCard {
    border-right: 0;
    border-bottom: 1px solid rgba(0, 200, 255, 0.15);
  }

  .processCard:last-child {
    border-bottom: 0;
  }

  .learnFinal {
    padding: 80px 25px;
  }

  .learnFinal h2 {
    font-size: calc((65px) * var(--cl-font-scale, 1));
    letter-spacing: -4px;
  }

  .finalGrid {
    width: 300px;
    height: 300px;
    right: -100px;
    opacity: 0.25;
  }

  .learnFooter {
    padding-left: 25px;
    padding-right: 25px;
  }

  .learnFooterTop {
    grid-template-columns: 1fr;
    gap: 40px;
  }

  .learnFooterBottom {
    flex-direction: column;
  }
}

/* =========================================================
   ABOUT VALUES — PROFESSIONAL ICONS
========================================================= */

.about-values .feature-icon {
  width: 52px;
  height: 52px;
  margin-bottom: 28px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1px solid rgba(0, 200, 255, 0.35);
  color: #00c8ff;
  background: rgba(0, 200, 255, 0.035);
  box-shadow:
    0 0 25px rgba(0, 200, 255, 0.07),
    inset 0 0 20px rgba(0, 200, 255, 0.025);
  transition:
    border-color 0.25s ease,
    background 0.25s ease,
    box-shadow 0.25s ease,
    transform 0.25s ease;
}

.about-values > div:hover .feature-icon {
  border-color: rgba(0, 200, 255, 0.8);
  background: rgba(0, 200, 255, 0.08);
  box-shadow:
    0 0 30px rgba(0, 200, 255, 0.16),
    inset 0 0 25px rgba(0, 200, 255, 0.04);
  transform: translateY(-3px);
}

.about-values .feature-icon svg {
  display: block;
  width: 29px;
  height: 29px;
}

.about-values > div > span {
  display: block;
  margin-bottom: 14px;
}

.about-values h3 {
  margin-top: 0;
}

/* =========================================================
   CHAINLAB — LEARNING PATH IMAGE CARDS
   LANDING PAGE ONLY
========================================================= */

.paths-section {
  width: min(1320px, calc(100% - 60px));
  margin: 0 auto;
  padding: 150px 0 170px;
}

.paths-section .section-heading-row {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 50px;
  margin-bottom: 70px;
}

.paths-section .section-label {
  margin-bottom: 28px;
}

.paths-section h2 {
  margin: 0;
  color: #ffffff;
  font-size: calc((clamp(58px, 7vw, 108px)) * var(--cl-font-scale, 1));
  font-weight: 900;
  line-height: 0.9;
  letter-spacing: -0.06em;
}

.paths-section h2 span {
  color: #ffb000;
}

.paths-section .text-link {
  flex-shrink: 0;
  color: #ffb000;
  text-decoration: none;
  font-size: calc((13px) * var(--cl-font-scale, 1));
  font-weight: 900;
  letter-spacing: 0.04em;
  white-space: nowrap;
  transition:
    color 180ms ease,
    transform 180ms ease;
}

.paths-section .text-link:hover {
  color: #ffffff;
  transform: translateX(4px);
}


/* =========================================================
   FIVE LEARNING CARDS
========================================================= */

.paths-section .paths-grid {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 14px;
}


/* =========================================================
   CARD
========================================================= */

.paths-section .path-card {
  position: relative;

  min-width: 0;
  min-height: 560px;

  padding: 16px;

  display: flex;
  flex-direction: column;

  color: #ffffff;
  text-decoration: none;

  background:
    linear-gradient(
      180deg,
      #06121c 0%,
      #020a11 100%
    );

  border: 1px solid
    rgba(0, 191, 255, 0.25);

  overflow: hidden;

  transition:
    transform 220ms ease,
    border-color 220ms ease,
    box-shadow 220ms ease;
}

.paths-section .path-card:hover {
  transform: translateY(-7px);

  border-color:
    rgba(0, 191, 255, 0.75);

  box-shadow:
    0 25px 70px
    rgba(0, 170, 255, 0.14);
}


/* =========================================================
   4K IMAGE
========================================================= */

.paths-section .path-visual {
  position: relative;

  width: 100%;
  aspect-ratio: 1 / 1;

  margin-bottom: 28px;

  overflow: hidden;

  background: #02070c;

  border: 1px solid
    rgba(0, 191, 255, 0.24);
}

.paths-section .path-visual::after {
  content: "";

  position: absolute;
  inset: 0;

  pointer-events: none;

  background:
    linear-gradient(
      180deg,
      rgba(0, 0, 0, 0) 55%,
      rgba(0, 0, 0, 0.3) 100%
    );
}

.paths-section .path-visual img {
  display: block;

  width: 100%;
  height: 100%;

  object-fit: cover;
  object-position: center;

  image-rendering: auto;

  transition:
    transform 500ms
    cubic-bezier(0.2, 0.7, 0.2, 1);
}

.paths-section .path-card:hover
.path-visual img {
  transform: scale(1.055);
}


/* =========================================================
   NUMBER
========================================================= */

.paths-section .path-number {
  margin-bottom: 12px;

  color: #00bfff;

  font-size: calc((12px) * var(--cl-font-scale, 1));
  font-weight: 900;

  letter-spacing: 0.08em;
}


/* =========================================================
   TITLE
========================================================= */

.paths-section .path-card h3 {
  margin: 0 0 14px;

  color: #ffffff;

  font-size: calc((20px) * var(--cl-font-scale, 1));
  font-weight: 900;

  line-height: 1;

  letter-spacing: -0.02em;
}


/* =========================================================
   DESCRIPTION
========================================================= */

.paths-section .path-card p {
  margin: 0;

  color: rgba(255, 255, 255, 0.72);

  font-size: calc((13px) * var(--cl-font-scale, 1));
  line-height: 1.65;
}


/* =========================================================
   ACTION
========================================================= */

.paths-section .path-card strong {
  margin-top: auto;
  padding-top: 30px;

  color: #ffb000;

  font-size: calc((11px) * var(--cl-font-scale, 1));
  font-weight: 900;

  letter-spacing: 0.05em;
}


/* =========================================================
   TABLET
========================================================= */

@media (max-width: 1150px) {
  .paths-section {
    width: calc(100% - 48px);
  }

  .paths-section .paths-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .paths-section .path-card {
    min-height: 540px;
  }
}


/* =========================================================
   MOBILE
========================================================= */

@media (max-width: 850px) {
  .paths-section {
    width: calc(100% - 30px);
    padding-top: 100px;
    padding-bottom: 110px;
  }

  .paths-section .section-heading-row {
    display: block;
    margin-bottom: 50px;
  }

  .paths-section .text-link {
    display: inline-block;
    margin-top: 28px;
  }

  .paths-section h2 {
    font-size: calc((clamp(50px, 11vw, 82px)) * var(--cl-font-scale, 1));
  }

  .paths-section .paths-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}


/* =========================================================
   SMALL MOBILE
========================================================= */

@media (max-width: 560px) {
  .paths-section {
    width: calc(100% - 30px);
