/* =========================================================
   CHAINLAB VISUAL POLISH — modern palette and utilities
   Kept as overrides so existing page/component selectors remain intact.
========================================================= */
:root {
  --background: #080d16;
  --surface: #0d1522;
  --surface-light: #121e2e;
  --border: #26364b;
  --border-bright: #3b82a8;
  --text: #edf3fb;
  --muted: #a0aec0;
  --cyan: #55d6e8;
  --cyan-dark: #178ba7;
  --orange: #f6b94b;
  --orange-bright: #ffd078;
  --cl-focus: rgba(85, 214, 232, 0.38);
}

html[data-theme="light"] {
  --background: #f5f7fb;
  --surface: #ffffff;
  --surface-light: #edf2f8;
  --border: #d8e1ec;
  --border-bright: #83b8ca;
  --text: #172437;
  --muted: #5d6b7e;
  --cyan: #087f9b;
  --cyan-dark: #08647a;
  --orange: #a96308;
  --orange-bright: #8a5207;
  --cl-focus: rgba(8, 127, 155, 0.24);
  color-scheme: light;
}

html[data-theme="dark"] { color-scheme: dark; }
body { background: var(--background); color: var(--text); }
button, input, textarea, select { font: inherit; }
button:focus-visible, a:focus-visible, input:focus-visible {
  outline: 3px solid var(--cl-focus);
  outline-offset: 3px;
}

/* Fixed utility strip: evenly spaced, centered controls */
.chainlab-utility-bar {
  background: color-mix(in srgb, var(--background) 88%, transparent);
  border-bottom: 1px solid var(--border);
  backdrop-filter: blur(18px);
}
.chainlab-utility-inner {
  width: min(100% - 32px, 1240px);
  margin-inline: auto;
}
.chainlab-toolbar-center {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
}
.chainlab-tools { display: flex; align-items: center; justify-content: center; gap: 10px; }
.chainlab-tool-button,
.chainlab-toolbar-center .chainlab-device-button,
.device-preview-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 44px;
  min-width: 44px;
  height: 44px;
  min-height: 44px;
  border: 1px solid var(--border);
  border-radius: 12px;
  background: var(--surface);
  color: var(--text);
  box-shadow: 0 4px 14px rgba(0,0,0,.08);
  transition: background .18s ease, border-color .18s ease, transform .18s ease;
}
.chainlab-tool-button:hover, .device-preview-button:hover {
  background: var(--surface-light); border-color: var(--border-bright); transform: translateY(-1px);
}
.font-control-wrapper, .device-preview-control { position: relative; }
.font-control-panel, .device-preview-menu {
  border: 1px solid var(--border);
  border-radius: 14px;
  background: var(--surface);
  color: var(--text);
  box-shadow: 0 18px 50px rgba(0,0,0,.22);
  padding: 8px;
}
.font-control-panel button, .device-preview-option {
  border: 1px solid transparent; border-radius: 9px; color: var(--text); background: transparent;
}
.font-control-panel button:hover, .device-preview-option:hover,
.font-control-panel button.active, .device-preview-option-active {
  background: var(--surface-light); border-color: var(--border-bright);
}

/* Chat is viewport-fixed, independent of page/toolbar layout */
.chainlab-chat-launcher {
  position: fixed !important;
  right: max(22px, env(safe-area-inset-right)) !important;
  bottom: max(22px, env(safe-area-inset-bottom)) !important;
  z-index: 10000 !important;
  display: inline-flex; align-items: center; justify-content: center; gap: 9px;
  min-width: 112px; min-height: 48px; padding: 0 18px;
  border: 1px solid var(--border-bright); border-radius: 999px;
  background: var(--text); color: var(--background);
  box-shadow: 0 10px 32px rgba(0,0,0,.24);
  font-weight: 700; letter-spacing: .06em;
}
.chainlab-chat-launcher:hover { transform: translateY(-2px); }
.chainlab-chatbox {
  position: fixed !important;
  right: max(22px, env(safe-area-inset-right)) !important;
  bottom: calc(max(22px, env(safe-area-inset-bottom)) + 62px) !important;
  z-index: 9999 !important;
  width: min(390px, calc(100vw - 28px));
  max-height: min(620px, calc(100dvh - 110px));
  overflow: hidden;
  border: 1px solid var(--border);
  border-radius: 20px;
  background: var(--surface);
  color: var(--text);
  box-shadow: 0 24px 80px rgba(0,0,0,.3);
}
.chainlab-chat-header { border-bottom: 1px solid var(--border); background: var(--surface-light); }
.chainlab-chat-messages { color: var(--text); }
.chainlab-message { border: 1px solid var(--border); border-radius: 14px; }
.chainlab-message.assistant-message { background: var(--surface-light); color: var(--text); }
.chainlab-message.user-message { background: var(--cyan-dark); color: #fff; }
.chainlab-chat-quick button { border: 1px solid var(--border); border-radius: 999px; background: var(--surface-light); color: var(--text); }
.chainlab-chat-input { border-top: 1px solid var(--border); }
.chainlab-chat-input input { background: var(--background); color: var(--text); border: 1px solid var(--border); border-radius: 12px; }

@media (max-width: 600px) {
  .chainlab-utility-inner { width: calc(100% - 20px); }
  .chainlab-toolbar-center, .chainlab-tools { gap: 7px; }
  .chainlab-tool-button, .chainlab-toolbar-center .chainlab-device-button, .device-preview-button {
    width: 42px; min-width: 42px; height: 42px; min-height: 42px; border-radius: 11px;
  }
  .chainlab-chat-launcher { right: 14px !important; bottom: 14px !important; }
  .chainlab-chatbox { right: 12px !important; bottom: 72px !important; width: calc(100vw - 24px); }
}


/* =========================================================
   CHAINLAB LANDING PAGE — UIVERSE / DEXTER-ST BUTTON THEME
   Applied to existing landing-page CTA links without changing
   their hrefs, labels, or behavior.
   ========================================================= */

:root {
  --cl-button-radius: 999px;
  --cl-button-bg: #101010;
  --cl-button-border: rgba(255, 255, 255, 0.22);
  --cl-button-text: #f7f8fa;
  --cl-button-glow: 210deg;
  --cl-button-transition: 0.35s ease;
}

/* Button-shaped links on the landing page */
.site-header .nav-button,
.hero-actions .primary-button,
.hero-actions .secondary-button,
.company-content .company-button,
.about-content .primary-button,
.featured-content .primary-button,
.security-content .secondary-button,
.final-inner .large-button,
.featured-card .featured-button {
  position: relative;
  isolation: isolate;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.65rem;
  min-height: 48px;
  padding: 0.85rem 1.45rem;
  overflow: visible;
  border: 1px solid var(--cl-button-border);
  border-radius: var(--cl-button-radius);
  background: var(--cl-button-bg);
  color: var(--cl-button-text);
  font-family: inherit;
  font-size: 0.88rem;
  font-weight: 600;
  line-height: 1.15;
  letter-spacing: 0.045em;
  text-decoration: none;
  text-transform: uppercase;
  cursor: pointer;
  box-shadow:
    inset 0 1px 1px rgba(255, 255, 255, 0.22),
    inset 0 2px 3px rgba(255, 255, 255, 0.12),
    inset 0 7px 12px rgba(255, 255, 255, 0.035),
    0 -1px 1px rgba(0, 0, 0, 0.08),
    0 5px 12px rgba(0, 0, 0, 0.22),
    0 12px 28px rgba(0, 0, 0, 0.16);
  transition:
    box-shadow var(--cl-button-transition),
    border-color var(--cl-button-transition),
    background-color var(--cl-button-transition),
    color var(--cl-button-transition),
    transform var(--cl-button-transition);
}

/* Outer metallic rim */
.site-header .nav-button::before,
.hero-actions .primary-button::before,
.hero-actions .secondary-button::before,
.company-content .company-button::before,
.about-content .primary-button::before,
.featured-content .primary-button::before,
.security-content .secondary-button::before,
.final-inner .large-button::before,
.featured-card .featured-button::before {
  content: "";
  position: absolute;
  z-index: -1;
  inset: -5px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: inherit;
  background: linear-gradient(145deg, rgba(255,255,255,.13), rgba(0,0,0,.7));
  box-shadow:
    0 1px 1px rgba(255,255,255,.14),
    0 -2px 8px rgba(0,0,0,.45),
    inset 0 1px 2px rgba(255,255,255,.08);
  pointer-events: none;
  transition: box-shadow var(--cl-button-transition), opacity var(--cl-button-transition);
}

/* Soft top-edge reflection */
.site-header .nav-button::after,
.hero-actions .primary-button::after,
.hero-actions .secondary-button::after,
.company-content .company-button::after,
.about-content .primary-button::after,
.featured-content .primary-button::after,
.security-content .secondary-button::after,
.final-inner .large-button::after,
.featured-card .featured-button::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: linear-gradient(
    180deg,
    rgba(255,255,255,.28) 0%,
    rgba(170,210,255,.14) 18%,
    rgba(255,255,255,0) 54%
  );
  opacity: 0;
  pointer-events: none;
  transition: opacity var(--cl-button-transition);
}

/* Keep button content above the shine */
.site-header .nav-button > *,
.hero-actions .primary-button > *,
.hero-actions .secondary-button > *,
.company-content .company-button > *,
.about-content .primary-button > *,
.featured-content .primary-button > *,
.security-content .secondary-button > *,
.final-inner .large-button > *,
.featured-card .featured-button > * {
  position: relative;
  z-index: 1;
}

.site-header .nav-button:hover,
.hero-actions .primary-button:hover,
.hero-actions .secondary-button:hover,
.company-content .company-button:hover,
.about-content .primary-button:hover,
.featured-content .primary-button:hover,
.security-content .secondary-button:hover,
.final-inner .large-button:hover,
