}

.achievement-summary {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 16px;
  margin-top: 45px;
}

.achievement-summary-card {
  padding: 26px;
  border: 1px solid var(--achievement-border);
  border-radius: 14px;
  background: var(--card, rgba(255, 255, 255, 0.035));
}

.summary-label {
  display: block;
  margin-bottom: 18px;
  color: var(--muted-foreground, #999);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 1.5px;
}

.achievement-summary-card strong {
  font-size: clamp(28px, 4vw, 44px);
  font-weight: 900;
}

.achievement-summary-card strong span {
  color: var(--muted-foreground, #888);
  font-size: 20px;
}

.achievement-progress-track {
  width: 100%;
  height: 9px;
  margin-top: 28px;
  overflow: hidden;
  border-radius: 20px;
  background: rgba(128, 128, 128, 0.2);
}

.achievement-progress-fill {
  height: 100%;
  border-radius: inherit;
  background: var(--achievement-accent, #b7ff3c);
  transition: width 400ms ease;
}

.achievement-section {
  max-width: 1200px;
  margin: 0 auto;
  padding: 45px 0 85px;
}

.achievement-section-heading {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 35px;
}

.achievement-section-heading h2 {
  margin: 0;
  font-size: clamp(28px, 4vw, 48px);
  font-weight: 900;
  letter-spacing: -1.5px;
}

.achievement-count {
  padding: 10px 15px;
  border: 1px solid var(--achievement-border);
  border-radius: 50px;
  color: var(--achievement-accent, #b7ff3c);
  font-family: monospace;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 1px;
  white-space: nowrap;
}

.achievement-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 20px;
}

.achievement-card {
  position: relative;
  display: flex;
  min-height: 300px;
  flex-direction: column;
  padding: 27px;
  overflow: hidden;
  border: 1px solid var(--achievement-border);
  border-radius: 16px;
  background: var(--card, rgba(255, 255, 255, 0.035));
  transition:
    transform 200ms ease,
    border-color 200ms ease,
    opacity 200ms ease;
}

.achievement-card.earned {
  border-color: rgba(183, 255, 60, 0.45);
}

.achievement-card.earned:hover {
  transform: translateY(-5px);
  border-color: var(--achievement-accent, #b7ff3c);
}

.achievement-card.locked {
  opacity: 0.62;
}

.achievement-card-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 25px;
}

.achievement-icon {
  display: grid;
  width: 65px;
  height: 65px;
  place-items: center;
  border: 1px solid var(--achievement-border);
  border-radius: 16px;
  background: rgba(128, 128, 128, 0.08);
  font-size: 32px;
}

.achievement-status {
  padding: 7px 10px;
  border-radius: 50px;
  font-family: monospace;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 1px;
}

.status-earned {
  color: #101500;
  background: var(--achievement-accent, #b7ff3c);
}

.status-locked {
  border: 1px solid var(--achievement-border);
  color: var(--muted-foreground, #999);
}

.achievement-card h3 {
  margin: 0 0 12px;
  font-size: 18px;
  font-weight: 900;
  letter-spacing: 0.5px;
}

.achievement-description {
  margin: 0 0 25px;
  color: var(--muted-foreground, #a3a3a3);
  font-size: 14px;
  line-height: 1.7;
}

.achievement-requirement {
  margin-top: auto;
  padding-top: 18px;
  border-top: 1px solid var(--achievement-border);
}

.achievement-requirement span {
  color: var(--muted-foreground, #999);
  font-family: monospace;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1.5px;
}

.achievement-requirement p {
  margin: 9px 0 0;
  font-size: 12px;
  line-height: 1.6;
}

.achievement-earned-label {
  margin-top: 18px;
  color: var(--achievement-accent, #b7ff3c);
  font-family: monospace;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 1px;
}

.achievement-modules {
  max-width: 1200px;
  margin: 0 auto;
  padding: 75px 0 30px;
  border-top: 1px solid var(--achievement-border);
}

.achievement-modules h2 {
  font-size: clamp(45px, 7vw, 80px);
}

.achievement-module-links {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
  margin: 35px 0;
}

.achievement-module-links a {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  padding: 20px 22px;
  border: 1px solid var(--achievement-border);
  border-radius: 10px;
  color: inherit;
  font-size: 13px;
  font-weight: 800;
  letter-spacing: 1px;
  text-decoration: none;
  transition:
    border-color 200ms ease,
