.achievement-module-links a:hover {
  border-color: var(--achievement-accent, #b7ff3c);
  background: rgba(128, 128, 128, 0.06);
}

.achievement-module-links a span {
  color: var(--achievement-accent, #b7ff3c);
  font-size: 20px;
}

.achievement-main-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 20px;
  padding: 17px 24px;
  border: 1px solid var(--achievement-accent, #b7ff3c);
  border-radius: 8px;
  color: #101500;
  background: var(--achievement-accent, #b7ff3c);
  font-size: 12px;
  font-weight: 900;
  letter-spacing: 1px;
  text-decoration: none;
  transition:
