/* ============================================================
   LANGUAGE
   ============================================================ */

.language-selector {
  position: relative;

  display: flex;
  align-items: center;

  gap: 9px;

  height: 40px;

  padding: 0 4px;

  color: #172033;

  font-size: 15px;
  font-weight: 600;

  white-space: nowrap;
}

