  display: flex;
  align-items: center;
  justify-content: center;

  width: 22px;
  height: 22px;

  font-size: 19px;
}

.language-selector-label {
  display: none;
}

.language-selector select {
  appearance: none;
  -webkit-appearance: none;

  border: 0;
  outline: 0;

  background: transparent;

  color: #172033;

  font-family: inherit;

  font-size: 15px;
  font-weight: 600;

  cursor: pointer;

  padding: 5px 24px 5px 0;
}

.language-selector::after {
  content: "⌄";

  position: absolute;

  right: 2px;
  top: 50%;

  transform: translateY(-54%);

  pointer-events: none;

  color: #1b2739;

  font-size: 15px;
  font-weight: 700;
}

.language-selector select option {
  background: #ffffff;
  color: #111827;
}


