}

.about-content .primary-button {
  margin-top: 20px;
}

/* =========================================================
   4K HEADQUARTERS IMAGE
========================================================= */

.about-visual {
  position: relative;
  width: 100%;
}

.about-image-frame {
  position: relative;
  width: 100%;
  aspect-ratio: 16 / 9;
  overflow: hidden;
  border: 1px solid var(--border);
  background: #02060b;
}

.about-image-frame img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center center;
}

.about-image {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center center;
  opacity: 0.92;
}

.image-overlay {
  position: absolute;
  inset: auto 30px 30px;
  z-index: 2;
  padding: 28px;
  background: rgba(2, 6, 11, 0.85);
  border: 1px solid rgba(0, 200, 255, 0.3);
}

.image-overlay span {
  display: block;
  color: var(--cyan);
  font-size: calc((10px) * var(--cl-font-scale, 1));
  font-weight: 900;
  letter-spacing: 1.5px;
}

.image-overlay strong {
  display: block;
  margin-top: 8px;
  font-size: calc((31px) * var(--cl-font-scale, 1));
  font-weight: 900;
}

.image-overlay small {
  display: block;
  margin-top: 8px;
  color: var(--orange);
  font-size: calc((10px) * var(--cl-font-scale, 1));
  font-weight: 900;
  letter-spacing: 1px;
}

.about-values {
  margin-top: 80px;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  border-top: 1px solid var(--border);
}

.about-values > div {
  padding: 35px 35px 0 0;
  border-right: 1px solid var(--border);
}

.about-values > div:not(:first-child) {
  padding-left: 35px;
}

.about-values > div:last-child {
  border-right: 0;
}

.about-values span,
.number,
.path-number {
  color: var(--cyan);
  font-size: calc((11px) * var(--cl-font-scale, 1));
  font-weight: 900;
  letter-spacing: 1px;
}

.about-values h3,
.mission-grid h3,
.process-step h3 {
  margin: 14px 0 10px;
  font-size: calc((14px) * var(--cl-font-scale, 1));
  font-weight: 900;
}

.about-values p,
.mission-grid p,
.process-step p {
  margin: 0;
  color: var(--muted);
  line-height: 1.7;
  font-size: calc((13px) * var(--cl-font-scale, 1));
}

/* =========================================================
   MISSION
========================================================= */

.mission-section {
  padding: 100px 0 150px;
}

.mission-heading {
  margin-top: 40px;
  display: grid;
  grid-template-columns: 1.2fr 0.8fr;
  gap: 80px;
  align-items: end;
}

.mission-heading p {
