  }

  .hero-grid {
    width: calc(100% - 30px);
    display: block;
  }

  .hero-content {
    padding-bottom: 0;
  }

  .hero-content h1 {
    font-size: calc((clamp(58px, 17vw, 90px)) * var(--cl-font-scale, 1));
