  }

  .orbit-one {
    width: 400px;
    height: 150px;
  }

  .orbit-two {
    width: 310px;
    height: 120px;
  }

  .orbit-three {
    width: 230px;
    height: 90px;
  }

  .floating-card {
    min-width: auto;
    padding: 12px;
    font-size: calc((8px) * var(--cl-font-scale, 1));
  }

  .card-learn {
    left: 0;
    top: 18%;
  }

  .card-blockchain {
    right: 0;
    top: 22%;
  }

  .card-security {
    left: 3%;
    bottom: 17%;
  }

  .card-community {
    right: 0;
    bottom: 14%;
  }

  .hero-features,
  .stats-grid {
    width: calc(100% - 30px);
  }

  .hero-features {
    grid-template-columns: 1fr;
  }

  .feature-item {
    border-right: 0;
    border-bottom: 1px solid var(--border);
  }

  .feature-item:last-child {
    border-bottom: 0;
  }

  .stats-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .stat {
    border-bottom: 1px solid var(--border);
  }

  .stat:nth-child(2n) {
    border-right: 0;
  }

  .stat:last-child {
    grid-column: 1 / -1;
    border-right: 0;
  }

  .about-section,
  .mission-section,
  .paths-section,
  .process-section,
  .security-section,
  .testimonials-section,
  .faq-section {
    width: calc(100% - 30px);
    padding-top: 90px;
    padding-bottom: 90px;
  }

  .about-grid,
  .mission-heading,
  .security-section,
  .faq-section {
    grid-template-columns: 1fr;
    gap: 45px;
  }

  .about-content h2,
  .mission-heading h2,
  .paths-section h2,
  .process-section h2,
  .featured-content h2,
  .security-content h2,
  .testimonials-section h2,
  .faq-heading h2,
  .final-inner h2 {
    font-size: calc((45px) * var(--cl-font-scale, 1));
    letter-spacing: -2px;
  }

  /*
    Keep the headquarters image at its natural 16:9
    proportion on mobile as well.
  */
  .about-image-frame {
    width: 100%;
    aspect-ratio: 16 / 9;
    min-height: 0;
  }

  .about-image {
    width: 100%;
    height: 100%;
    object-fit: cover;
  }

  .about-values {
    grid-template-columns: 1fr;
  }

  .about-values > div,
  .about-values > div:not(:first-child) {
    padding: 30px 0;
    border-right: 0;
    border-bottom: 1px solid var(--border);
  }

  .mission-grid {
    grid-template-columns: 1fr;
  }

  .mission-grid article,
  .mission-grid article:nth-child(2) {
    border-right: 0;
    border-bottom: 1px solid var(--border);
  }

  .mission-grid article:last-child {
    border-bottom: 0;
  }

  .paths-grid {
    grid-template-columns: 1fr;
  }

  .path-card {
    min-height: 390px;
  }

  .section-heading-row {
    display: block;
  }

  .section-heading-row .text-link {
    display: inline-block;
    margin-top: 25px;
  }

  .process-grid {
    grid-template-columns: 1fr;
  }

  .process-step {
    border-right: 0;
    border-bottom: 1px solid var(--border);
  }

  .featured-section {
    display: block;
  }

  .featured-image {
    min-height: 470px;
  }

  .featured-content {
    padding: 70px 25px;
    border-left: 0;
    border-top: 1px solid var(--border);
  }

  .security-visual {
    height: 390px;
  }

  .ring-one {
    width: 350px;
    height: 350px;
  }

  .ring-two {
    width: 270px;
    height: 270px;
  }

  .ring-three {
    width: 190px;
    height: 190px;
  }

  .testimonial-grid {
    grid-template-columns: 1fr;
  }

  .footer-grid {
    grid-template-columns: 1fr 1fr;
    gap: 45px;
  }

  .footer-brand {
    grid-column: 1 / -1;
  }

  .footer-bottom {
    flex-direction: column;
  }
}

@media (max-width: 500px) {
  .nav-button {
    display: none;
  }

  .hero-actions {
    flex-direction: column;
  }

  .hero-actions a {
    width: 100%;
  }

  .hero-visual {
    min-height: 400px;
  }

  .coin-wrapper {
    width: 280px;
    height: 280px;
  }

  .floating-card {
    transform: scale(0.8);
  }

  .eyebrow {
    font-size: calc((9px) * var(--cl-font-scale, 1));
  }

  /*
    Headquarters image remains 16:9.
    Do NOT use a fixed height here.
  */
  .about-image-frame {
    width: 100%;
    aspect-ratio: 16 / 9;
    min-height: 0;
  }

  .about-image {
    width: 100%;
    height: 100%;
    object-fit: cover;
  }

  .featured-center {
    width: 180px;
    height: 180px;
  }

  .featured-center strong {
    font-size: calc((30px) * var(--cl-font-scale, 1));
  }

  .footer-grid {
    grid-template-columns: 1fr;
  }

  .footer-brand {
    grid-column: auto;
  }

  .site-footer {
    padding-left: 25px;
    padding-right: 25px;
  }
}

