.featured-card .featured-image {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: #05070b;
  border: 0;
}

.featured-card .featured-photo {
  position: absolute;
  inset: 0;

  width: 100%;
  height: 100%;

  display: block;

  object-fit: cover;
  object-position: center center;

  image-rendering: auto;

  transform: translateZ(0);
  backface-visibility: hidden;

  filter:
    contrast(1.05)
    saturate(1.04)
    brightness(1.02);

  transition:
    transform 1s cubic-bezier(0.2, 0.7, 0.2, 1);
}

/* =========================================================
   DARK GRADIENT FOR TEXT
========================================================= */

.featured-card .featured-image-overlay {
  position: absolute;
  inset: 0;
  z-index: 1;

  background:
    linear-gradient(
      90deg,
      rgba(5, 7, 11, 0.05) 0%,
      rgba(5, 7, 11, 0.05) 30%,
      rgba(5, 7, 11, 0.18) 42%,
      rgba(5, 7, 11, 0.52) 56%,
      rgba(5, 7, 11, 0.88) 70%,
      #05070b 86%,
      #05070b 100%
    );

  pointer-events: none;
}

/* =========================================================
