========================================================= */

.featured-card .featured-image-vignette {
  position: absolute;
  inset: 0;
  z-index: 1;

  background:
    linear-gradient(
      180deg,
      rgba(0, 0, 0, 0.15) 0%,
      transparent 25%,
      transparent 72%,
      rgba(0, 0, 0, 0.45) 100%
    );

  pointer-events: none;
}

