.hero-section {
  position: relative;
  width: calc(100% - 80px);
  max-width: 1600px;
  margin: 70px auto 100px;
  padding: 0;
  overflow: hidden;

  border: 1px solid rgba(255, 255, 255, 0.10);
  border-radius: 32px;

  background:
    radial-gradient(
      circle at 78% 35%,
      rgba(0, 126, 255, 0.12),
      transparent 32%
    ),
    radial-gradient(
      circle at 20% 70%,
      rgba(0, 80, 160, 0.08),
      transparent 35%
    ),
    #03070d;

  box-shadow:
    0 30px 100px rgba(0, 0, 0, 0.45),
    inset 0 1px 0 rgba(255, 255, 255, 0.025);
}

/* Subtle technical grid inside the card */

.hero-section::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 0.45;

  background-image:
    linear-gradient(
      rgba(0, 174, 255, 0.035) 1px,
      transparent 1px
    ),
    linear-gradient(
      90deg,
      rgba(0, 174, 255, 0.035) 1px,
      transparent 1px
    );

  background-size: 44px 44px;
}

/* Keep all hero content above the grid */

.hero-section > * {
  position: relative;
  z-index: 1;
}


/* =========================================================
   MAIN HERO
   ========================================================= */

.hero-grid {
  min-height: 720px;
  padding: 70px 70px 40px;

  display: grid;
  grid-template-columns: minmax(0, 0.95fr) minmax(0, 1.25fr);
  gap: 45px;
  align-items: center;
}


