  letter-spacing: -0.065em;
  font-weight: 900;

  color: #f7f8fb;
}

.hero-content h1 span {
  color: #ffad00;
}

.hero-description {
  max-width: 700px;

  margin-top: 46px;

  color: #aab8ca;

  font-size: calc((18px) * var(--cl-font-scale, 1));
  line-height: 1.7;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;

  margin-top: 34px;
}

.hero-note {
  max-width: 650px;

  margin-top: 32px;

  color: #71839a;

  font-size: calc((14px) * var(--cl-font-scale, 1));
  line-height: 1.7;
}


