/* =========================================================
   CHAINLAB — PROFESSIONAL GLOBAL HEADER / FOOTER
   Reference-style navigation system
   ========================================================= */

:root {
  --chainlab-nav-height: 72px;
  --chainlab-blue: #176cff;
  --chainlab-blue-hover: #0b5be0;
  --chainlab-light-bg: #ffffff;
  --chainlab-light-text: #172033;
  --chainlab-light-muted: #526174;
  --chainlab-light-border: #d9e0e8;
  --chainlab-dark-bg: #02070d;
  --chainlab-dark-surface: #050c14;
  --chainlab-dark-text: #f4f7fb;
  --chainlab-dark-muted: #9aaabd;
  --chainlab-dark-border: #1b3044;
}

/* ---------- HEADER SHELL ---------- */

.chainlab-header {
  position: fixed !important;
  top: 0 !important;
  left: 0 !important;
  right: 0 !important;
  width: 100% !important;
  height: var(--chainlab-nav-height) !important;
  min-height: var(--chainlab-nav-height) !important;
  z-index: 2147483000 !important;

  padding: 0 !important;
  margin: 0 !important;

  background: rgba(255,255,255,.96) !important;
  border-bottom: 1px solid var(--chainlab-light-border) !important;

  box-shadow: 0 5px 24px rgba(18,32,51,.055);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
}

.chainlab-header-inner {
  width: min(100% - 48px, 1480px) !important;
  height: 100% !important;
  min-height: 0 !important;
  margin: 0 auto !important;
  padding: 0 !important;

  display: flex !important;
  align-items: center !important;
  gap: 14px !important;

  white-space: nowrap;
}

/* ---------- LEFT CONTROLS ---------- */

.header-controls {
  display: flex !important;
  align-items: center !important;
  flex: 0 0 auto !important;
}

.header-controls .chainlab-tools {
  position: static !important;
  display: flex !important;
  align-items: center !important;
  gap: 8px !important;
}

/* Aa and theme buttons */
.chainlab-header .chainlab-tool-button,
.chainlab-header .chainlab-theme-toggle {
  width: 38px !important;
  height: 38px !important;
  min-width: 38px !important;
  min-height: 38px !important;
  padding: 0 !important;

  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;

  border: 1px solid var(--chainlab-light-border) !important;
  border-radius: 50% !important;

  background: #fff !important;
  color: var(--chainlab-light-text) !important;

  box-shadow: 0 4px 14px rgba(18,32,51,.07) !important;

  font-family: inherit !important;
  font-weight: 700 !important;
  letter-spacing: 0 !important;

  transition: border-color .2s ease, background .2s ease,
              color .2s ease, transform .2s ease,
              box-shadow .2s ease !important;
}

.chainlab-header .chainlab-tool-button:hover,
.chainlab-header .chainlab-theme-toggle:hover {
  transform: translateY(-1px) !important;
  border-color: #aeb9c7 !important;
  box-shadow: 0 7px 18px rgba(18,32,51,.10) !important;
}

.chainlab-header .chainlab-theme-icon,
.chainlab-header .chainlab-tool-button svg {
  width: 17px !important;
  height: 17px !important;
}

/* ---------- DIVIDERS ---------- */

.chainlab-header .header-divider {
  width: 1px !important;
  height: 28px !important;
  margin: 0 4px !important;
  flex: 0 0 1px !important;
  background: #dce2e9 !important;
}

/* ---------- LANGUAGE ---------- */

.chainlab-header .language-selector {
  position: relative !important;
  z-index: 100000 !important;

  height: 42px !important;
  min-height: 42px !important;
  padding: 0 12px !important;

  display: inline-flex !important;
  align-items: center !important;
  gap: 8px !important;

  border: 1px solid var(--chainlab-light-border) !important;
  border-radius: 10px !important;

  background: #fff !important;
  color: var(--chainlab-light-text) !important;

  box-shadow: 0 3px 12px rgba(18,32,51,.035) !important;
}

.chainlab-header .language-selector-icon {
  width: 18px !important;
  height: 18px !important;
  font-size: 15px !important;
}

.chainlab-header .language-selector-label {
  display: inline !important;
  color: var(--chainlab-light-text) !important;
  font-size: 13px !important;
  font-weight: 700 !important;
}

.chainlab-header .language-selector select {
  max-width: 112px !important;
  min-height: 30px !important;
  padding: 0 18px 0 0 !important;
  border: 0 !important;
  background: transparent !important;
  color: var(--chainlab-light-text) !important;
  font-size: 13px !important;
  font-weight: 650 !important;
}

.chainlab-header .language-selector::after {
  right: 2px !important;
  color: #172033 !important;
}

/* ---------- BRAND ---------- */

.chainlab-header .brand {
  display: inline-flex !important;
  align-items: center !important;
  flex: 0 0 auto !important;

  margin: 0 6px 0 2px !important;

  color: #07558c !important;
  font-size: 24px !important;
  line-height: 1 !important;
  font-weight: 900 !important;
  letter-spacing: -1.7px !important;
}

/* ---------- MAIN NAV ---------- */

.chainlab-header .main-nav {
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;

  flex: 1 1 auto !important;
  min-width: 0 !important;

  gap: clamp(18px, 2.1vw, 34px) !important;
  margin: 0 !important;
}

.chainlab-header .main-nav a {
  position: relative !important;

  display: inline-flex !important;
  align-items: center !important;

  height: var(--chainlab-nav-height) !important;

  color: var(--chainlab-light-text) !important;
  background: transparent !important;

  font-size: 13px !important;
  font-weight: 750 !important;
  letter-spacing: -.01em !important;

  text-decoration: none !important;

  transition: color .2s ease !important;
}

.chainlab-header .main-nav a::after {
  content: "" !important;
  position: absolute !important;

  left: 50% !important;
  right: auto !important;
  bottom: 12px !important;

  width: 28px !important;
  height: 2px !important;

  transform: translateX(-50%) scaleX(0) !important;
