   ========================================================= */

.chainlab-hero-brand {
  width: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  margin: 0 auto 52px;
  position: relative;
  z-index: 20;
}

.chainlab-hero-brand-name {
  display: block;
  font-family:
    "Arial Black",
    "Helvetica Neue",
    Arial,
    sans-serif;
  font-size: clamp(72px, 11vw, 180px);
  font-weight: 950;
  line-height: 0.82;
  letter-spacing: -0.075em;
  white-space: nowrap;

  background: linear-gradient(
    100deg,
    #ffffff 0%,
    #dffaff 22%,
    #00e5ff 48%,
    #168cff 70%,
    #a855f7 100%
  );

  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  color: transparent;

  filter:
    drop-shadow(0 0 18px rgba(0, 229, 255, 0.16))
    drop-shadow(0 0 42px rgba(92, 80, 255, 0.10));

  animation: chainlabHeroBrandIn 0.85s ease-out both;
}

.chainlab-hero-brand-byline {
  margin-top: 20px;

  font-family:
    "Helvetica Neue",
    Arial,
    sans-serif;

  font-size: clamp(11px, 1.15vw, 17px);
  font-weight: 800;
  line-height: 1;
  letter-spacing: 0.48em;
  text-transform: uppercase;

  color: #00d9ff;

  text-shadow: 0 0 18px rgba(0, 217, 255, 0.22);

  animation: chainlabHeroBylineIn 0.85s ease-out 0.12s both;
}

.chainlab-hero-brand::after {
  content: "";
  width: min(230px, 34vw);
  height: 2px;
  margin-top: 24px;

  background: linear-gradient(
    90deg,
    transparent,
    #00e5ff 25%,
    #168cff 55%,
    #a855f7 75%,
    transparent
  );

  box-shadow: 0 0 16px rgba(0, 217, 255, 0.22);
  opacity: 0.9;
}

@keyframes chainlabHeroBrandIn {
  from {
    opacity: 0;
    transform: translateY(24px) scale(0.96);
    filter: blur(8px);
  }

  to {
    opacity: 1;
    transform: translateY(0) scale(1);
    filter:
      drop-shadow(0 0 18px rgba(0, 229, 255, 0.16))
      drop-shadow(0 0 42px rgba(92, 80, 255, 0.10));
  }
}

@keyframes chainlabHeroBylineIn {
  from {
    opacity: 0;
    transform: translateY(10px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* Keep the brand above the existing hero decoration. */
