  letter-spacing: .08em;
}

.learning-overview-master .overview-text-link:hover {
  background: rgba(0,217,255,.10);
  border-color: rgba(0,217,255,.55);
}

.learning-overview-master .overview-content-grid + .overview-content-grid .overview-card {
  min-height: 235px;
}

.learning-overview-master .overview-bottom-line {
  margin-top: 26px;
  padding: 22px 24px;
  border: 1px solid rgba(0,217,255,.20);
  border-radius: 16px;
  background: rgba(0,217,255,.035);
}

.learning-overview-master .overview-bottom-line p {
  color: #b5c0cd;
  opacity: 1;
}

.learning-overview-master .overview-bottom-line strong {
  color: #fff;
}

.learning-overview-master .hero-features {
  width: 100%;
  margin: clamp(34px,5vw,56px) 0 0;
  display: grid;
  grid-template-columns: repeat(4, minmax(0,1fr));
  overflow: hidden;
  border: 1px solid rgba(71,121,173,.26);
  border-radius: 18px;
  background: rgba(3,10,18,.46);
}

.learning-overview-master .feature-item {
  min-height: 160px;
  padding: 27px 23px;
  border-right: 1px solid rgba(71,121,173,.20);
}

.learning-overview-master .feature-item:last-child {
  border-right: 0;
}

.learning-overview-master .feature-icon {
  color: #00d9ff;
  text-shadow: 0 0 22px rgba(0,217,255,.45);
}

.learning-overview-master .feature-item h3 {
  color: #f4f8fc;
  letter-spacing: .02em;
}

.learning-overview-master .feature-item p {
  color: #8998aa;
}

.learning-overview-master .stats-grid {
  width: 100%;
  margin: 18px 0 0;
  overflow: hidden;
  display: grid;
  grid-template-columns: repeat(5, minmax(0,1fr));
  border: 1px solid rgba(71,121,173,.26);
  border-radius: 16px;
  background: rgba(2,8,15,.60);
}

.learning-overview-master .stat {
  min-height: 112px;
  padding: 18px 12px;
  border-right: 1px solid rgba(71,121,173,.20);
}

.learning-overview-master .stat:last-child {
  border-right: 0;
}

.learning-overview-master .stat strong {
  color: #00d9ff;
  font-size: clamp(22px,2.2vw,32px);
  font-weight: 900;
  letter-spacing: -.04em;
}

.learning-overview-master .stat:nth-child(5) strong {
  color: #c38cff;
}

.learning-overview-master .stat span {
  color: #7f90a4;
  font-size: 9px;
  letter-spacing: .12em;
}

html[data-theme="light"] .learning-overview-master {
  border-color: rgba(20,80,130,.18);
  background:
    radial-gradient(circle at 50% 0%, rgba(0,170,220,.06), transparent 34%),
    linear-gradient(145deg, #fff, #f5f9fc);
  box-shadow: 0 25px 70px rgba(30,55,80,.10), inset 0 1px 0 rgba(255,255,255,.9);
}

html[data-theme="light"] .learning-overview-master .overview-heading-group h2,
html[data-theme="light"] .learning-overview-master .overview-card h3,
html[data-theme="light"] .learning-overview-master .feature-item h3,
html[data-theme="light"] .learning-overview-master .overview-bottom-line strong {
  color: #101820;
}

html[data-theme="light"] .learning-overview-master .overview-intro,
html[data-theme="light"] .learning-overview-master .overview-card p,
html[data-theme="light"] .learning-overview-master .feature-item p,
html[data-theme="light"] .learning-overview-master .overview-bottom-line p {
  color: #566676;
}

html[data-theme="light"] .learning-overview-master .overview-card {
  background: #fff !important;
  border-color: rgba(30,90,135,.14) !important;
}

html[data-theme="light"] .learning-overview-master .hero-features,
html[data-theme="light"] .learning-overview-master .stats-grid {
  background: rgba(244,248,251,.9);
  border-color: rgba(30,90,135,.14);
}

@media (max-width: 1100px) {
  .learning-overview-master {
    width: min(100% - 42px, 1000px);
    padding: 38px;
  }

  .learning-overview-master .overview-content-grid {
    grid-template-columns: repeat(2, minmax(0,1fr));
  }

  .learning-overview-master .hero-features {
    grid-template-columns: repeat(2, minmax(0,1fr));
  }

  .learning-overview-master .feature-item:nth-child(2) {
    border-right: 0;
  }

  .learning-overview-master .feature-item:nth-child(-n+2) {
    border-bottom: 1px solid rgba(71,121,173,.20);
  }
}

@media (max-width: 760px) {
  .learning-overview-master {
    width: calc(100% - 28px);
    margin-top: 56px;
    margin-bottom: 56px;
    padding: 25px 18px;
    border-radius: 22px;
  }

  .learning-overview-master .overview-heading-group {
    margin-bottom: 42px;
  }

  .learning-overview-master .overview-heading-group h2 {
    font-size: clamp(32px,9vw,48px);
  }

  .learning-overview-master .overview-content-grid {
    grid-template-columns: 1fr;
    gap: 12px;
  }

  .learning-overview-master .overview-content-grid + .overview-content-grid {
    margin-top: 12px;
  }

  .learning-overview-master .overview-card,
  .learning-overview-master .overview-content-grid + .overview-content-grid .overview-card {
    min-height: auto;
  }

  .learning-overview-master .hero-features {
    grid-template-columns: 1fr;
  }

  .learning-overview-master .feature-item,
  .learning-overview-master .feature-item:nth-child(2) {
    border-right: 0;
    border-bottom: 1px solid rgba(71,121,173,.20);
  }

  .learning-overview-master .feature-item:last-child {
    border-bottom: 0;
  }

  .learning-overview-master .stats-grid {
    grid-template-columns: repeat(2,minmax(0,1fr));
  }

  .learning-overview-master .stat:nth-child(2),
  .learning-overview-master .stat:nth-child(4) {
    border-right: 0;
  }

  .learning-overview-master .stat:nth-child(-n+3) {
    border-bottom: 1px solid rgba(71,121,173,.20);
  }

  .learning-overview-master .overview-bottom-line {
    align-items: flex-start;
  }
}

/* =========================================================
   FINAL CTA — DARK MODE VISIBILITY FIX
   ========================================================= */

html[data-theme="dark"] .final-section .final-inner .section-label {
  color: #00d9ff !important;
  opacity: 1 !important;
}

html[data-theme="dark"] .final-section .final-inner h2,
html[data-theme="dark"] .final-section .final-inner h2 span {
  color: #ffffff !important;
  opacity: 1 !important;
  visibility: visible !important;
  text-shadow:
    0 0 18px rgba(0, 217, 255, 0.12),
    0 2px 12px rgba(0, 0, 0, 0.5);
}

html[data-theme="dark"] .final-section .final-inner p {
  color: #d7e0e8 !important;
  opacity: 1 !important;
  visibility: visible !important;
}

html[data-theme="dark"] .final-section .final-inner .large-button {
  color: #ffffff !important;
  background: #111c28 !important;
  border-color: #00d9ff !important;
}

html[data-theme="dark"] .final-section .final-inner .large-button span {
  color: #00d9ff !important;
}

/* Keep the entire CTA visible above decorative layers */
html[data-theme="dark"] .final-section .final-inner,
html[data-theme="dark"] .final-section .final-inner > * {
  position: relative;
  z-index: 10;
}

/* =========================================================
   COMPANY VALUES — REMOVE OUTER BORDERS
   ========================================================= */

.about-values {
  border: none !important;
  box-shadow: none !important;
  background: transparent !important;
}

.about-values > div {
  border: none !important;
  outline: none !important;
  box-shadow: none !important;
  background: transparent !important;
}

/* Remove decorative border lines if present */
.about-values::before,
.about-values::after,
.about-values > div::before,
.about-values > div::after {
  display: none !important;
  border: none !important;
  box-shadow: none !important;
}

/* Keep the content clean and readable */
.about-values h3,
.about-values p,
.about-values span {
  border: none !important;
}

/* Dark mode */
html[data-theme="dark"] .about-values,
html[data-theme="dark"] .about-values > div {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
}

/* Light mode */
html[data-theme="light"] .about-values,
html[data-theme="light"] .about-values > div {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
}